import type { BankQuestion } from "@/lib/bank";

/** Verbal Ability for Placements (Placement Aptitude): 570 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "apt-verbal-placement-1", "question": "Choose the word closest in meaning to the word in capitals as used in the sentence.\nThe auditor was METICULOUS in checking every invoice.", "options": ["Thorough", "Careless", "Generous", "Hasty"], "answer": 0, "explanation": "Meticulous means showing great attention to detail, i.e. thorough. Careless and hasty are its opposites.", "difficulty": "easy", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-2","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nThe company promised a TRANSPARENT hiring process.","options":["Clear","Opaque","Open","Fair"],"answer":1,"explanation":"Transparent here means open and easy to see into; the opposite is opaque (hidden, unclear). Clear and open are synonyms.","difficulty":"easy","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-3","question":"Fill in the blank.\nShe has been working with the analytics team ___ 2019.","options":["from","for","since","by"],"answer":2,"explanation":"With the present perfect continuous, 'since' marks a point in time (2019) and 'for' marks a length of time (for six years).","difficulty":"easy","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-5","question":"Fill in the blank with the correct preposition.\nRahul is good ___ solving puzzles, so he enjoys the reasoning round.","options":["at","in","on","with"],"answer":0,"explanation":"The fixed expression is 'good at' something. 'Good in' is a common error; 'good with' is used for people or tools (good with children, good with numbers).","difficulty":"easy","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-6","question":"Choose the one word for: a person who is new to a job or activity and has little experience.","options":["Veteran","Novice","Expert","Mentor"],"answer":1,"explanation":"A novice is a beginner. A veteran has long experience and a mentor guides others.","difficulty":"easy","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-7","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nEach of the interns / have been given / a separate laptop for the project. / No error","options":["Each of the interns","a separate laptop for the project","have been given","No error"],"answer":2,"explanation":"'Each of' takes a singular verb: 'Each of the interns has been given'. The plural noun 'interns' just before the verb is the trap.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-8","question":"Fill in the blank.\nDespite repeated reminders, the vendor failed to ___ with the terms of the contract.","options":["obey","respect","follow","comply"],"answer":3,"explanation":"'Comply with' is the correct collocation. Obey, follow and respect take a direct object without 'with' (obey the terms, follow the terms).","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-9","question":"Choose the meaning of the idiom in capitals.\nWith revenue falling, the new manager decided to BITE THE BULLET and close two loss-making branches.","options":["Face a painful situation with courage","Make a hasty, careless decision","Put off a difficult choice","Blame someone else for a problem"],"answer":0,"explanation":"To bite the bullet is to accept something unpleasant but necessary and get on with it. 'Put off a difficult choice' is the opposite.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-10","question":"Choose the word that best replaces the phrasal verb in capitals.\nThe product launch was CALLED OFF because of the budget cuts.","options":["Postponed","Cancelled","Announced","Approved"],"answer":1,"explanation":"To call off is to cancel. Postponed would be 'put off', the usual confusion.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-11","question":"Choose the correct passive form of: \"The committee will announce the results tomorrow.\"","options":["The results would be announced by the committee tomorrow.","The results will announce by the committee tomorrow.","The results will be announced by the committee tomorrow.","The results are announced by the committee tomorrow."],"answer":2,"explanation":"Future simple active (will announce) becomes 'will be + past participle' in the passive. The tense must not change to 'would' or 'are'.","difficulty":"easy","source":"TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-12","question":"Choose the correct indirect form of: He said, \"I met the recruiter yesterday.\"","options":["He said that I had met the recruiter the day before.","He said that he has met the recruiter the previous day.","He said that he met the recruiter yesterday.","He said that he had met the recruiter the previous day."],"answer":3,"explanation":"With a past reporting verb, simple past (met) shifts to past perfect (had met), 'yesterday' becomes 'the previous day' and 'I' becomes 'he'.","difficulty":"easy","source":"TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-13","question":"Fill in the blank.\nThe new leave policy will ___ all permanent employees from next month.","options":["affect","infect","effect","afflict"],"answer":0,"explanation":"'Affect' is the verb meaning to have an influence on. 'Effect' as a verb means to bring about (effect a change), and 'afflict' means to cause suffering.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-14","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: As a result, many new hires spend their first week waiting for access.\nQ: Most companies issue laptops and system logins only after the joining formalities are complete.\nR: A few firms have fixed this by setting up accounts a week before the joining date.\nS: These formalities can take several days.","options":["SQPR","QSPR","QPSR","RQSP"],"answer":1,"explanation":"Q introduces the practice, S ('These formalities') follows from Q, P gives the result of that delay, and R ('fixed this') offers the solution. QPSR breaks the 'These formalities' link.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-15","question":"Choose the correct option to fill the blank.\nIf I ___ the team lead, I would change the release schedule.","options":["was","had","were","am"],"answer":2,"explanation":"An unreal present condition takes the subjunctive 'were' for all persons: 'If I were…, I would…'.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-16","question":"You missed a report deadline for a client. Which is the most appropriate opening line for your formal email?","options":["Please note that the delay was not our fault.","As you may know, deadlines are sometimes unrealistic.","Hey, sorry the report's late!","We sincerely apologise for the delay in delivering the report, which was due on 3 March."],"answer":3,"explanation":"A formal client email opens by owning the problem politely and specifically. The others are too casual or defensive.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-17","question":"Choose the word closest in meaning to the word in capitals.\nThe CEO was CANDID about the quarter's losses at the town hall.","options":["Frank","Vague","Cautious","Cheerful"],"answer":0,"explanation":"Candid means open and honest, i.e. frank. Cautious and vague suggest holding back, which is the opposite.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-18","question":"Choose the word opposite in meaning to the word in capitals.\nThe first draft of the proposal was VERBOSE, so the manager asked for a one-page version.","options":["Detailed","Concise","Lengthy","Wordy"],"answer":1,"explanation":"Verbose means using more words than needed; its opposite is concise. Wordy and lengthy are synonyms; the context (one-page version) confirms it.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-19", "question": "Fill in the blank.\nNeither the manager nor the employees ___ aware of the change in policy.", "options": ["has been", "was", "were", "is"], "answer": 2, "explanation": "With 'neither … nor', the verb agrees with the nearer subject. 'Employees' is plural, so 'were'.", "difficulty": "moderate", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-20","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nWhich of the following best states the main idea of the passage?","options":["Warehouses are more profitable than factories.","Lean inventories have no real advantages.","Suppliers often halt production deliberately.","Many firms are giving up some cost efficiency in exchange for protection against supply disruptions."],"answer":3,"explanation":"The passage describes the shift from pure lean inventory to keeping buffers, accepting higher costs for resilience. It grants that lean cut storage costs, so 'no advantages' is wrong.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-21","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe number of applicants / for the trainee post / have increased this year. / No error","options":["have increased this year","for the trainee post","The number of applicants","No error"],"answer":0,"explanation":"'The number of' is singular (it refers to one number): 'has increased'. Compare 'A number of applicants have applied', where the meaning is plural.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-22", "question": "Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHardly had the presentation begun / than the projector / stopped working. / No error", "options": ["Hardly had the presentation begun", "than the projector", "stopped working", "No error"], "answer": 1, "explanation": "'Hardly' and 'scarcely' pair with 'when' (or 'before'), not 'than'. Only 'no sooner' takes 'than'.", "difficulty": "moderate", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-23","question":"Choose the pair of words that best fills the blanks.\nThe proposal was ___ by the board because it was financially ___.","options":["shelved … viable","rejected … sound","rejected … unviable","approved … unviable"],"answer":2,"explanation":"'Because' needs a reason that fits the action: a proposal is rejected because it is unviable. The other pairs set up a contradiction.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-24","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nThe first and last sentences are fixed.\n1. The company's first product was a simple invoicing tool for small shops.\nP: Encouraged, the founders added payroll and tax filing.\nQ: Within two years, it had more than ten thousand paying users.\nR: The bundle, however, proved too complex for the shops it was built for.\nS: Many customers cancelled and went back to the basic tool sold by a rival.\n6. The founders eventually split the product back into separate, simpler apps.","options":["QPSR","PQRS","QRPS","QPRS"],"answer":3,"explanation":"Q (success) explains 'Encouraged' in P; P adds features, which R calls 'the bundle'; S gives the consequence, which leads to the fix in sentence 6.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-25", "question": "Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: This is because a written record lets everyone return to what was agreed.\nQ: Teams that work across time zones often rely on written updates rather than calls.\nR: Without such a record, the same question tends to be answered again and again, which is why many teams make the written update compulsory.\nS: It also lets a colleague who was asleep during the discussion catch up the next morning.", "options": ["QPSR", "QSPR", "QPRS", "PQSR"], "answer": 0, "explanation": "Q states the practice, P gives the first reason ('This is because'), S adds a second benefit ('It also'), and R closes with what happens without the record and the resulting rule.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-26","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: He listed the exact steps that had failed and the fix the team had applied.\nQ: After the outage, the engineering head sent a short note to all clients.\nR: He ended by naming a date by which a permanent solution would be in place.\nS: He began with an apology, without excuses.","options":["QSRP","QSPR","QPSR","SQPR"],"answer":1,"explanation":"Q introduces the note. 'Began' (S), the details (P) and 'ended' (R) mark the order of its contents.","difficulty":"hard","source":"TCS NQT verbal pattern"},
  {"id": "apt-verbal-placement-27", "question": "Read the passage and answer the question.\n\nPassage: When the firm moved half its support staff to remote work, managers expected productivity to fall. Instead, ticket resolution times improved by about a tenth within six months. Exit interviews, however, told a different story: newer employees reported feeling isolated and said they had learned the job more slowly without colleagues nearby. The company has since asked recent hires to spend three days a week in the office, while experienced staff may continue to work from home.\n\nWhich of the following can be inferred from the passage?", "options": ["The company plans to bring every employee back to the office.", "Exit interviews showed that all remote employees felt isolated.", "The company believes that working near colleagues helps new employees learn the job.", "Remote work lowered the productivity of experienced staff."], "answer": 2, "explanation": "Asking only recent hires to come in, after they reported learning more slowly alone, shows the company links in-person contact with learning. Productivity rose, so the second option contradicts the passage; the third overgeneralises from 'newer employees'.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-28","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nAs used in the passage, the word 'resilience' most nearly means:","options":["The ability to lower holding costs","The speed at which parts are delivered","The ability to keep operating through disruptions","A refusal to change suppliers"],"answer":2,"explanation":"Firms accept higher holding costs as the price of resilience, i.e. of not having lines stand idle when a supplier fails. Lower holding costs is the thing they give up.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-29","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nThe tone of the passage is best described as:","options":["Sharply critical of lean methods","Enthusiastic about large warehouses","Dismissive of the critics","Balanced and explanatory"],"answer":3,"explanation":"The author explains the benefit of lean inventories, their weakness, the response, and both the critics' and supporters' views without taking sides.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-30","question":"Read the passage and answer the question.\n\nPassage: A mid-sized software company banned internal meetings on Wednesdays. The rule was meant to give engineers long stretches of uninterrupted time. After a quarter, the number of code changes shipped on Wednesdays rose sharply, but so did the volume of internal chat messages, as staff tried to settle by text what they would once have settled in a ten-minute call. Some team leads now argue that the policy did not remove coordination costs; it only moved them.\n\nWhich of the following is the most suitable title for the passage?","options":["Meeting-free Wednesdays: Time Gained, Coordination Moved","The End of Office Meetings","Why Chat Tools Should Be Banned","How Engineers Ship Code"],"answer":0,"explanation":"The passage reports more shipped code (time gained) and more chat (coordination moved). The other titles are too broad or argue something the passage does not.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-31","question":"Choose the meaning of the idiom in capitals.\nThe contractor CUT CORNERS on the new office, and the roof began leaking within a month.","options":["Negotiated a lower price","Did the work cheaply by ignoring proper standards","Finished the work ahead of schedule","Reduced the size of the building"],"answer":1,"explanation":"To cut corners is to save time or money by skipping what should be done properly; the leaking roof confirms the negative sense.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-32","question":"Choose the correct replacement for the part in capitals.\nNot only the interns but also the manager WERE LATE for the review.","options":["have been late","were late (no change)","was late","are late"],"answer":2,"explanation":"With 'not only … but also', the verb agrees with the nearer subject, 'the manager' (singular): 'was late'.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-33","question":"In which sentence is the word 'principal' or 'principle' used correctly?","options":["She refused to sign, as a matter of principal.","Our company's guiding principals are honesty and speed.","The principle reason for the delay was a shortage of staff.","The loan's principal will be repaid over five years."],"answer":3,"explanation":"Principal = main, or the capital sum of a loan; principle = a rule or belief. So 'principal reason', 'matter of principle' and 'guiding principles' are the correct forms.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-34","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe committee has submitted / its final report / to the board of directors. / No error","options":["No error","its final report","to the board of directors","The committee has submitted"],"answer":0,"explanation":"The committee acts as one body here, so the singular 'has' and 'its' are correct and consistent. Changing to 'have … their' would only be needed if members acted separately.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-35","question":"Fill in the blank.\nThe new billing software is ___ the old one in every respect.","options":["more superior than","superior to","superior than","more superior to"],"answer":1,"explanation":"Latin comparatives such as superior, inferior, senior and junior take 'to', not 'than', and never 'more' (they are already comparative).","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-36", "question": "Choose the meaning of the word in capitals as used in the sentence.\nThe board will ADDRESS the shareholders' concerns at the annual meeting.", "options": ["Find the location of", "Deliver a speech to", "Deal with", "Write a letter to"], "answer": 2, "explanation": "To address a concern or problem is to deal with it. 'Address' meaning to speak to applies to people (address the shareholders), not to concerns.", "difficulty": "moderate", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-37","question":"Choose the correct replacement for the part in capitals.\nThe team lead, along with her colleagues, ARE ATTENDING the summit in Pune.","options":["were attending","are attending (no change)","have been attending","is attending"],"answer":3,"explanation":"Phrases like 'along with', 'as well as' and 'together with' do not make the subject plural. The subject is 'the team lead': 'is attending'.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-38","question":"Choose the best rewrite of: \"Walking into the office, the printer was making a strange noise.\"","options":["As I walked into the office, I heard the printer making a strange noise.","The printer, walking into the office, was making a strange noise.","Walking into the office, a strange noise was made by the printer.","Walking into the office, the printer's strange noise was heard."],"answer":0,"explanation":"The original has a dangling modifier: it says the printer was walking. Only the first rewrite gives 'walking' a real person as its doer.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-39","question":"Choose the option that makes the sentence grammatically parallel.\nThe role requires analysing data, to prepare reports and the presentation of findings to clients.","options":["the analysis of data, to prepare reports and presenting findings to clients","analysing data, preparing reports and presenting findings to clients","analysing data, to prepare reports and presenting findings to clients","to analyse data, preparing reports and the presentation of findings to clients"],"answer":1,"explanation":"Items in a list should share one form. Three -ing forms (analysing, preparing, presenting) are parallel; the others mix -ing, infinitive and noun forms.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-40","question":"Which is the most suitable rewrite of \"We'll get back to you ASAP\" for a formal letter to a client?","options":["We will get back to you real quick.","We shall revert at the earliest, no worries.","We will respond to your query as soon as possible.","Will get back ASAP, thanks!"],"answer":2,"explanation":"Formal register avoids contractions, abbreviations like ASAP and casual phrases like 'no worries' or 'real quick'.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id": "apt-verbal-placement-41", "question": "Choose the word opposite in meaning to the word in capitals.\nAfter three rounds, the salary negotiations reached an IMPASSE.", "options": ["Standstill", "Stalemate", "Deadlock", "Breakthrough"], "answer": 3, "explanation": "An impasse is a situation in which no progress is possible. Deadlock, stalemate and standstill are synonyms; a breakthrough is its opposite.", "difficulty": "moderate", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-42","question":"Fill in the blank.\nThe audit revealed several ___ between the invoices raised and the payments recorded.","options":["discrepancies","desperations","dispensations","discriminations"],"answer":0,"explanation":"A discrepancy is a mismatch between two things that should agree, such as invoices and payments. The others look similar but mean something else.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-43","question":"Fill in the blank.\nAnanya is one of those analysts who ___ never missed a deadline.","options":["has","have","had been","is"],"answer":1,"explanation":"The relative pronoun 'who' refers to 'analysts' (the group she belongs to), so the verb is plural: 'who have never missed'. 'Has' wrongly agrees with 'one'.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-44","question":"How many of the following sentences are grammatically correct?\n(i) The data are being analysed by the research team.\n(ii) Scarcely had we reached the venue than it started raining.\n(iii) It is high time we leave for the airport.\n(iv) Neither of the two proposals is acceptable to the board.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(i) and (iv) are correct: 'data' may take a plural verb, and 'neither of' takes a singular verb. (ii) is wrong because 'scarcely' pairs with 'when', not 'than'; (iii) is wrong because 'It is high time' takes the past form, 'we left'. So two are correct.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-45", "question": "Fill in the blank.\nThe client insisted that the revised report ___ submitted before Friday.", "options": ["was", "is", "be", "will be"], "answer": 2, "explanation": "Verbs of demand such as insist, recommend and suggest take the subjunctive (base form) in the that-clause: 'that the report be submitted'.", "difficulty": "hard", "source": "Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-46", "question": "Fill in the blank.\nDouble-check the figures lest you ___ an error in the final invoice.", "options": ["would make", "will make", "do not make", "should make"], "answer": 3, "explanation": "'Lest' means 'for fear that' and is followed by 'should' + base verb (or the bare base form). It is already negative, so 'do not make' creates a double negative.", "difficulty": "moderate", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-47","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: Yet the same feature that makes it cheap also makes it fragile.\nQ: Cloud storage has made it cheap for start-ups to keep every file they create.\nR: A single misconfigured setting can expose millions of records to anyone who looks.\nS: Files sit on shared servers that are reached over the public internet.","options":["QSPR","QPSR","QSRP","SQPR"],"answer":0,"explanation":"Q opens the topic; S explains how it works; P refers back to that 'feature' (shared, internet-reached servers); R gives the concrete risk. In QPSR, P's 'same feature' has nothing to point to.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-48","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nThe first and last sentences are fixed.\n1. Interview panels often favour candidates who answer quickly.\nP: Slower answers, by contrast, are sometimes read as a lack of knowledge.\nQ: Quick answers sound confident, and confidence is easily mistaken for competence.\nR: Several firms now give candidates a few minutes to think before they respond.\nS: In technical roles, however, the first answer is frequently not the best one.\n6. Early results suggest that this small change improves the quality of hires.","options":["QSPR","QPSR","SQPR","PQSR"],"answer":1,"explanation":"Q explains why quick answers win; P ('by contrast') covers slow answers; S ('however') challenges that bias; R gives the response, which sentence 6 calls 'this small change'.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-49","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: The second, and less obvious, is that it changes what customers expect.\nQ: A discount offered every month has two effects.\nR: The first is a short-term rise in sales.\nS: Once shoppers learn that a sale is always coming, they stop buying at full price.","options":["QRSP","RQPS","QRPS","QPRS"],"answer":2,"explanation":"Q announces two effects; R gives the first, P the second, and S explains the second. S cannot come before P because it illustrates the changed expectation.","difficulty":"hard","source":"TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-50","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: Most of them, however, never get past the first chapter.\nQ: Every January, sales of self-improvement books rise sharply.\nR: Publishers know this and time their biggest releases accordingly.\nS: The books are bought with good intentions, often as gifts to oneself.","options":["QSPR","RQSP","QSRP","QRSP"],"answer":3,"explanation":"R's 'this' and 'accordingly' point to the January sales spike in Q, so R follows Q directly. S describes the buying, and P ('however', 'them' = the books) gives the contrast.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-51","question":"Read the passage and answer the question.\n\nPassage: When the firm moved half its support staff to remote work, managers expected productivity to fall. Instead, ticket resolution times improved by about a tenth within six months. Exit interviews, however, told a different story: newer employees reported feeling isolated and said they had learned the job more slowly without colleagues nearby. The company has since asked recent hires to spend three days a week in the office, while experienced staff may continue to work from home.\n\nWhich of the following, if true, would most weaken the reason for the company's new policy on recent hires?","options":["New hires who worked from the office learned the job no faster than new hires who worked from home.","Several newer employees who left cited isolation as a reason.","Office rents in the city have risen over the past year.","Experienced staff resolved tickets faster from home than from the office."],"answer":0,"explanation":"The policy rests on the idea that recent hires learn faster in the office. Evidence that they do not learn faster there removes that reason. The last option strengthens the policy; the others are irrelevant to it.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-52","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nEach of the following is supported by the passage EXCEPT:","options":["Keeping a buffer of components raises holding costs.","Most firms have abandoned lean inventory methods entirely.","A halt at a single supplier could stop assembly lines.","Lean inventories reduced storage costs."],"answer":1,"explanation":"The passage says many firms now keep 'a modest buffer of critical components', which is a partial change, not abandoning lean methods entirely. The other three are stated directly.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-53","question":"Read the passage and answer the question.\n\nPassage: A mid-sized software company banned internal meetings on Wednesdays. The rule was meant to give engineers long stretches of uninterrupted time. After a quarter, the number of code changes shipped on Wednesdays rose sharply, but so did the volume of internal chat messages, as staff tried to settle by text what they would once have settled in a ten-minute call. Some team leads now argue that the policy did not remove coordination costs; it only moved them.\n\nThe team leads' argument assumes which of the following?","options":["The rise in code changes was caused by the extra chat messages.","Meetings on other days became shorter.","The extra chat messages on Wednesdays were largely doing the coordination work that meetings used to do.","Engineers prefer chat to meetings."],"answer":2,"explanation":"To say the costs were 'moved', the leads must assume the new messages replace the coordination that meetings did, not unrelated chatter. If the messages were social, their argument fails.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-54","question":"Read the passage and answer the question.\n\nPassage: A retailer found that customers who left a complaint and received a reply within an hour were more likely to buy again than customers who never complained at all. The finding surprised the board, which had treated complaints purely as a cost. The marketing head cautions against reading too much into it: customers who bother to complain may simply be more engaged with the brand to begin with.\n\nThe marketing head's point is best described as which of the following?","options":["Complaints should be ignored because they are costly.","Customers who never complain are the most loyal.","Quick replies to complaints reduce repeat sales.","The link between complaining and buying again may reflect customers who were already more loyal, not the effect of the quick reply."],"answer":3,"explanation":"The head warns that complainers may differ from non-complainers from the start (more engaged), so the reply may not be what causes the repeat purchases. This is a correlation-versus-cause caution.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-55","question":"Read the passage and answer the question.\n\nPassage: A retailer found that customers who left a complaint and received a reply within an hour were more likely to buy again than customers who never complained at all. The finding surprised the board, which had treated complaints purely as a cost. The marketing head cautions against reading too much into it: customers who bother to complain may simply be more engaged with the brand to begin with.\n\nWhich of the following, if true, would most strengthen the marketing head's caution?","options":["Customers who complained but got no reply for a week also bought again more often than customers who never complained.","Customers who got a quick reply bought again more often than complainers who got a slow reply.","The retailer cut its complaint-handling budget last year.","Customers who received a reply within an hour rated the service highly."],"answer":0,"explanation":"If even ignored complainers buy again more than non-complainers, the engagement of complainers, not the quick reply, explains the pattern. The last option supports the reply effect, so it weakens the caution.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id": "apt-verbal-placement-56", "question": "Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe CEO, as well as the directors, / were present / when the merger was announced. / No error", "options": ["The CEO, as well as the directors,", "were present", "when the merger was announced", "No error"], "answer": 1, "explanation": "'As well as the directors' is a parenthetical add-on; the subject is 'The CEO' (singular), so 'was present'.", "difficulty": "hard", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-57","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nBeing a rainy day, / the offsite was postponed / to Friday. / No error","options":["to Friday","the offsite was postponed","Being a rainy day,","No error"],"answer":2,"explanation":"As written, 'Being a rainy day' describes 'the offsite', which is absurd. It needs its own subject: 'It being a rainy day, the offsite was postponed'.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-58","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nBetween you and I, / the appraisal results will be announced / only after the board meeting. / No error","options":["No error","the appraisal results will be announced","only after the board meeting","Between you and I,"],"answer":3,"explanation":"A preposition (between) takes the object case: 'between you and me'. 'You and I' sounds formal, which is why it slips through.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-59","question":"Which of the following sentences is correct?","options":["Of the two candidates, Priya is the more qualified.","Priya is the more qualified of all the candidates.","Of the two candidates, Priya is the most qualified.","Priya is more qualified than any candidate on the shortlist."],"answer":0,"explanation":"Two items take the comparative (the more qualified). 'Than any candidate' must be 'than any other candidate' when Priya is on the shortlist herself; 'of all' needs the superlative.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-60","question":"Fill in the blank.\nBy the time the auditors arrive tomorrow, we ___ the reconciliation.","options":["would complete","will have completed","have completed","will complete"],"answer":1,"explanation":"An action finished before a future point ('by the time … arrive') takes the future perfect: 'will have completed'.","difficulty":"hard","source":"TCS NQT verbal pattern"},
  {"id": "apt-verbal-placement-61", "question": "Fill in the blank.\nHad the team tested the patch on the staging server, the outage ___.", "options": ["will have been avoided", "had been avoided", "would have been avoided", "would be avoided"], "answer": 2, "explanation": "'Had the team tested' is an inverted third conditional (= If the team had tested), whose result clause is 'would have + past participle'.", "difficulty": "hard", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-62","question":"Which sentence uses 'fewer' and 'less' correctly?","options":["Our team has fewer staff but less problems.","There were less complaints this quarter than last.","Fewer water was used after the new taps were fitted.","We received fewer applications this year, and the hiring budget is also less."],"answer":3,"explanation":"'Fewer' goes with countable plurals (applications, complaints, problems) and 'less' with uncountable nouns (budget as an amount, water).","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-63","question":"Fill in the blank.\nThe CFO's statement was meant to ___ fears of layoffs among the staff.","options":["allay","ally","allure","alley"],"answer":0,"explanation":"To allay fears is to reduce or calm them. Alley (a lane), ally (to join with) and allure (to attract) are look-alikes.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-64", "question": "In how many of the following sentences is the idiom used correctly?\n(i) The new hire is still learning the ropes in her first month.\n(ii) After a bitter quarrel, the two teams let the cat out of the bag and worked well together.\n(iii) The manager gave the proposal the green light, so the project was cancelled.\n(iv) We will cross that bridge when we come to it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(i) learning the ropes = learning how a job is done, correct. (iv) = deal with a problem only when it arises, correct. (ii) letting the cat out of the bag means revealing a secret, not making peace (that is 'bury the hatchet'). (iii) a green light means approval, which contradicts 'cancelled'. So two.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-65","question":"In which sentence is the word used INCORRECTLY?","options":["Please be discreet when discussing the client's finances.","The manager made a discrete enquiry about the candidate's notice period.","The process is broken into discrete steps, each with its own owner.","The survey responses were grouped into five discrete categories."],"answer":1,"explanation":"Discreet = careful not to attract attention; discrete = separate and distinct. A quiet enquiry is a 'discreet' enquiry.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-66","question":"Choose the pair of words that best fills the blanks.\nHer ___ explanation, far from clarifying the issue, only ___ the confusion.","options":["lucid … dispelled","convoluted … dispelled","convoluted … compounded","lucid … compounded"],"answer":2,"explanation":"'Far from clarifying' tells us the explanation failed, so it was convoluted (overly complicated), and the confusion grew (compounded). 'Lucid … compounded' breaks the logic of the first blank.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-67","question":"Which of the following sentences uses 'no sooner' correctly?","options":["No sooner the CEO announced the bonus than the shares rose.","No sooner had the CEO announced the bonus then the shares rose.","No sooner had the CEO announced the bonus when the shares rose.","No sooner did the CEO announce the bonus than the shares rose."],"answer":3,"explanation":"'No sooner' needs inversion (did/had + subject) and pairs with 'than'. The others use 'when', drop the inversion, or confuse 'than' with 'then'.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-68","question":"Fill in the blank.\nThe jury ___ divided in their opinions, so the verdict was delayed.","options":["were","is","was","has been"],"answer":0,"explanation":"A collective noun takes a plural verb when its members act as individuals; 'divided' and 'their opinions' show that here. 'Was' would clash with 'their'.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-69","question":"Fill in the blanks.\nThe manager was angry ___ his assistant ___ the delay in the report.","options":["on … at","with … for","upon … with","to … about"],"answer":1,"explanation":"One is angry with a person and angry for (or about) a thing. The other pairs misuse the prepositions.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-70", "question": "Choose the word opposite in meaning to the word in capitals.\nThe new backup protocol is meant to MITIGATE the risk of data loss.", "options": ["Insure", "Alleviate", "Aggravate", "Assess"], "answer": 2, "explanation": "Mitigate means to make less severe; aggravate means to make worse. Alleviate is a synonym, the usual trap.", "difficulty": "hard", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-71", "question": "Choose the word closest in meaning to the word in capitals.\nThe meeting was OSTENSIBLY about budgets, but most of the time went on the reorganisation.", "options": ["Actually", "Mainly", "Secretly", "Seemingly"], "answer": 3, "explanation": "Ostensibly means 'as it appears or is claimed', i.e. seemingly; the 'but' shows the real purpose was different. 'Actually' is close to the opposite.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-72","question":"Choose the correct indirect form of: She said to me, \"Will you send me the file tomorrow?\"","options":["She asked me if I would send her the file the next day.","She told me whether I would send her the file the next day.","She asked me would I send her the file the next day.","She asked me if I will send her the file tomorrow."],"answer":0,"explanation":"A yes/no question is reported with asked + if/whether, statement word order, will → would, me → her and tomorrow → the next day. 'Told' cannot introduce a question.","difficulty":"moderate","source":"TCS NQT verbal pattern"},
  {"id": "apt-verbal-placement-73", "question": "Choose the correct passive form of: \"Who has approved this expense?\"", "options": ["By who has this expense been approved?", "By whom was this expense approved?", "By whom this expense has been approved?", "By whom has this expense been approved?"], "answer": 3, "explanation": "'Who' as the doer becomes 'by whom'; the present perfect stays 'has been + past participle' with question word order. The second option changes the tense, the third loses the question order, and the fourth uses 'who' after a preposition.", "difficulty": "moderate", "source": "TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-74","question":"Choose the most concise and professional rewrite of:\n\"I am writing this email to you in order to inform you that the meeting which was scheduled for Monday has been moved to Tuesday due to the fact that the client is unavailable.\"","options":["I am writing to inform you that the meeting scheduled for Monday has been moved to Tuesday due to the fact that the client is unavailable.","The Monday meeting has been moved to Tuesday because the client is unavailable.","FYI, Monday's meeting is now Tuesday, client can't make it.","Meeting moved."],"answer":1,"explanation":"The best version keeps every fact (which meeting, new day, reason) and removes padding ('in order to', 'due to the fact that'). The third is still wordy, the second is too casual, and the last drops information.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-75","question":"Which sentence uses 'who' or 'whom' correctly?","options":["The analyst whom I believed was on leave joined the call.","To who should the invoice be addressed?","The analyst who I believed was on leave joined the call.","The client whom requested the refund has written again."],"answer":2,"explanation":"In the first, 'who' is the subject of 'was on leave' ('I believed' is an inserted clause), so 'who' is right and 'whom' in the second is wrong. 'Whom requested' needs the subject form, and 'to who' needs the object form 'whom'.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-76","question":"Choose the word closest in meaning to the word in capitals.\nThe new intern was DILIGENT in documenting every test case.","options":["Hard-working","Careless","Reluctant","Talkative"],"answer":0,"explanation":"Diligent means showing steady, careful effort, i.e. hard-working. Careless is its opposite.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-77","question":"Choose the word opposite in meaning to the word in capitals.\nThe manager gave a VAGUE reply when asked about the appraisal dates.","options":["Unclear","Precise","Rude","Brief"],"answer":1,"explanation":"Vague means not clearly stated; its opposite is precise. Unclear is a synonym, and a reply can be brief yet still clear or vague.","difficulty":"easy","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-78","question":"Fill in the blank with the correct preposition.\nDue to the server migration, the client demo has been postponed ___ next Monday.","options":["at","with","to","from"],"answer":2,"explanation":"An event is postponed TO a later date. “Postponed at/with/from” is not idiomatic.","difficulty":"easy","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-79","question":"Choose the one word for: a person or company that is unable to pay its debts.","options":["Insolent","Illiterate","Introvert","Insolvent"],"answer":3,"explanation":"Insolvent means unable to pay debts. Insolent (rude and disrespectful) is the look-alike trap.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-80","question":"Fill in the blank.\nI ___ in this company since 2021, and I have worked on three products so far.","options":["have been working","am working","was working","work"],"answer":0,"explanation":"“Since 2021” marks an action that began in the past and continues now, which needs the present perfect continuous: have been working. “Am working since” is a common Indian-English error.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-81","question":"Fill in the blanks with the correct articles.\n___ European client and ___ Indian vendor signed the contract yesterday.","options":["An, an","A, an","An, a","A, a"],"answer":1,"explanation":"Articles follow the sound, not the letter: “European” begins with a “yoo” (consonant) sound, so “a European”; “Indian” begins with a vowel sound, so “an Indian”.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-82","question":"Choose the meaning of the idiom in capitals.\nThe pilot failed badly, so the product team had to GO BACK TO THE DRAWING BOARD.","options":["Ask the design team for more drawings","Give up the project for good","Start planning again from the beginning","Blame the designers for the failure"],"answer":2,"explanation":"“Go back to the drawing board” means to start again after a plan has failed. It does not mean abandoning the project or literal drawings.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-83","question":"Choose the correct passive form of: \"The QA team is testing the new release.\"","options":["The new release is tested by the QA team.","The new release has been tested by the QA team.","The new release was being tested by the QA team.","The new release is being tested by the QA team."],"answer":3,"explanation":"Present continuous active (is testing) becomes present continuous passive: is being + past participle. The other options change the tense.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-84","question":"Choose the correct indirect form of: He said, \"I will submit the report tomorrow.\"","options":["He said that he would submit the report the next day.","He said that he will submit the report tomorrow.","He said that I would submit the report the next day.","He said that he would have submitted the report tomorrow."],"answer":0,"explanation":"With a past reporting verb, “will” becomes “would”, “I” becomes “he”, and “tomorrow” becomes “the next day”. Keeping “will … tomorrow” ignores the backshift.","difficulty":"easy","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-85","question":"Which word is spelt correctly?","options":["Occurence","Occurrence","Ocurrence","Occurrance"],"answer":1,"explanation":"“Occurrence” has double c, double r, and ends in -ence. The other spellings drop a letter or use -ance.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-86","question":"Fill in the blank.\nThe new analytics dashboard ___ the existing reporting tools rather than replacing them.","options":["compliments","completes","complements","competes"],"answer":2,"explanation":"“Complement” means to complete or go well with something; “compliment” means to praise. A dashboard that works alongside existing tools complements them.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-87","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nNeither of the two proposals were / accepted by the board, as both / exceeded the approved budget. / No error","options":["Neither of the two proposals were","accepted by the board, as both","exceeded the approved budget.","No error"],"answer":0,"explanation":"“Neither of” takes a singular verb: “Neither of the two proposals was accepted”. The plural “proposals” right before the verb is the trap.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-88","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe manager, along with his team, / are attending the client meeting / in Bengaluru this week. / No error","options":["The manager, along with his team,","are attending the client meeting","in Bengaluru this week.","No error"],"answer":1,"explanation":"The subject is “The manager”; a phrase starting with “along with” does not make it plural. So it should be “is attending”.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-89","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHardly had the server restarted / when the alerts started / flooding the dashboard. / No error","options":["Hardly had the server restarted","when the alerts started","flooding the dashboard.","No error"],"answer":3,"explanation":"The sentence is correct: “Hardly … when” is the right pair, and the inversion “had the server restarted” is required after “Hardly”. Changing “when” to “than” would create an error (“than” goes with “no sooner”).","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-90","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nIf he would have checked the logs, / he could have found / the bug much earlier. / No error","options":["If he would have checked the logs,","he could have found","the bug much earlier.","No error"],"answer":0,"explanation":"In a third conditional the if-clause takes the past perfect: “If he had checked the logs, he could have found …”. “Would have” belongs only in the main clause.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-91","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: As a result, many teams now insist that every change be reviewed by at least one other engineer.\nQ: Studies of software projects have repeatedly found that defects caught early are far cheaper to fix than those found later.\nR: Code review is one of the cheapest ways of catching such defects before they reach production.\nS: However, reviews work only if reviewers have the time to read each change carefully.","options":["RQPS","QPRS","QRPS","SQRP"],"answer":2,"explanation":"Q states the general finding; R introduces code review as a way to catch “such defects” (refers back to Q); P gives the result (“As a result”); S adds a qualification with “However”. QPRS puts the result before its cause.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-92","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: For twenty years, the bakery had relied entirely on customers who walked past its door.\nQ: Today, online orders make up more than half of its revenue.\nR: Orders that once came only from the neighbourhood began arriving from across the city.\nS: During the lockdown, with footfall gone, the owner reluctantly listed her cakes on a delivery app.","options":["PSRQ","PRSQ","SPRQ","PSQR"],"answer":0,"explanation":"P sets the background, S is the turning point (lockdown, listing online), R is the immediate effect, and Q (“Today”) is the present outcome. PRSQ has orders arriving from across the city before the bakery went online.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-93","question":"Choose the word that best fills the blank.\nAlthough the startup’s revenue grew rapidly, its ___ spending on marketing meant that it was still losing money.","options":["frugal","prudent","negligible","unchecked"],"answer":3,"explanation":"“Although revenue grew … still losing money” needs a word for excessive spending: unchecked. Frugal, prudent and negligible all describe careful or small spending, which would not explain the losses.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-94","question":"Choose the pair of words that best fills the blanks.\nThe auditor’s report was ___: it praised the team’s diligence but ___ the lack of proper documentation.","options":["glowing, overlooked","scathing, ignored","neutral, applauded","mixed, criticised"],"answer":3,"explanation":"The colon promises a description that the second half explains: praise “but” criticism = a mixed report. “Glowing … overlooked” loses the contrast signalled by “but”; “scathing” clashes with “praised”.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-95","question":"Choose the best replacement for the sentence, or the option that corrects it.\n\"The reason why he resigned is because he was overworked.\"","options":["The reason he resigned is that he was overworked.","The reason why he resigned was because of overwork.","The reason he resigned is because of he was overworked.","No improvement needed"],"answer":0,"explanation":"“The reason … is because” is redundant, since “reason” already means cause; the standard form is “The reason … is that …”. The other rewrites keep the redundancy or break the grammar.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-96","question":"In which sentence is the word \"discreet\" or \"discrete\" used correctly?","options":["The signal is sampled at discreet intervals.","Please be discreet when discussing the restructuring with the team.","She made a discrete enquiry about the vacancy.","The project was split into three discreet phases."],"answer":1,"explanation":"“Discreet” means careful not to cause embarrassment or reveal secrets; “discrete” means separate or distinct. Intervals and phases are discrete; an enquiry made quietly is discreet.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-97","question":"Read the passage and answer the question.\n\nPassage: Many firms measure developer productivity by counting the lines of code written. The metric is easy to collect, but it rewards the wrong behaviour: a developer who deletes 500 redundant lines while keeping every feature working has arguably done more useful work than one who adds 500 new ones, yet the metric scores the first as negative. Worse, once engineers know they are measured this way, they tend to write longer code than necessary.\n\nWhich of the following can be inferred from the passage?","options":["Deleting code is always more valuable than writing new code.","Lines of code are difficult to count accurately.","A metric can change the very behaviour it is meant to measure.","Firms should stop measuring developer productivity altogether."],"answer":2,"explanation":"The last sentence says engineers write longer code once they know the metric, i.e. measurement changes behaviour. “Always more valuable” over-generalises a single example; the passage says the metric is EASY to collect; abandoning all measurement goes beyond the text.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-98","question":"A senior client proposes a review meeting on Friday, but you will be at another client’s site all day. Which reply is the most appropriate?","options":["Friday does not work for me. Let me know another day.","Sorry, I am very busy on Friday so I cannot come, please understand.","I will try to join on Friday if I get some time between my other meetings.","Thank you for the invitation. I will be at another client site on Friday; could we meet on Monday or Tuesday instead? I am happy to work around your schedule."],"answer":3,"explanation":"The best reply thanks the client, gives a brief reason, and proposes concrete alternatives while staying flexible. The others are curt, vague and apologetic without a solution, or non-committal in a way that risks a no-show.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-99","question":"The first and last sentences of a paragraph are fixed. Arrange P, Q, R and S in between to form a coherent paragraph.\n1: A large online retailer once noticed that its sales dipped sharply every Friday evening.\nP: Then someone laid the sales graph over the server-load graphs.\nQ: The cause turned out to be a weekly database backup that started at 7 p.m.\nR: Moving the backup to 3 a.m. made the dip disappear within a week.\nS: Engineers first suspected a marketing problem, but the campaigns ran the same on every day.\n6: The lesson: before blaming customers, check your own systems.","options":["SQPR","PSQR","SPRQ","SPQR"],"answer":3,"explanation":"S is the first (wrong) hypothesis; P (“Then”) is the next step in the investigation; Q reveals what that comparison showed; R is the fix, which leads to the lesson in 6. SQPR reveals the cause before the step that found it.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-100","question":"Three of the four sentences below form a coherent paragraph. Which sentence does NOT belong?\nA. Cloud providers bill most services by the hour or even by the second.\nB. This lets a startup pay only for the computing it actually uses instead of buying servers upfront.\nC. Many startups also rent their office space by the month rather than buying property.\nD. The flip side is that a forgotten test server can quietly run up a large bill.","options":["A","B","D","C"],"answer":3,"explanation":"A, B and D form a tight argument about cloud billing: how it works, its benefit (“This lets …”), and its risk (“The flip side …” refers to the pay-per-use model). C shifts to office rent; it shares the pay-as-you-go idea but breaks the topic, and D cannot follow it.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-101","question":"Read the passage and answer the question.\n\nPassage: The vendor’s proposal promises \"zero downtime\", \"infinite scalability\" and \"fully automated security\". Each phrase is attractive; none is defined. The document runs to forty pages, yet it never says what happens when a data centre fails, how costs grow with traffic, or who is accountable when an automated control misses an attack. Perhaps the vendor has good answers. The proposal, however, gives us no way of knowing.\n\nThe author’s attitude towards the proposal is best described as:","options":["Sceptical","Enthusiastic","Indifferent","Contemptuous"],"answer":0,"explanation":"The author questions undefined claims and lists missing details, yet concedes the vendor “perhaps” has answers — measured doubt, i.e. scepticism. Contemptuous is too strong given that concession; indifferent ignores the detailed critique.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-102","question":"Read the passage and answer the question.\n\nPassage: A food-delivery company found that customers who ordered at least three times in their first week were far more likely to still be using the app six months later. The product team therefore proposed giving every new user three free deliveries in their first week, expecting long-term retention to rise.\n\nThe proposal depends on which assumption?","options":["Free deliveries cost the company very little.","Ordering often in the first week helps cause long-term use, rather than merely signalling users who would have stayed anyway.","Every new user will place exactly three orders in the first week.","Six months is the most useful period over which to measure retention."],"answer":1,"explanation":"The data shows only a correlation. The plan works only if early ordering itself drives retention; if keen users simply order more, free deliveries would not change who stays. Cost, exact order counts and the measurement window are not required for the reasoning.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-103","question":"Choose the sentence that best completes the paragraph.\nAutomated tests catch regressions quickly, but they check only what someone thought to test. Exploratory testing, in which a tester probes the software without a script, often finds the bugs that nobody anticipated. ___","options":["Automated testing should therefore be abandoned.","Exploratory testing is therefore cheaper than automation.","The two approaches therefore complement each other rather than compete.","Most bugs are therefore found by customers after release."],"answer":2,"explanation":"The paragraph gives each approach a distinct strength, so the natural conclusion is that they work together. Abandoning automation contradicts the first sentence; cost and customer-found bugs are never discussed.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-104","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nScarcely had the review meeting begun / than the fire alarm / went off on the third floor. / No error","options":["Scarcely had the review meeting begun","than the fire alarm","went off on the third floor.","No error"],"answer":1,"explanation":"“Scarcely” (like “hardly”) pairs with “when”, not “than”: “Scarcely had the meeting begun when the fire alarm went off.” “Than” belongs with “no sooner”. The inversion in the first part is correct.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-105","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nBeing a public holiday, / the office remained / closed all day. / No error","options":["the office remained","Being a public holiday,","closed all day.","No error"],"answer":1,"explanation":"The opening participle has no proper subject: as written, it says the office was a public holiday. Correct: “It being a public holiday, the office remained closed” or “As it was a public holiday, …”.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-106","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe selection panel comprises of / five senior engineers / and two external experts. / No error","options":["five senior engineers","and two external experts.","No error","The selection panel comprises of"],"answer":3,"explanation":"“Comprise” takes a direct object: “The panel comprises five senior engineers …”, or “is composed of / consists of”. “Comprises of” is a common error.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-107","question":"Fill in the blank.\nThe attrition numbers are alarming; it is high time the company ___ its leave policy.","options":["revised","revises","revise","has revised"],"answer":0,"explanation":"“It is high time” is followed by the past simple (a subjunctive use) to show that the action is overdue: “it is high time the company revised …”. The present forms sound natural but are grammatically wrong here.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-108","question":"How many of the following sentences are grammatically correct?\n(i) Every one of the servers was patched last night.\n(ii) The CEO, as well as the directors, were present at the meeting.\n(iii) Neither the laptops nor the charger was delivered on time.\n(iv) One of my colleague is on leave today.","options":["1","2","3","4"],"answer":1,"explanation":"(i) Correct: “every one” is singular. (ii) Wrong: “as well as” does not add to the subject, so “The CEO … was present”. (iii) Correct: with “neither … nor”, the verb agrees with the nearer subject, “charger” → was. (iv) Wrong: “one of my colleagues”. Two are correct.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-109","question":"Choose the word closest in meaning to the word in capitals.\nThe vendor’s OBSEQUIOUS emails, full of flattery and endless apologies, began to irritate the CTO.","options":["Insolent","Sincere","Servile","Obscure"],"answer":2,"explanation":"Obsequious means excessively eager to please or obey — servile. Insolent is the opposite; obscure is a sound-alike trap.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-110","question":"Which sentence uses \"lie\" or \"lay\" correctly?","options":["After the night shift yesterday, she lay down for an hour.","After the night shift yesterday, she laid down for an hour.","Please lie the files on my desk before you leave.","The signed documents have laid untouched for weeks."],"answer":0,"explanation":"“Lie” (recline, no object) has past “lay” and participle “lain”; “lay” (put something down, takes an object) has past “laid”. So: she lay down (correct); she laid down (wrong); lay the files (not lie); have lain untouched (not laid).","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-111","question":"Read the passage and answer the question.\n\nPassage: When a ride-hailing platform cut its commission from 25% to 15% in one city, driver sign-ups rose by 40% within two months. Yet the average driver's earnings per hour fell. The platform's analysts noted that the number of ride requests had stayed flat over the period, and that the share of each shift drivers spent waiting for a booking had nearly doubled.\n\nQuestion: Which of the following is best supported by the passage?","options":["The cut drew so many new drivers that the same number of rides was spread thinner, reducing each driver's paid time.","The commission cut was a loss-making decision for the platform.","Drivers who joined after the cut were less skilled than earlier drivers.","Riders did not notice the commission cut because fares did not change."],"answer":0,"explanation":"Flat demand + many more drivers + doubled waiting time together point to dilution: the same rides shared by more drivers, so each spends less of the shift earning. A lower commission alone would raise per-ride income, so something must have offset it — idle time. The passage says nothing about the platform's profits, driver skill or rider awareness; those options import outside assumptions.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-112","question":"Read the passage and answer the question.\n\nPassage: When a ride-hailing platform cut its commission from 25% to 15% in one city, driver sign-ups rose by 40% within two months. Yet the average driver's earnings per hour fell. The platform's analysts noted that the number of ride requests had stayed flat over the period, and that the share of each shift drivers spent waiting for a booking had nearly doubled.\n\nQuestion: Based on the passage, which step would most directly raise drivers' hourly earnings, assuming the commission stays at 15%?","options":["Cutting the commission further to 10%","Increasing ride requests or slowing the onboarding of new drivers","Paying a one-time bonus to every driver who joined after the cut","Publishing average hourly earnings to attract still more drivers"],"answer":1,"explanation":"Hourly earnings fell because waiting time doubled while demand stayed flat. The lever is therefore the ratio of rides to drivers: more requests or fewer new drivers. A further commission cut (tempting, since the first one was 'driver-friendly') would attract even more drivers and deepen the idle-time problem; publicising earnings has the same effect; a one-time bonus does not change hourly earnings.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-113","question":"Read the passage and answer the question.\n\nPassage: Historians long read the steep fall in recorded crop yields in a fourteenth-century province as evidence of famine. But in the same decades the province switched from taxing harvests to taxing land area. Under the new system a landholder gained nothing by reporting his output accurately and risked nothing by understating it, so the yield records — kept by tax collectors who no longer needed them — lost their link to what was actually harvested.\n\nQuestion: Which of the following best states the author's main point?","options":["There was no famine in the province during the fourteenth century.","Taxing land area is a fairer system than taxing harvests.","The recorded fall in yields may reflect a change in reporting incentives rather than a real fall in harvests.","Tax collectors deliberately falsified the yield records to hide a famine."],"answer":2,"explanation":"The author does not deny a famine outright; the claim is that the records stopped measuring harvests once the tax no longer depended on them, so they cannot prove a famine. 'There was no famine' overstates the argument (the most tempting trap). Fairness of taxes is never discussed, and the passage blames incentives, not deliberate falsification.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-114","question":"Read the passage and answer the question.\n\nPassage: Historians long read the steep fall in recorded crop yields in a fourteenth-century province as evidence of famine. But in the same decades the province switched from taxing harvests to taxing land area. Under the new system a landholder gained nothing by reporting his output accurately and risked nothing by understating it, so the yield records — kept by tax collectors who no longer needed them — lost their link to what was actually harvested.\n\nQuestion: Which of the following, if true, would most strengthen the author's argument?","options":["Neighbouring provinces that made the same switch to land taxes recorded no fall in yields.","Several landholders petitioned against the land tax, calling it heavy.","Tax collectors in the province were paid a fixed salary throughout the period.","Grain prices in the province's markets stayed stable throughout those decades, whereas they rose sharply during documented famines elsewhere."],"answer":3,"explanation":"Stable prices are independent evidence that real supply did not collapse, which is exactly what the author needs: the records fell, the harvest did not. If neighbouring provinces made the same switch without a recorded fall, the switch does not seem to distort records — that weakens the argument. Complaints about the tax and the collectors' pay do not bear on whether the records tracked real output.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-115","question":"Read the passage and answer the question.\n\nPassage: Chess masters shown a position from a real game for five seconds can reconstruct it almost perfectly, while novices recall only a handful of pieces. When the same number of pieces is scattered randomly on the board, however, masters do barely better than novices.\n\nQuestion: Which conclusion is most strongly supported?","options":["The masters' advantage comes from recognising meaningful patterns rather than from greater raw memory capacity.","Masters have a generally superior visual memory compared with novices.","Masters remember random positions worse than novices do.","Novices could become masters by practising the memorisation of random positions."],"answer":0,"explanation":"The advantage appears only when the position is meaningful, so it must depend on knowledge of typical structures, not on general memory. 'Superior visual memory' is contradicted by the random-position result; 'worse than novices' overstates 'barely better'; and nothing suggests memorising random positions builds expertise — if anything the data suggest it would not help.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-116","question":"Read the passage and answer the question.\n\nPassage: Open-plan offices were sold as engines of collaboration: tear down the walls, the argument went, and the barriers between people would fall with them. Yet when researchers fitted employees at two firms with sensors before and after such a move, face-to-face conversation fell by roughly two-thirds while email and chat messages rose sharply. Deprived of privacy, workers seem to have rebuilt it digitally.\n\nQuestion: The author's attitude towards the claim that open-plan offices increase collaboration is best described as:","options":["neutral: the author merely reports a study without judging the claim","sceptical: the author presents evidence that the promised effect did not occur","hostile to all forms of office redesign","convinced that digital communication harms productivity"],"answer":1,"explanation":"'Were sold as', 'the argument went' and the contrasting 'Yet' signal distance from the claim, and the evidence cuts against it — that is scepticism. It is not neutral (the framing takes a side), not a blanket attack on redesign, and the passage never says digital messaging hurts productivity; it only says it replaced talk.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-117","question":"Read the passage and answer the question.\n\nPassage: Open-plan offices were sold as engines of collaboration: tear down the walls, the argument went, and the barriers between people would fall with them. Yet when researchers fitted employees at two firms with sensors before and after such a move, face-to-face conversation fell by roughly two-thirds while email and chat messages rose sharply. Deprived of privacy, workers seem to have rebuilt it digitally.\n\nQuestion: The final sentence of the passage most likely implies that:","options":["employees preferred email because it is faster than conversation","the firms' managers banned face-to-face conversation after the move","employees used written messages partly to keep their exchanges from being overheard","the sensors interfered with normal conversation"],"answer":2,"explanation":"'Deprived of privacy, workers seem to have rebuilt it digitally' means the move to messages was a way of regaining privacy that the open floor removed. Speed of email is not mentioned; nothing suggests a ban; and blaming the sensors would undercut the study rather than explain the result, which is not what the author implies.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-118","question":"Critical reasoning. A company found that teams using its new code-review tool shipped 30% fewer bugs than teams that did not. The tool was offered to all teams, but adoption was voluntary, and the earliest adopters were teams whose leads had already made automated testing mandatory. The company concludes that the tool cuts bugs by about 30%. Which of the following best describes the main weakness of this conclusion?","options":["A 30% difference is too small to be meaningful.","Bugs differ in severity, so counting them is meaningless.","The tool may slow teams down and reduce the number of releases.","The adopting teams may have had fewer bugs anyway because of practices they already followed, so the difference cannot be credited to the tool alone."],"answer":3,"explanation":"Voluntary adoption by teams that already had mandatory testing is self-selection: the groups differed before the tool arrived, so the 30% gap mixes the tool's effect with existing discipline. The other options raise side issues (size, severity, speed) that do not touch the causal leap from correlation to effect.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-119","question":"Critical reasoning. After a town library extended its opening hours from 40 to 60 hours a week, the average number of visits per day fell, yet the total number of books borrowed per week rose. Which of the following, if true, best explains this?","options":["With longer hours, regular users switched from several short visits a week to a single longer visit in which they borrowed several books at once.","The library added a large number of new books at the same time.","Many visitors came only to use the library's free internet.","The library reduced the maximum number of books a member could borrow at a time."],"answer":0,"explanation":"The puzzle needs both facts at once: fewer visits but more borrowing. Fewer, longer visits with several books each explains both. New stock could raise borrowing but does not explain fewer visits; internet users are irrelevant to borrowing; a lower borrowing cap would push borrowing down, the opposite of what happened.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-120","question":"Critical reasoning. After a city installed red-light cameras at its 20 busiest junctions, the number of reported collisions at those junctions rose by 15%, yet insurance payouts for injuries from collisions there fell by 30%. Which of the following, if true, best resolves this apparent discrepancy?","options":["Drivers avoided the camera junctions and used side streets instead.","Drivers braking suddenly to avoid fines caused more minor rear-end bumps, while dangerous side-impact crashes from running red lights became much rarer.","Insurance companies raised their premiums across the city during the same period.","The cameras were switched off at night for maintenance."],"answer":1,"explanation":"More collisions but fewer injury payouts means the mix of collisions changed: many more low-severity crashes and fewer severe ones. Sudden braking explains the first and fewer red-light runners the second. Diverted traffic would reduce collisions, not raise them; premiums say nothing about payouts; night-time switch-offs do not explain the opposite movements.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-121","question":"Critical reasoning. An online-course provider reports that 90% of learners who paid for a course completed it, compared with 15% of learners who took it free. It therefore plans to stop offering free access, expecting the overall completion rate to rise to about 90%. The plan depends on which of the following assumptions?","options":["Most learners who now take courses free would agree to pay.","Completion is the best measure of how much a learner has learned.","The higher completion among payers is caused by having paid, rather than by the kind of learner who chooses to pay.","The price of the courses will not be raised in future."],"answer":2,"explanation":"The provider expects anyone who pays to behave like today's payers. That holds only if paying itself drives completion; if payers were simply the already-motivated learners, newly forced payers would complete at a lower rate. Whether most free learners pay changes how many enrol, not the completion rate among those who do; the other two options are not needed for the prediction.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-122","question":"Critical reasoning. The city council plans to end rush-hour congestion on its main road by widening it from two lanes to four. The council's reasoning assumes which of the following?","options":["Most rush-hour drivers on the road travel alone.","Widening the road will be cheaper than building a new rail line.","Congestion on the main road is worse than on any other road in the city.","The extra capacity will not simply attract enough additional trips to fill the road again."],"answer":3,"explanation":"If doubling capacity draws people who previously avoided the road (or travelled at other times), the new lanes fill up and congestion returns — the plan only works if that does not happen. Solo driving, cost comparisons and ranking against other roads are not needed for the conclusion that widening will end congestion on this road.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-123","question":"Critical reasoning. Ornithologists claim that a migratory songbird finds its way using the Earth's magnetic field. Which of the following, if true, most strongly supports this claim?","options":["Birds fitted with small magnets that distort the local field became disoriented under overcast skies, while birds fitted with brass weights of the same mass did not.","The birds fly the same route every year.","The birds migrate mostly at night.","Other species of bird are known to navigate using the positions of stars."],"answer":0,"explanation":"This is a controlled intervention: disturbing the magnetic field (and only that, since the brass weights control for the extra load) disrupts navigation when visual cues are hidden. A fixed route, night flying or other species' star navigation are consistent with many mechanisms and do not single out magnetism; star navigation even suggests an alternative.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-124","question":"Critical reasoning. In the year after a city launched a bike-sharing scheme, reported cases of asthma fell by 12%. The mayor argues that the scheme cut traffic pollution and so improved residents' health. Which of the following, if true, most seriously weakens the mayor's argument?","options":["Bike-sharing schemes in other cities have been popular.","In the same year the city's main hospital changed its coding rules, recording many former asthma cases as 'allergic bronchitis'.","Cycling is good exercise and improves heart health.","Some residents who use the bikes have asthma."],"answer":1,"explanation":"If the fall in 'asthma' is partly a relabelling of the same illnesses, the statistic does not show any real health improvement, let alone one caused by cleaner air. Popularity elsewhere and the heart benefits of exercise are irrelevant to asthma; asthmatic bike users do not affect the citywide count.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-125","question":"Critical reasoning. A survey found that employees who use standing desks report far fewer back problems than those who sit all day. The HR head proposes buying standing desks for all staff to reduce back problems. Which of the following, if true, most seriously weakens the proposal?","options":["Standing desks are more expensive than ordinary desks.","Some employees who use standing desks still sit for part of the day.","Employees who already had back problems were advised by their doctors not to use standing desks.","Back problems are a leading cause of sick leave."],"answer":2,"explanation":"This reverses the causal arrow: the desks did not prevent back problems; people with back problems were steered away from the desks. The correlation then says nothing about what the desks would do for everyone. Cost is a practical objection, not a logical weakness; partial sitting and the importance of back problems do not attack the inference.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-126","question":"Critical reasoning. Every project that met its deadline last year used the agile method. Some projects that used the agile method went over budget. No project that went over budget won an award. Which of the following must be true?","options":["Some projects that met their deadline went over budget.","No project that met its deadline won an award.","Every project that won an award used the agile method.","Some projects that used the agile method did not win an award."],"answer":3,"explanation":"The agile projects that went over budget exist (second statement), and none of them won an award (third statement), so some agile projects did not win. The first option may or may not be true — the over-budget agile projects need not be among those that met their deadline. Nothing links award winners to agile or forbids deadline-meeting projects from winning, so the last two are not forced.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-127","question":"Critical reasoning. Some economists argue that raising the minimum wage destroys low-wage jobs. [A] Yet in several regions that raised it sharply, employment in low-wage sectors held steady. The economists reply that employers adjusted in other ways, cutting hours and training instead of jobs. [B] If that is so, the right test of the policy is not the number of jobs but total hours worked and benefits received. In this argument, the sentences marked [A] and [B] play which roles?","options":["[A] is evidence against a position; [B] is the author's conclusion about how that position should be tested.","[A] is the conclusion of the argument; [B] is evidence for it.","[A] is the economists' main claim; [B] is a concession the author makes to them.","[A] and [B] are both pieces of evidence for the economists' position."],"answer":0,"explanation":"[A] reports a finding that cuts against the job-loss claim. The economists then shift ground, and [B] draws the author's conclusion: if adjustment happens through hours and benefits, those, not job counts, are the proper measure. [A] is not the conclusion and is not the economists' claim (their claim is in the first sentence); [B] does not concede anything to them — it reframes the test.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-128","question":"Critical reasoning. A city says that the 'quiet zones' it created last year cut noise complaints in those areas by 40%, so the zones have reduced noise. Which of the following would be most useful to know in evaluating this claim?","options":["How many residents support the quiet zones","Whether the way complaints are made — the hotline's hours or the online form — changed when the zones were introduced","How the city decided which areas would become quiet zones","Whether quiet zones in other countries have been popular with tourists"],"answer":1,"explanation":"The argument uses complaints as a stand-in for noise. If the complaint channel became harder to use at the same time, complaints could fall with no change in noise. That answer would directly confirm or undermine the measure. Public support and tourist popularity do not bear on noise levels; how the areas were chosen matters less than whether the measurement itself changed.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-129","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The idea, however, sat unused for two decades, because the scanners needed to read it did not yet exist.\nQ: That packet now sits in a museum, an unlikely relic of a revolution in retail.\nR: In 1949 an engineering student sketched a code of thick and thin lines by drawing his fingers through beach sand.\nS: Today the same pattern is read billions of times a day, so routinely that shoppers no longer notice it.\nT: Cheap lasers and microchips changed that in the 1970s, and a supermarket finally scanned its first item, a packet of chewing gum.","options":["RTPQS","PRTQS","RPTQS","RPTSQ"],"answer":2,"explanation":"R introduces the idea (1949). P ('The idea, however, sat unused … scanners did not exist') must follow it. T ('changed that') answers P's missing scanners and introduces the packet of gum; Q ('That packet') must come right after T. S ('Today') closes the timeline. RPTSQ separates Q from the packet it refers to; RTPQS makes 'changed that' refer to nothing.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-130","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Newer studies suggest instead that the brain actively prunes memories it rarely uses.\nQ: Seen this way, the blank we sometimes draw on a name is the price of a memory that works.\nR: For a long time, psychologists treated forgetting as passive decay, like ink fading on paper.\nS: A system that stored every detail would, by contrast, drown in its own records.\nT: Pruning clears away clutter, so the memories that remain are quicker to retrieve.\nU: This is why people with near-perfect recall often describe it as a burden rather than a gift.","options":["RTPSUQ","PRTSUQ","RPSTUQ","RPTSUQ"],"answer":3,"explanation":"R gives the old view; P ('instead') gives the new one; T explains what pruning achieves; S ('by contrast') imagines the opposite system; U ('This is why') draws the consequence of S for people with perfect recall; Q ('Seen this way') sums up. RPSTUQ puts U after T, but 'This is why people with near-perfect recall … burden' explains S, not the benefits of pruning; PRTSUQ starts with 'instead', which needs the old view before it.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-131","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Ports that refused to adapt, by contrast, faded within a generation.\nQ: The steel shipping container, introduced in the 1950s, looks too simple to have changed the world.\nR: By packing goods into identical boxes that cranes could lift straight onto lorries and trains, it cut loading costs dramatically.\nS: Before it, cargo was loaded piece by piece, and a ship could spend longer in port than at sea.\nT: Cities that invested early in deep berths and giant cranes became the new hubs of world trade.","options":["QSRTP","QRSTP","QSRPT","SQRTP"],"answer":0,"explanation":"Q introduces the container; S ('Before it') describes the old system; R explains how the container cut costs; T names the winners; P ('by contrast') names the losers and must follow T. QSRPT puts 'by contrast' before anything it can contrast with; SQRTP opens with 'it' before the container is mentioned.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-132","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Within that narrow band, a difference of a tenth of a star can decide which product a shopper buys.\nQ: A five-star rating system seems to offer precise, graded feedback.\nR: Sellers, knowing this, chase tiny gains in their average rather than real improvements in quality.\nS: In practice, most users give either one star or five, treating the scale as a thumbs-up or thumbs-down.\nT: The middle of the scale is therefore nearly empty, and most averages cluster between 4.2 and 4.8.\nU: The precision the system promised has thus become a pressure that rewards gaming over substance.","options":["QTSPRU","QSTPRU","SQTPRU","QSTRPU"],"answer":1,"explanation":"Q states the promise; S ('In practice') shows how users actually behave; T ('therefore') draws the consequence — averages bunch together; P ('that narrow band') needs T's range; R ('knowing this') follows P's point that tiny differences matter; U ('thus') concludes. QTSPRU makes 'therefore' precede its reason; QSTRPU puts 'knowing this' before the fact it refers to.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-133","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Each of these omissions is small on its own, but they compound.\nQ: Early estimates for software projects are notoriously optimistic.\nR: Managers then respond with pressure, and rushed work produces still more rework.\nS: Developers estimate the work they can see, not the integration, testing and rework that surface later.\nT: Ten tasks, each underestimated by a modest fifteen per cent, add up to a slip of weeks once the waiting between tasks is counted.","options":["QPSTR","QSTPR","QSPTR","SQPTR"],"answer":2,"explanation":"Q states the claim; S gives the cause and lists the omitted items; P ('Each of these omissions … compound') needs S's list; T illustrates the compounding; R ('then') describes the next stage, the managers' reaction to the slip. QPSTR uses 'these omissions' before any are named; QSTPR gives the example of compounding before the idea of compounding.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-134","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Asphalt and dark roofs soak up sunlight during the day and release it slowly through the night.\n2. As a result, a city centre can stay several degrees warmer than the surrounding countryside after sunset.\n3. Rising sea levels, meanwhile, threaten coastal cities with more frequent flooding.\n4. Painting roofs white or planting street trees reflects or blocks much of this incoming energy.\n5. Several cities now offer rebates to building owners who install such cool roofs.","options":["Sentence 2","Sentence 4","Sentence 5","Sentence 3"],"answer":3,"explanation":"The paragraph is about urban heat: cause (1), effect (2), remedy (4, 'this incoming energy') and policy (5, 'such cool roofs'). Sentence 3 is about another climate threat to cities; its 'meanwhile' makes it look connected, but it breaks the cause–effect–remedy chain. Sentence 5 might look like a detour, but 'such cool roofs' ties it to sentence 4.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-135","question":"Grammar. Which of the following sentences is grammatically correct?","options":["One of the managers who were promoted last year has resigned.","One of the managers who was promoted last year have resigned.","One of the managers who were promoted last year have resigned.","One of the managers who was promoted last year has resigned."],"answer":0,"explanation":"Two verbs, two subjects. 'who' refers to 'managers' (several were promoted, and one of that group resigned), so the relative clause takes 'were'. The main subject is 'One', so the main verb is 'has resigned'. The option with 'who was … has' is the common slip: it makes 'who' refer to 'one', which changes the meaning to 'the one manager who was promoted'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-136","question":"Grammar. Which sentence is free of a modifier error?","options":["Having reviewed the code twice, the bug still escaped the team.","Having reviewed the code twice, the team still missed the bug.","After reviewing the code twice, the bug was still missed by the team.","To review the code properly, a checklist is needed by the team."],"answer":1,"explanation":"An opening participle or infinitive phrase must describe the subject that follows it. Only 'the team' can review code. In the other options the subject is 'the bug' (twice) or 'a checklist', so the bug or the checklist is said to have reviewed the code — dangling modifiers. The passive 'was still missed by the team' does not rescue the sentence, because the grammatical subject is still 'the bug'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-137","question":"Grammar. Fill in the blank. If the server had been patched last week, we ___ with this breach now.","options":["would not have dealt","will not be dealing","would not be dealing","had not been dealing"],"answer":2,"explanation":"This is a mixed conditional: a past condition ('had been patched last week') with a present result ('now'). The result clause therefore uses would + present (continuous) form: 'would not be dealing'. 'Would not have dealt' is the past-result form, which clashes with 'now'; 'will' belongs to real future conditions; 'had not been dealing' is not a result form at all.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-138","question":"Grammar. Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe data from both surveys suggest / that neither the price nor the features / was the main reason customers / switched to the rival product.","options":["The data from both surveys suggest","that neither the price nor the features","No error","was the main reason customers"],"answer":3,"explanation":"With 'neither … nor', the verb agrees with the nearer subject, 'the features', so it should be 'were the main reason'. 'The data … suggest' is correct (data is treated as plural in formal usage) and is the tempting distractor; 'the price nor the features' is correctly paired.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-139","question":"Grammar. Which of the following sentences is correct?","options":["The battery life of the new phone is longer than that of the old phone.","The battery life of the new phone is longer than the old phone.","The new phone's battery life is longer than the old phone.","The battery life of the new phone is longer than those of the old phone."],"answer":0,"explanation":"A comparison must set like against like: battery life against battery life. 'That of the old phone' stands for 'the battery life of the old phone'. The first two compare a battery life with a phone; 'those' is plural and cannot stand for the singular 'battery life'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-140","question":"Grammar. How many of the following sentences are grammatically correct?\n(i) The manager asked Riya and me to present the findings.\n(ii) It was they who approved the budget.\n(iii) Let's keep this matter strictly between you and me.\n(iv) The award will go to whoever finishes the course first.","options":["1","3","2","4"],"answer":3,"explanation":"All four are correct. (i) 'me' is an object of 'asked'; (ii) after 'It was' the formal subject form 'they' is used; (iii) 'between' is a preposition and takes the object form 'you and me'; (iv) 'whoever' is the subject of 'finishes' inside its own clause, so it is not changed to 'whomever'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-141","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The trouble is that a password strong enough to resist guessing is usually too hard to remember.\nQ: So users write it down, reuse it across sites, or vary it by a single predictable digit.\nR: For years, security teams answered weak passwords with ever stricter rules: longer strings, symbols, forced changes every ninety days.\nS: Each of these habits quietly undoes the strength the rules were meant to buy.\nT: That is why many guidelines now favour long, memorable passphrases and have dropped forced periodic changes.","options":["PRQST","RQPST","RPQTS","RPQST"],"answer":3,"explanation":"R sets up the old approach; P ('The trouble is') names its flaw; Q ('So users … it') needs P's singular 'a password' and gives the users' response; S ('these habits') sums up Q; T ('That is why') draws the conclusion. In RQPST, Q's 'it' has no singular antecedent and the 'So' has no cause yet.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-142","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Within a decade, the same farmers were buying more fertiliser, not less.\nQ: When a cheaper, more efficient fertiliser reached the region, officials expected total use to fall.\nR: Economists call this the rebound effect: making a resource cheaper to use can raise demand for it enough to cancel the saving.\nS: Fields that had once been too poor to farm profitably were now worth planting.\nT: The reason was not waste but expansion.","options":["RQPTS","QPTSR","QPSTR","QTPSR"],"answer":1,"explanation":"Q states the expectation, P the surprising outcome ('the same farmers'), T announces the cause, S spells it out, and R names the pattern ('this'). R cannot open because 'this' needs something before it; in QPSTR the claim 'The reason was … expansion' comes after its own evidence.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-143","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Many cities now paint cycle lanes green to make them visible to drivers.\n2. Studies of such lanes find that colour alone does little to reduce collisions at junctions.\n3. What does reduce them is physical separation: kerbs, bollards or parked cars between bikes and traffic.\n4. Green is also the colour most strongly associated with environmental campaigns.\n5. Paint, in other words, signals a lane; it does not protect the people in it.","options":["5","4","1","2"],"answer":1,"explanation":"The paragraph argues that painted lanes signal but do not protect, while physical separation does. Sentence 4 drifts to the symbolism of the colour green, which plays no part in that argument. Sentence 5 needs 2 and 3, and 1 introduces the painted lanes.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-144","question":"Choose the sentence that best completes the paragraph.\nHospitals that published their surgeons' death rates hoped to reward skill and expose carelessness. Some surgeons, however, began turning away the sickest patients, whose higher risk of dying would drag their numbers down. The published rates improved; ________.","options":["whether the patients did is a different question","this shows that the original rates had been miscalculated","the hospitals, accordingly, became safer for every patient","and the sickest patients were treated with more care than before"],"answer":0,"explanation":"The paragraph separates the measure (the published rate) from the goal (patients' outcomes): the numbers got better partly because the riskiest patients were refused. The ending must keep that gap open. 'Safer for every patient' and 'more care' contradict the refusals, and nothing suggests a miscalculation.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-145","question":"Critical reasoning. Employees who took a company's optional time-management course completed 20% more tasks the next quarter than employees who did not. The company concludes that making the course compulsory will raise every employee's output by about 20%.\nWhich of the following is an assumption the conclusion depends on?","options":["Time-management courses are more effective than any other kind of training","Completing more tasks always means producing higher-quality work","The employees who chose the course were not already more productive or motivated than those who did not","The course was taught by an outside expert rather than an internal trainer"],"answer":2,"explanation":"The data compare self-selected volunteers with everyone else. If the volunteers were already the keener, faster workers, the 20% gap reflects who signed up, not what the course did, and compulsion would not reproduce it. The conclusion is about output, so quality and comparison with other training are not needed.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-146","question":"Critical reasoning. After a city replaced the diesel buses on Route 9 with electric ones, average weekday ridership on that route rose by 15%. Officials conclude that passengers prefer electric buses and plan to convert the whole fleet in order to grow ridership.\nWhich of the following, if true, most weakens the officials' conclusion?","options":["In a survey, several Route 9 passengers said the new buses were quieter","Electric buses cost considerably more to buy than diesel buses","Ridership on the city's other routes rose by 2% over the same period","As part of the switch, buses on Route 9 began running every 10 minutes instead of every 20"],"answer":3,"explanation":"Doubling the frequency is a rival cause big enough to explain the rise, so the bus type may not matter at all. Cost is irrelevant to whether passengers prefer the buses; a 2% rise elsewhere leaves most of the gap unexplained; quieter buses, if anything, support the conclusion.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-147","question":"Critical reasoning. In the year after a city's police launched an online form for reporting crimes, the number of reported burglaries rose sharply, yet insurance claims for burglary in the city fell.\nWhich of the following, if true, best resolves the apparent contradiction?","options":["Many victims of minor burglaries who would not have visited a police station now reported them online","The online form could also be used to report lost property","Insurance companies raised their premiums for homes in the city that year","Reported burglaries in neighbouring cities also rose that year"],"answer":0,"explanation":"If the form made reporting easier, recorded burglaries can rise even while actual burglaries, and so insurance claims, fall: the rise is in reporting, not in crime. Premiums might touch the claims figure but do not explain the jump in reports; lost-property reports are not burglaries; neighbouring cities say nothing about this one.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-148","question":"Read the passage and answer the question.\n\nPassage: Early printed books imitated manuscripts so closely that printers hired scribes to add decorated capitals by hand, and some buyers did not notice they were holding a printed book. Only after a generation did printers begin to exploit what the press could do that a scribe could not: page numbers that matched across copies, indexes that pointed to the same place in every copy, and title pages that advertised the printer's shop.\n\nQuestion: Which of the following can be inferred from the passage?","options":["Scribes resisted the spread of printing because it threatened their trade","Early printed books were of lower quality than the manuscripts they imitated","Title pages were first devised by scribes to advertise their own work","An index that cites page numbers works only if every copy places the text on the same page"],"answer":3,"explanation":"The passage lists matching page numbers and indexes that 'pointed to the same place in every copy' as things a scribe could not offer; that only makes sense if an index depends on identical pagination. Resistance and quality are never discussed, and title pages are credited to printers, not scribes.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-149","question":"Read the passage and answer the question.\n\nPassage: Early printed books imitated manuscripts so closely that printers hired scribes to add decorated capitals by hand, and some buyers did not notice they were holding a printed book. Only after a generation did printers begin to exploit what the press could do that a scribe could not: page numbers that matched across copies, indexes that pointed to the same place in every copy, and title pages that advertised the printer's shop.\n\nQuestion: Which of the following best states the main point of the passage?","options":["For a generation readers could not tell printed books from manuscripts","A new technology was first used to copy the old one, and its distinctive advantages were exploited only later","Printing replaced hand-copying quickly because it was far cheaper","Decorated capitals were the most prized feature of early books"],"answer":1,"explanation":"The passage moves from imitation ('imitated manuscripts so closely') to later exploitation ('Only after a generation … what the press could do that a scribe could not'). Cost is not mentioned, capitals are only an example of imitation, and the last option overstates 'some buyers did not notice'.","difficulty":"hard","source":"TCS NQT · CAT VARC"},
  {"id":"apt-verbal-placement-150","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe auditor recommended / that every invoice above ₹1 lakh / be approved by / two senior managers.","options":["No error","that every invoice above ₹1 lakh","The auditor recommended","be approved by"],"answer":0,"explanation":"After verbs of recommending, insisting or demanding, formal English uses the base-form subjunctive in the that-clause: 'recommended that every invoice … be approved'. Changing it to 'is approved' or 'are approved' is the trap; the singular 'every invoice' does not change the bare form 'be'.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-151","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nOf the two proposals, / the second is the most / practical, since it needs / no new hardware.","options":["Of the two proposals,","No error","the second is the most","practical, since it needs"],"answer":2,"explanation":"When exactly two things are compared, English uses the comparative: 'the second is the more practical'. The superlative 'most' needs three or more. The rest of the sentence is fine.","difficulty":"hard","source":"Accenture · AMCAT"},
  {"id":"apt-verbal-placement-152","question":"Which sentence is correctly parallel?","options":["The trainee can either attend the workshop or watch the recording.","The trainee either can attend the workshop or watching the recording.","The trainee can either attend the workshop or the recording can be watched.","Either the trainee can attend the workshop or watch the recording."],"answer":0,"explanation":"'Either … or' must join elements of the same form, placed right before each: 'either attend … or watch' (two verb phrases). The second option pairs a verb phrase with a clause; the third puts 'either' before a clause but 'or' before a verb; the fourth pairs 'can attend' with 'watching'.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-153","question":"Choose the word closest in meaning to the word in capitals as used in the sentence.\nThe minister's remarks were so EQUIVOCAL that both sides of the dispute claimed he supported them.","options":["emphatic","ambiguous","conciliatory","inflammatory"],"answer":1,"explanation":"Equivocal means open to more than one interpretation, which is exactly why both sides could claim him. 'Conciliatory' is the trap: it describes an attempt to please, but the sentence's point is that his meaning was unclear, not that he was friendly.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-154","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe new evidence did not so much contradict the theory as QUALIFY it.","options":["describe it in detail","make it eligible","limit or modify it","prove it beyond doubt"],"answer":2,"explanation":"'Not so much X as Y' sets Y as a milder alternative to contradicting: to qualify a claim is to restrict or add conditions to it. 'Make eligible' is the everyday sense of qualify and does not fit an argument; 'prove' would be the opposite of contradicting, not a softer version of it.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-155","question":"Choose the word that best fills the blank.\nThe report was ___: in forty pages it said nothing that a single paragraph could not have said.","options":["prolix","terse","cogent","lucid"],"answer":0,"explanation":"The clause after the colon describes needless length, which is what prolix means (tediously wordy). Terse is its opposite; cogent (convincing) and lucid (clear) are praise and do not match the complaint.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-156","question":"Choose the pair of words that best fills the blanks.\nThe critic's review, though ___ in tone, was ___ in substance: it praised the actors politely and then took the play apart scene by scene.","options":["courteous ... flattering","scathing ... devastating","courteous ... devastating","hostile ... gentle"],"answer":2,"explanation":"'Though' sets tone against substance, and the colon explains both halves: polite praise (courteous tone) and a scene-by-scene demolition (devastating substance). 'Scathing … devastating' removes the contrast that 'though' demands; the other two reverse or drop the demolition.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-157","question":"Read the passage and answer the question.\n\nPassage: Translators of poetry face a choice that translators of instruction manuals do not. A manual succeeds if a reader can follow it; its words are disposable once the meaning has been carried across. A poem's words are not disposable, because its sound, rhythm and ambiguity are part of what it means. A translator who keeps the literal sense may lose the music, and one who recreates the music must invent words the poet never wrote. Neither choice is a failure of skill; the loss is built into the task.\n\nQuestion: The author would most likely agree that:","options":["the literal sense is the most important part of a poem's meaning","a skilled enough translator could keep both the sense and the music of any poem","instruction manuals are easier to write than poems","a translation of a poem can be faithful in some respects only by being unfaithful in others"],"answer":3,"explanation":"The author says keeping the sense costs the music and recreating the music costs the literal words, and that 'the loss is built into the task'. That rules out the skilled-translator option directly. The passage ranks no part of meaning above the others and compares translating, not writing.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-158","question":"Read the passage and answer the question.\n\nPassage: Translators of poetry face a choice that translators of instruction manuals do not. A manual succeeds if a reader can follow it; its words are disposable once the meaning has been carried across. A poem's words are not disposable, because its sound, rhythm and ambiguity are part of what it means. A translator who keeps the literal sense may lose the music, and one who recreates the music must invent words the poet never wrote. Neither choice is a failure of skill; the loss is built into the task.\n\nQuestion: Why does the author mention instruction manuals?","options":["To contrast poetry with a kind of text whose meaning can be separated from its exact words","To suggest that poems should be translated the way manuals are","To argue that technical writing deserves more respect than it gets","To give an example of a translation that failed"],"answer":0,"explanation":"Manuals are the foil: their 'words are disposable once the meaning has been carried across', whereas a poem's are not. The comparison sharpens the poetry point; it neither praises manuals, describes a failure, nor recommends manual-style translation.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-159","question":"Critical reasoning. A shop's sales fell after a competitor opened next door. The owner concludes that the competitor is drawing away the shop's customers.\nWhich of the following, if true, most strengthens the owner's conclusion?","options":["The competitor stocks a wider range of products than the shop","The shop raised its prices shortly before the competitor opened","Sales also fell at the chain's shops in towns where no competitor had opened","Most former customers surveyed said they now buy the same products at the competitor"],"answer":3,"explanation":"Direct evidence that the lost customers moved to the competitor ties the fall to it. A wider range only makes the conclusion plausible; falls in towns without a competitor and the price rise point to other causes, so they weaken it.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-verbal-placement-160","question":"Read the statements and choose the option that must be true.\nStatement 1: The release ships on Friday only if all the tests pass.\nStatement 2: All the tests passed.","options":["The release will not ship on Friday","Some of the tests were skipped","The release will ship on Friday","It cannot be determined from these statements whether the release ships on Friday"],"answer":3,"explanation":"'Only if' states a necessary condition, not a sufficient one: passing tests is required for a Friday release but does not guarantee it (an approval or a freeze might still block it). Treating 'only if' as 'if' gives the tempting 'will ship'.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-161","question":"Read the statements and choose the option that must be true.\nEvery analyst on the team knows SQL. Some people who know SQL also know Python. Ravi knows Python.","options":["Ravi knows SQL","Ravi may or may not be an analyst on the team","Ravi is an analyst on the team","Some analysts on the team know Python"],"answer":1,"explanation":"Knowing Python places Ravi in no fixed relation to the team or to SQL: the Python-knowers who know SQL need not include him or any analyst. None of the other three is forced by the statements, so only 'may or may not' must be true.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-162","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nAfter the merger, the two finance teams were AT LOGGERHEADS over which accounting software to keep.","options":["working long hours","waiting for a decision from above","in strong disagreement","in complete agreement"],"answer":2,"explanation":"To be at loggerheads is to be locked in a fierce dispute. The phrase 'over which software to keep' signals a quarrel, not cooperation or waiting.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-163","question":"The first sentence of a paragraph is given. Arrange P, Q, R and S after it to form a coherent paragraph.\n1. Bridge engineers often worry less about the heaviest load a bridge will carry than about loads that repeat.\nP: Each crossing bends the steel very slightly, far too little to see.\nQ: Over millions of crossings, these tiny bends can start microscopic cracks.\nR: That is how a bridge that never carried more than its rated load can still fail, and why inspectors hunt for cracks rather than weigh the traffic.\nS: Once a crack grows past a critical length, the part can break under an ordinary load.","options":["PQRS","QPSR","PQSR","PSQR"],"answer":2,"explanation":"P describes one bend; Q ('these tiny bends') needs P; S follows the crack to failure; R ('That is how … can still fail') needs the failure described in S. In PQRS, R explains a failure that has not yet been mentioned; QPSR opens with 'these' before the bends are introduced.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-164","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe manager asked us / to finish the report / as quick as possible / and send it to the client.","options":["as quick as possible","The manager asked us","No error","to finish the report"],"answer":0,"explanation":"The phrase modifies the verb 'finish', so it needs the adverb: 'as quickly as possible'. The pronoun 'us' is correctly the object of 'asked'.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-165","question":"Choose the best version of the sentence.","options":["Unlike the previous version's, the new app is easier to navigate in its interface.","Unlike the previous version, the new app has an interface that is easier to navigate.","Unlike the previous version, the new app's interface is easier to navigate.","Unlike that of the previous version, the new app has an easier interface to navigate."],"answer":1,"explanation":"A comparison with 'unlike' must set like against like. Only the first contrasts a version with an app. The second contrasts a version with an interface; the third sets 'that of the previous version' (an interface) against 'the new app'; the fourth sets an interface against an app and is clumsy besides.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-166","question":"Read the passage and answer the question.\n\nPassage: The brochure promises that the course will 'transform your career in thirty days'. It offers no data on what graduates went on to do, names no employer that has hired them, and gives twice as many pages to its founder's biography as to its syllabus.\n\nQuestion: The author's attitude towards the brochure's promise is best described as:","options":["indifferent","sceptical","admiring","furious"],"answer":1,"explanation":"Quoting the promise and then listing what is missing (outcomes, employers, syllabus) is the pattern of doubt. The tone is cool and evidence-based, so 'furious' overstates it, and the pointed list is not indifferent.","difficulty":"moderate","source":"Accenture · AMCAT"},
  {"id":"apt-verbal-placement-167","question":"Critical reasoning. Every startup in our accelerator that raised a second funding round had a founder who had previously worked at a large tech company. So big-tech experience is what makes founders succeed.\nThe argument is most vulnerable to which criticism?","options":["It does not consider whether founders with big-tech experience were just as common among the startups that failed to raise a second round","It assumes that large tech companies hire only skilled engineers","It treats a second funding round as the only kind of investment","It does not define what counts as a large tech company"],"answer":0,"explanation":"A trait shared by the winners proves nothing unless it is rarer among the losers; if most founders in the accelerator had big-tech experience, the pattern is expected by chance. The other options point at details the argument does not rely on.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-168","question":"Choose the one word for: a speech or piece of writing that praises someone highly, especially one delivered at a funeral.","options":["obituary","eulogy","elegy","epitaph"],"answer":1,"explanation":"A eulogy is a speech of praise, typically at a funeral. An elegy is a mournful poem, an epitaph is the short inscription on a tomb, and an obituary is a published notice of a death with a life summary.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-169","question":"In which sentence is 'affect' or 'effect' used correctly?","options":["The delay did not effect the final deadline.","Higher fuel prices will effect airline profits.","The manager's words had a deep affect on the team.","The new policy will effect a change in how leave is approved."],"answer":3,"explanation":"As a verb, 'effect' means to bring about, so 'effect a change' (cause a change) is right. The second and fourth need the verb 'affect' (to influence); the third needs the noun 'effect'.","difficulty":"hard","source":"Capgemini · Infosys"},
  {"id":"apt-verbal-placement-170","question":"Fill in the blank.\nThe witness's account was ___ by CCTV footage, which showed exactly what she had described.","options":["alleged","fabricated","corroborated","refuted"],"answer":2,"explanation":"Footage that matches her account confirms it: corroborated. 'Refuted' would need footage that contradicts her; 'fabricated' and 'alleged' describe the account itself, not the effect of the footage.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-171","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Their real value lay elsewhere: a team that had to write down its assumptions often discovered, for the first time, that its members disagreed about them.\nQ: The long-range forecasts produced by corporate planning departments in the 1970s were, by most measures, wrong.\nR: Oil prices, interest rates and exchange rates all moved in ways the forecasters had not imagined.\nS: Yet the firms that kept planning through those years did not regret it.\nT: The forecast, in other words, was useful less as a prediction than as an argument made visible.","options":["QRSPT","QSRPT","RQSPT","QRPST"],"answer":0,"explanation":"Q makes the claim, R supports it, S ('Yet') raises the puzzle of why firms kept planning, P resolves it ('Their real value lay elsewhere'), and T restates the resolution ('in other words'). In QRPST, P answers a question S has not yet asked, and S then repeats a point already settled.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-172","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: A single bee that finds a rich patch of flowers cannot carry the news far by itself.\nQ: The others follow, and within an hour a colony can shift most of its foragers to the new patch.\nR: Back at the hive, though, it performs a dance whose angle and length encode the patch's direction and distance.\nS: No bee decides this; the shift emerges from thousands of small, local choices.","options":["PQRS","PRSQ","PRQS","RPQS"],"answer":2,"explanation":"P introduces the lone bee; R ('though', 'it') answers P's limitation; Q ('The others follow') needs the dance to follow; S ('No bee decides this') comments on the shift described in Q. R cannot open because 'it' needs P; in PRSQ, 'this' would refer to a shift not yet mentioned.","difficulty":"very-hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-173","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. A placebo is a treatment with no active ingredient.\n2. Yet patients given placebos often report real relief, especially from pain.\n3. Some of that relief can be measured: brain scans show changes in the regions that process pain.\n4. Pharmaceutical companies spend more on marketing their drugs than on researching them.\n5. The effect seems to depend on expectation, which is why an expensive-looking pill can work better than a plain one.","options":["5","4","1","3"],"answer":1,"explanation":"Sentences 1, 2, 3 and 5 build one argument about how placebos produce real effects through expectation. Sentence 4 shifts to drug-company budgets, a different subject that none of the others needs.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-174","question":"Choose the option that best completes the paragraph.\nFor most of history, maps were made to be owned rather than used: lavish, decorated, and kept in the libraries of rulers. The cheap printed road map changed this. Once anyone could afford one, ________.","options":["travellers no longer needed to ask anyone for directions","the decorated maps of earlier centuries became completely worthless","maps came to be judged less by their beauty than by whether they got a traveller to the right town","rulers stopped commissioning maps of their territories altogether"],"answer":2,"explanation":"The paragraph turns on 'owned rather than used'; the ending must complete the shift from display to use. The other options overreach: nothing suggests rulers stopped commissioning maps, that old maps lost all value, or that asking for directions ended.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-175","question":"Critical reasoning. In a city where displaying hygiene ratings is voluntary, restaurants that displayed their rating in the window received fewer food-poisoning complaints last year than restaurants that did not. A councillor argues that displaying ratings makes restaurants improve their hygiene.\nWhich of the following, if true, most seriously weakens the councillor's argument?","options":["Several restaurants that display their ratings had once received low ratings","Restaurants that received high ratings were far more likely than others to choose to display them","The ratings were awarded by trained food-safety inspectors","Some food-poisoning complaints are made against the wrong restaurant"],"answer":1,"explanation":"If clean restaurants are the ones that choose to display, the display is a result of good hygiene, not its cause: the causation runs backwards. Inspector training and misdirected complaints do not favour either group; former low-raters that now display hint at improvement, which slightly supports the argument.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-176","question":"Critical reasoning. To reduce dropouts, a university plans to send every first-year student a weekly text message listing the coming week's deadlines.\nThe plan assumes which of the following?","options":["Students read text messages more often than they read emails","Most students who drop out do so in their first year","Text messages are cheaper to send than counselling sessions are to run","A significant number of dropouts are caused at least partly by students losing track of deadlines"],"answer":3,"explanation":"Reminders can only reduce dropouts if missed deadlines contribute to dropping out. The plan does not need texts to beat email, dropouts to cluster in the first year, or any cost comparison; deny the assumption that lost-track deadlines cause some dropouts, though, and the plan has no reason to work.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-177","question":"Critical reasoning. A bakery chain found that its shops that play slow music sell 12% more pastries per customer than its shops that play fast music. It plans to switch every shop to slow music.\nWhich would be most useful to know in evaluating the plan?","options":["Whether fast music costs more to license than slow music","Whether customers can name the music being played","How many pastries the chain sells in a year","Whether the slow-music shops differ from the others in location, customer type or menu"],"answer":3,"explanation":"The plan treats music as the cause of the difference. If the slow-music shops are in different areas or serve different customers, those factors could explain the 12% and the switch would achieve nothing. The other facts do not bear on whether the music causes the sales gap.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-178","question":"Read the passage and answer the question.\n\nPassage: The Tasmanian tiger's extinction is often blamed on the bounty the colonial government paid for each animal killed. The bounty records, however, show kills falling steeply years before the scheme ended, at a time when the payment was unchanged and hunters had every reason to keep claiming it. Some researchers therefore suspect that a disease, reported in zoo animals of the period, had already thinned the wild population, and that hunting finished off a species already in decline.\n\nQuestion: The researchers' reasoning depends on which assumption?","options":["The bounty was the only cause of tiger deaths at the time","Zoo animals and wild animals always catch the same diseases","The colonial government kept no other records of the species","Hunters would have kept killing and claiming as many animals if the animals had still been plentiful"],"answer":3,"explanation":"The argument reads falling claims as falling numbers. That works only if hunting effort stayed the same, so that fewer kills meant fewer animals rather than fewer hunters or less access. 'Always' makes the zoo option far stronger than needed, and the argument itself names a second cause (disease).","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-179","question":"Read the passage and answer the question.\n\nPassage: The Tasmanian tiger's extinction is often blamed on the bounty the colonial government paid for each animal killed. The bounty records, however, show kills falling steeply years before the scheme ended, at a time when the payment was unchanged and hunters had every reason to keep claiming it. Some researchers therefore suspect that a disease, reported in zoo animals of the period, had already thinned the wild population, and that hunting finished off a species already in decline.\n\nQuestion: Which of the following, if true, would most weaken the researchers' suspicion?","options":["The bounty was paid in full for every animal brought in","In the years the kills fell, much of the tiger's remaining range was fenced off as private farmland that bounty hunters could not enter","The disease reported in zoos has also been found in wild specimens collected at that time","Some farmers killed tigers without bothering to claim the bounty"],"answer":1,"explanation":"If hunters lost access to the animals, kills could fall while the population stayed healthy, so the drop no longer points to disease. Disease in wild specimens strengthens the suspicion; full payment is consistent with it; unclaimed kills affect the totals but not why claims fell.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-180","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe review panel comprises of / five members, each of whom / has at least ten years' / experience in the sector.","options":["has at least ten years'","five members, each of whom","The review panel comprises of","No error"],"answer":2,"explanation":"'Comprise' takes a direct object: the panel comprises five members (or is made up of / consists of five members). 'Comprises of' is a common error. 'Each of whom has' is correctly singular.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-181","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nDespite of the delay in funding, / the team managed / to deliver the prototype / on the agreed date.","options":["to deliver the prototype","Despite of the delay in funding,","the team managed","No error"],"answer":1,"explanation":"'Despite' is followed directly by its object: 'Despite the delay'. 'In spite of' takes 'of'; mixing the two gives the error 'despite of'.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-182","question":"How many of the following sentences are grammatically correct?\n(i) The police has arrested the suspect.\n(ii) Each of the boxes was checked twice.\n(iii) The scissors is on the desk.\n(iv) Mathematics is my favourite subject.\n(v) The furniture in the new office are modern.","options":["3","4","2","1"],"answer":2,"explanation":"Only (ii) and (iv) are right. 'Police' is a plural noun (the police have arrested), 'scissors' is plural (are), and 'furniture' is uncountable and singular (is). 'Each of' takes a singular verb, and subjects like mathematics are singular despite the -s.","difficulty":"very-hard","source":"AMCAT · Product company OA"},
  {"id":"apt-verbal-placement-183","question":"Choose the correct question tag.\nNobody from the finance team has replied yet, ___?","options":["haven't they","has he","have they","hasn't it"],"answer":2,"explanation":"'Nobody' makes the statement negative, so the tag is positive. Indefinite pronouns like nobody and everyone take 'they' in the tag, and 'they' needs 'have'. 'Haven't they' wrongly treats the sentence as positive.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-184","question":"Fill in the blank.\nOnly after the audit was complete ___ the irregularities.","options":["the board learned of","did the board learn of","had learned the board of","the board did learn of"],"answer":1,"explanation":"A sentence opening with 'Only after …' takes inverted word order in the main clause, with the auxiliary before the subject: 'did the board learn'. Normal order ('the board learned') is the common error; the last option inverts the wrong elements.","difficulty":"hard","source":"Product company OA · CAT VARC"},
  {"id":"apt-verbal-placement-185","question":"Choose the correct indirect form of:\nThe manager said, \"We have been testing this build since Monday and will release it tomorrow.\"","options":["The manager said that they were testing that build since Monday and would release it the next day.","The manager said that they have been testing this build since Monday and will release it tomorrow.","The manager said that they had been testing that build since Monday and would release it the next day.","The manager said that they had been testing that build since Monday and will release it the next day."],"answer":2,"explanation":"With a past reporting verb, every tense shifts back: 'have been testing' → 'had been testing' and 'will' → 'would'; 'this' → 'that' and 'tomorrow' → 'the next day'. The last option shifts only one verb; the third uses a past continuous that cannot carry 'since Monday'.","difficulty":"very-hard","source":"Infosys · Accenture"},
  {"id":"apt-verbal-placement-186","question":"Choose the word that best fills the blank.\nThe CEO's resignation letter was a model of ___: it thanked everyone, blamed no one and explained nothing.","options":["indiscretion","discretion","candour","effrontery"],"answer":1,"explanation":"Thanking all, blaming none and revealing nothing is careful reticence: discretion. Candour (frankness) is the opposite of 'explained nothing'; indiscretion and effrontery (shameless boldness) do not fit a letter that offends no one.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-187","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe committee's report was ANODYNE: designed to offend nobody, it informed nobody either.","options":["deliberately provocative","sharply insightful","painful to read","bland and inoffensive"],"answer":3,"explanation":"Anodyne describes something deliberately unlikely to offend, and so dull. Its older sense, a painkiller, may tempt some into 'painful'; the colon's explanation ('designed to offend nobody') rules out 'provocative' and 'insightful'.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-188","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nHer EFFUSIVE thanks embarrassed the quiet volunteer.","options":["insincere","grateful","restrained","generous"],"answer":2,"explanation":"Effusive means gushing, expressing feeling without restraint, so its opposite is restrained. 'Insincere' is a trap: effusive praise may seem insincere, but sincerity is a different scale from how much is expressed.","difficulty":"hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-189","question":"In which sentence is 'disinterested' used in its traditional, exam-standard sense?","options":["A judge must be disinterested in the outcome of the cases she hears.","The students were disinterested in the lecture and kept checking their phones.","He seemed disinterested by the offer and turned it down unread.","After years in the same role, she grew disinterested and bored."],"answer":0,"explanation":"Disinterested means impartial, having nothing to gain from the outcome, which is what a judge should be. The other sentences mean lacking interest, for which the standard word is 'uninterested'.","difficulty":"hard","source":"CAT VARC · Capgemini"},
  {"id":"apt-verbal-placement-190","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: In the nineteenth century, many cities believed that disease spread through foul air, or 'miasma'.\nQ: So a wrong theory, acted on thoroughly, ended up solving the right problem.\nR: They therefore built sewers to carry away the stench of waste.\nS: Cholera and typhoid, in fact, spread through contaminated drinking water.\nT: By carrying the waste away, the sewers also kept it out of that water, which is what really ended the epidemics.","options":["PSRTQ","PRSTQ","PRTSQ","SPRTQ"],"answer":1,"explanation":"P gives the belief, R the action it led to ('therefore'), S corrects the belief ('in fact'), T explains why the action worked anyway ('that water' needs S), and Q sums up. PRTSQ puts 'that water' before any water is mentioned; PSRTQ separates R's 'therefore' from the belief that causes it.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-191","question":"Choose the sentence that best fills the blank.\nMany firms reward call-centre staff for keeping calls short. ________. The result is that customers call back, and the firm ends up handling the same problem two or three times.","options":["Staff learn to end calls quickly, sometimes before the customer's problem is actually solved","Some firms have begun to move their call centres to other countries","Call-centre work is among the most stressful jobs in the service sector","Most customers also prefer short calls, since nobody likes waiting on hold"],"answer":0,"explanation":"The missing sentence must link the incentive (short calls) to the result (repeat calls). Only the first does: rushing calls leaves problems unsolved. Customer preference for short calls would not cause call-backs, and stress or outsourcing break the chain.","difficulty":"very-hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-192","question":"Read the statements and choose the option that must be true.\nAll the interns who completed the security training were given access to the production server. Some interns with access to the production server made changes without approval. Priya is an intern who completed the security training.","options":["Priya was given access to the production server","Every intern with access to the production server completed the training","Some interns who completed the training made changes without approval","Priya made changes without approval"],"answer":0,"explanation":"The first statement applies to Priya directly, so she has access. The interns who made unapproved changes might all be ones who got access some other way, so neither Priya nor any trained intern is known to have made changes; and the first statement does not say only trained interns got access.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-193","question":"Critical reasoning. In a study, people told that a wine cost ₹4,000 a bottle rated it as tasting better than people told that the same wine cost ₹400. Brain scans also showed more activity in pleasure-related regions in the first group.\nWhich conclusion is best supported by the study?","options":["Information about price can change how much people actually enjoy something, not just what they say about it","Expensive wines generally taste better than cheap ones","Wine sellers would always earn more by raising their prices","People cannot tell good wine from bad wine"],"answer":0,"explanation":"The wine was the same, so the difference came from the price label; the brain scans suggest the difference was felt, not merely reported. The study compares no different wines, tests no ability to judge quality, and says nothing about sales.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-194","question":"Choose the pair of words that best fills the blanks.\nThe new manager's style was a sharp ___ from her predecessor's: where he had ___ every decision, she delegated almost everything.","options":["departure ... micromanaged","departure ... ignored","continuation ... delegated","relief ... approved"],"answer":0,"explanation":"'Where he had …, she delegated' sets up an opposite: someone who controlled every decision personally, i.e. micromanaged. That contrast is a departure. 'Ignored' is not the opposite of delegating, and 'continuation' contradicts 'sharp'.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-195","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nThe architect told the new hires not to REINVENT THE WHEEL: the firm already had templates for most of their drawings.","options":["start the project over from the beginning","copy another firm's designs","make small improvements to an old design","waste effort creating something that already exists"],"answer":3,"explanation":"To reinvent the wheel is to spend effort building from scratch what already exists; the second clause about existing templates makes the meaning explicit.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-verbal-placement-196","question":"Choose the meaning of the phrasal verb in capitals as used in the sentence.\nThe wage talks BROKE DOWN after the union rejected the management's final offer.","options":["failed","were made public","were completed","were postponed"],"answer":0,"explanation":"Talks that break down collapse without agreement; the rejected final offer is the cause. 'Postponed' implies they will resume, which 'final offer' rules out.","difficulty":"moderate","source":"Wipro · CoCubes"},
  {"id":"apt-verbal-placement-197","question":"Read the passage and answer the question.\n\nPassage: Few objects are as unloved as the shipping pallet. Yet without this rough square of planks, which lets a forklift lift a tonne of goods in seconds, almost everything on a supermarket shelf would cost more. Its anonymity is a sign of its success: we notice infrastructure only when it fails.\n\nQuestion: The primary purpose of the passage is to:","options":["explain why shipping pallets often fail","argue that an overlooked object plays an important economic role","describe how the forklift was invented","criticise supermarkets for keeping prices high"],"answer":1,"explanation":"The passage moves from 'unloved' to 'Yet without' it prices would rise: it rescues an ignored object's importance. Prices are evidence, not the target; forklifts are mentioned in passing; and the point is that pallets rarely fail.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-198","question":"Read the passage and answer the question.\n\nPassage: Few objects are as unloved as the shipping pallet. Yet without this rough square of planks, which lets a forklift lift a tonne of goods in seconds, almost everything on a supermarket shelf would cost more. Its anonymity is a sign of its success: we notice infrastructure only when it fails.\n\nQuestion: What does the author mean by 'Its anonymity is a sign of its success'?","options":["The pallet goes unnoticed precisely because it works reliably","The pallet will be appreciated only once it is replaced","Products shipped on pallets are sold without brand names","The pallet succeeded because nobody owns its design"],"answer":0,"explanation":"The explanation follows the colon: we notice infrastructure only when it fails, so something nobody notices is something that does not fail. The other options read 'anonymity' as being about ownership or branding, or predict a future the passage never mentions.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-199","question":"Which sentence is free of redundancy?","options":["Please revert back to me by Friday.","The final outcome of the review will be shared next week.","The two companies merged together last year.","The committee will reconsider its decision after the audit."],"answer":3,"explanation":"'Merged together' (merging already means together), 'revert back' (revert already means go back) and 'final outcome' (an outcome is already final) each repeat an idea. 'Reconsider its decision' says it once.","difficulty":"hard","source":"Capgemini · Accenture"},
  {"id":"apt-verbal-placement-200","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Instead, it asked a simpler question: which customers had stopped buying, and when?\nQ: A retailer once spent two years building a model to predict which customers would leave.\nR: The answer, sitting in its own sales records, turned out to predict departures better than the model ever had.\nS: The model grew so complex that no one could explain its forecasts, and the team quietly abandoned it.\nT: Sometimes the most useful analysis is the one boring enough to be trusted.","options":["QSRPT","SQPRT","QPSRT","QSPRT"],"answer":3,"explanation":"Q introduces the model; S says it was abandoned; P ('Instead') gives the replacement question; R ('The answer') answers P; T draws the moral. P cannot precede S because 'Instead' needs the abandoned effort; R cannot precede P because it answers P's question.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-201","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The savings came less from the box itself than from what it removed: the days of loading and unloading by hand.\nQ: Before the 1950s, cargo was packed loose into ships' holds, sack by sack and crate by crate.\nR: The steel shipping container replaced all of this with a single box that a crane could lift in minutes.\nS: Loading a vessel could take a week, and dockworkers' wages often cost more than the voyage itself.\nT: Within two decades, ocean shipping had become so cheap that it barely mattered where a product was made.\nU: Theft and breakage, common when every item passed through many hands, fell sharply too.","options":["SQRPUT","QRSPUT","QSRUPT","QSRPUT"],"answer":3,"explanation":"Q and S describe the old system; R ('all of this') needs both; P explains where the savings came from; U ('too') adds a further saving and so must follow P; T gives the long-run result. In QRSPUT, 'all of this' comes before the week-long loading it summarises; in QSRUPT, 'too' has no earlier saving to refer to.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-202","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Some species of bamboo can grow almost a metre in a single day.\n2. A stalk reaches its full height within a few months and then spends years hardening.\n3. Pandas eat little else, though they digest it poorly.\n4. That mix of fast growth and eventual strength makes bamboo attractive as a building material.\n5. Harvested stalks regrow from the same roots, so a grove need not be replanted.","options":["2","1","3","5"],"answer":2,"explanation":"The paragraph builds a case for bamboo as a renewable building material: speed (1), strength (2), the conclusion (4) and regrowth (5). Sentence 3 is about pandas' diet, which serves none of these points.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-203","question":"Read the passage and choose the option that best summarises it.\n\nPassage: A city that widens a congested road usually finds that, within a few years, the new lanes are as crowded as the old ones. Cheaper, faster trips encourage people to drive more often, to drive at peak hours they used to avoid, and to move to homes farther from work. The extra capacity does not so much relieve demand as release demand that the congestion itself had been holding back.","options":["Cities should never widen roads, because drivers ignore new lanes","Road widening fails mainly because construction takes several years","Widening a congested road tends to create new traffic that fills it, because the congestion had been suppressing demand","People move farther from work when roads become congested"],"answer":2,"explanation":"The key idea is in the last sentence: congestion held demand back, and new capacity releases it. The passage describes a tendency, not a rule that cities must never widen roads; it never blames construction time; and it says people move farther away when trips get easier, not harder.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-204","question":"Critical reasoning. Researchers found that children who ate breakfast scored higher on morning tests than children who skipped it, and concluded that eating breakfast improves concentration.\nWhich of the following, if true, most strengthens the conclusion?","options":["The same children scored higher on days they ate breakfast than on days they skipped it","Children who eat breakfast tend to come from higher-income families","Teachers noticed that hungry children were more talkative in class","Most children in the study preferred cereal to other breakfast foods"],"answer":0,"explanation":"Comparing each child with themselves removes differences between children (income, sleep, motivation), leaving breakfast as the likely cause. The income point is a rival explanation and weakens the claim; cereal preferences and talkativeness do not bear on test scores.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-205","question":"Critical reasoning. Since a company began letting any employee email the CEO directly, the number of formal grievances filed has fallen by 40%. The HR head concludes that the policy has made employees happier.\nWhich of the following, if true, most weakens the HR head's conclusion?","options":["Employee turnover fell slightly over the same period","Complaints sent to the CEO by email are not recorded as formal grievances","The CEO personally replies to most of the emails she receives","Several rival companies have adopted similar policies"],"answer":1,"explanation":"If complaints simply moved to a channel that is not counted, grievances can fall while discontent stays the same: the measure, not the mood, changed. Personal replies and lower turnover tend to support the conclusion; what rivals do is irrelevant.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-206","question":"Read the statements and choose the option that must be true.\nEvery senior developer on the project reviews code. No one who reviews code merges their own changes. Arjun merged his own changes yesterday.","options":["Arjun reviews code but is not a senior developer on the project","Nothing can be concluded about Arjun","Arjun neither reviews code nor is a senior developer on the project","Arjun is a senior developer who does not review code"],"answer":2,"explanation":"Since Arjun merged his own changes, he cannot be a code reviewer (statement 2). Since every senior developer reviews code, someone who does not review code cannot be a senior developer (statement 1, contrapositive). Both conclusions follow.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-207","question":"Read the passage and answer the question.\n\nPassage: For centuries, sailors could find their latitude from the height of the sun but had no reliable way to find their longitude, which depends on knowing the time at a fixed reference point. Astronomers proposed reading that time from the position of the moon, a method that was elegant but needed hours of calculation. A self-taught clockmaker proposed instead a clock accurate enough to keep the reference time at sea for months. The scientific establishment, which favoured the astronomers' method, was slow to accept that a mechanical device could solve what it regarded as a problem of astronomy.\n\nQuestion: According to the passage, finding longitude at sea required:","options":["measuring the height of the sun","knowing the time at a reference point while away from it","hours of calculation from the moon's position","a clock built by a self-taught craftsman"],"answer":1,"explanation":"The passage says longitude 'depends on knowing the time at a fixed reference point'. The sun's height gives latitude; the lunar calculation and the clock are two competing ways of getting that time, not the requirement itself.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-208","question":"Read the passage and answer the question.\n\nPassage: For centuries, sailors could find their latitude from the height of the sun but had no reliable way to find their longitude, which depends on knowing the time at a fixed reference point. Astronomers proposed reading that time from the position of the moon, a method that was elegant but needed hours of calculation. A self-taught clockmaker proposed instead a clock accurate enough to keep the reference time at sea for months. The scientific establishment, which favoured the astronomers' method, was slow to accept that a mechanical device could solve what it regarded as a problem of astronomy.\n\nQuestion: Which of the following can be inferred from the passage?","options":["The establishment's reluctance stemmed partly from how it classified the problem","The astronomers' method was never used at sea","The clockmaker's clock was less accurate than the lunar method","Latitude was harder to determine than longitude"],"answer":0,"explanation":"The phrase 'what it regarded as a problem of astronomy' links the resistance to the establishment's framing of the problem. Nothing compares accuracy, nothing says the lunar method was never used, and the passage states the reverse of the last option.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-209","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nI am really looking forward / to meet the new / team members / at next week's offsite.","options":["I am really looking forward","No error","team members","to meet the new"],"answer":3,"explanation":"In 'look forward to', 'to' is a preposition, so it takes a gerund: 'looking forward to meeting'. Treating it as part of an infinitive ('to meet') is a frequent error.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-210","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe manager suggested us / to postpone the launch / until the security audit / was complete.","options":["The manager suggested us","until the security audit","to postpone the launch","No error"],"answer":0,"explanation":"'Suggest' does not take a person as object followed by an infinitive. Correct forms are 'suggested that we postpone the launch' or 'suggested postponing the launch'. The error begins with 'suggested us'; the infinitive in the next part only follows from it.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-211","question":"Which sentence states that the team rejected every proposal except one?","options":["Not all of the proposals were rejected by the team.","The team rejected only one of the proposals.","The team only rejected one of the proposals.","The team rejected all but one of the proposals."],"answer":3,"explanation":"'All but one' means all except one. The second and third say exactly one was rejected, the opposite. The last says at least one survived, which is true of the intended meaning but does not say that only one did.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-212","question":"Which sentence says that Riya, and nobody else, saw the email?","options":["Only Riya saw the email.","Riya saw the only email.","Riya saw only the email.","Riya only saw the email."],"answer":0,"explanation":"'Only' limits the word it is placed next to. Before 'Riya' it limits who saw it. 'Saw only the email' limits what she saw; 'only saw' (in careful usage) limits the action, e.g. saw but did not reply; 'the only email' says there was just one email.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-213","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe negotiator's opening was CONCILIATORY: she conceded two minor points before raising her main demand.","options":["aggressive","intended to placate","condescending","evasive"],"answer":1,"explanation":"Conceding points to the other side first is a gesture meant to soothe and build goodwill, which is what conciliatory means. Nothing in the sentence suggests aggression, dodging or talking down.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-214","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe board's victory was PYRRHIC: the company won the lawsuit but lost its biggest client in the process.","options":["achieved through deception","celebrated before it was certain","temporary and soon reversed","won at so great a cost that it was hardly worth winning"],"answer":3,"explanation":"A Pyrrhic victory is one whose cost outweighs its gain, after King Pyrrhus, whose wins against Rome cost him most of his army. The colon spells it out: the lawsuit was won, but the biggest client was lost.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-215","question":"Choose the word that best fills the blank.\nHer argument was ___: every step followed from the last, and none of us could find a flaw in it.","options":["specious","tenuous","cogent","convoluted"],"answer":2,"explanation":"An argument whose steps follow and that withstands scrutiny is cogent. 'Specious' is the trap: it means plausible on the surface but actually wrong, which contradicts 'none of us could find a flaw'.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-216","question":"Choose the pair of words that best fills the blanks.\nAlthough the founders described their product as ___, critics pointed out that it merely ___ features long available elsewhere.","options":["obsolete ... improved","derivative ... repackaged","revolutionary ... repackaged","revolutionary ... invented"],"answer":2,"explanation":"'Although' sets the founders' claim against the critics' view: the claim must be of novelty (revolutionary) and the reply that nothing is new (repackaged). 'Derivative' removes the contrast; 'invented' would agree with the founders, and 'merely' would make no sense.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-217","question":"Choose the sentence that best fills the blank.\nSleep researchers once believed that the brain simply rested at night. ________. During deep sleep, for example, it replays the day's experiences, strengthening some memories and discarding others.","options":["Most adults need between seven and nine hours of sleep a night","Dreams have been interpreted in many ways across cultures","Some animals sleep with only half of their brain at a time","We now know that sleep is a period of intense, organised activity"],"answer":3,"explanation":"The blank must overturn the old belief and set up 'for example', which describes the brain working hard. Only the first does both. Sleep duration, dream interpretation and half-brain sleep do not link the old view to the example.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-218","question":"Critical reasoning. Hospitals that adopted a new surgical checklist recorded more post-operative complications in the first year than before, yet deaths after surgery at those hospitals fell.\nWhich of the following, if true, best resolves the apparent contradiction?","options":["The checklist required staff to record minor complications that had previously gone unreported","Many surgeons disliked filling in the checklist","The hospitals performed more complex operations that year","Deaths after surgery also fell at hospitals that did not use the checklist"],"answer":0,"explanation":"If more complications are being recorded, not occurring, the rise is an artefact of better reporting and is compatible with safer surgery. More complex operations would explain more complications but make falling deaths harder to explain; falling deaths elsewhere explain only one half.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-219","question":"Read the argument and answer the question.\nMany people assume that remote workers are less productive. Yet in a two-year study, call-centre staff who worked from home handled 13% more calls than colleagues in the office. The researchers attribute the gain to fewer breaks and sick days. Still, the result may not carry over to other jobs, since call-centre output is unusually easy to measure.\n\nWhat role does the final sentence play?","options":["It provides further evidence for the study's result","It states the main conclusion of the argument","It limits how widely the study's finding can be applied","It explains why the remote workers were more productive"],"answer":2,"explanation":"'Still' signals a qualification: the last sentence warns that the result may not generalise beyond easily measured work. It neither concludes nor supports the finding, and the explanation for the gain (fewer breaks and sick days) comes in the sentence before.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-220","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nHis explanation for the missing funds did not HOLD WATER.","options":["was not convincing","was not written down","was too long","was not made public"],"answer":0,"explanation":"An argument that holds water stands up to examination; one that does not hold water falls apart when tested, i.e. is unconvincing.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-221","question":"In which sentence is the idiom 'damp squib' used correctly?","options":["She was a damp squib at the party, the life and soul of every conversation.","The much-hyped feature turned out to be a damp squib: users barely noticed it.","The launch was a damp squib, beating every sales forecast.","After a week of rain, the football field was a damp squib."],"answer":1,"explanation":"A damp squib is something expected to make an impact that turns out a disappointing flop. The second option takes it literally; the third and fourth describe successes, the opposite of its meaning.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-222","question":"Critical reasoning. Our app's average rating rose from 3.8 to 4.4 stars after the redesign, so the redesign clearly made our users happier.\nThe argument assumes which of the following?","options":["Users who dislike an app always leave a rating","The redesign cost more than the original design","An average above 4 stars means an app is successful","The people rating the app after the redesign are comparable to those who rated it before"],"answer":3,"explanation":"If the raters changed (for example, unhappy users left and stopped rating), the average could rise without any user becoming happier. The argument needs the two groups to be comparable. 'Always' makes the second option far stronger than needed; the last two are irrelevant.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-223","question":"Choose the one word for: government by the wealthy.","options":["plutocracy","autocracy","oligarchy","aristocracy"],"answer":0,"explanation":"Plutocracy (Greek ploutos, wealth) is rule by the rich. Oligarchy is rule by a small group, whatever the basis; aristocracy is rule by a hereditary noble class; autocracy is rule by one person.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-224","question":"Choose the correctly spelt word from the options below.","options":["consciencious","conscientious","conscientous","consientious"],"answer":1,"explanation":"The word is built on 'conscience' + '-tious': c-o-n-s-c-i-e-n-t-i-o-u-s. The misspellings drop the second 'c', the 'i' before 'ous', or replace the 't' with a 'c'.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-225","question":"Three of the following words are similar in meaning. Which word does NOT belong with them?","options":["transient","fleeting","perennial","ephemeral"],"answer":2,"explanation":"Ephemeral, transient and fleeting all mean lasting a very short time. Perennial means lasting or recurring year after year, the opposite idea.","difficulty":"moderate","source":"AMCAT · Wipro"},
  {"id":"apt-verbal-placement-226","question":"Choose the pair that best completes the analogy.\nLACONIC : WORDS :: FRUGAL : ?","options":["waste","money","generosity","speech"],"answer":1,"explanation":"A laconic person uses few words; a frugal person uses (spends) little money. 'Speech' repeats the first pair's domain, and 'waste' and 'generosity' are what frugality avoids, not what it uses sparingly.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-227","question":"Choose the pair that has the same relationship as ANTIDOTE : POISON.","options":["symptom : disease","rebuttal : argument","vaccine : doctor","remedy : cure"],"answer":1,"explanation":"An antidote counters a poison; a rebuttal counters an argument. A symptom is caused by a disease, a doctor gives a vaccine, and a remedy and a cure are near-synonyms rather than opposing forces.","difficulty":"very-hard","source":"AMCAT · CAT"},
  {"id":"apt-verbal-placement-228","question":"Read the passage and choose the conclusion it best supports.\n\nPassage: In a survey, 70% of a firm's employees said they would prefer a four-day week with longer days to a five-day week. In the trial that followed, however, many of those who switched reported feeling more tired by Thursday than they had felt by Friday before.","options":["What employees say they prefer may not match how a change actually affects them","The four-day week should be abandoned at once","The survey was badly designed","Most employees regretted switching to the four-day week"],"answer":0,"explanation":"The passage contrasts a stated preference with the experienced effect, and the first option says exactly that. 'Abandoned at once' and 'badly designed' go beyond the evidence, and 'many' reported tiredness, which is not the same as 'most' regretting the switch.","difficulty":"hard","source":"Infosys · Accenture"},
  {"id":"apt-verbal-placement-229","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: These scraps, stuck to the bottom of the pan, are what chemists call products of the Maillard reaction.\nQ: Cooks have long known that meat browned in a hot pan tastes better than meat that is simply boiled.\nR: The reaction needs temperatures above about 140 °C, which water cannot reach while it is boiling.\nS: Browning leaves behind dark scraps that dissolve into a sauce and carry much of the flavour.\nT: That is why a stew made from browned meat tastes richer than one made from raw meat, even after hours of the same simmering.","options":["QSRPT","SQPRT","QSPRT","QPSRT"],"answer":2,"explanation":"Q states the kitchen fact; S introduces the scraps; P ('These scraps') names the reaction; R ('The reaction') explains why boiling cannot produce it; T draws the consequence. In QSRPT, 'The reaction' appears before any reaction has been named; P cannot precede S because 'These scraps' needs S.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-230","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: But the stone itself held a second clue.\nQ: In 1799, soldiers digging near the town of Rosetta found a slab carved with the same decree in three scripts.\nR: One of them was Greek, which scholars could read, so the meaning of the other two was known in advance.\nS: Matching names in the Greek to ringed groups of signs in the hieroglyphs let scholars begin assigning sounds to signs.\nT: Knowing what a text means, however, is not the same as knowing how its script works.\nU: Over two decades, that slow matching turned an unreadable script into a readable language.","options":["QTRPSU","QRPTSU","QRTPSU","QRTSPU"],"answer":2,"explanation":"Q finds the stone; R ('One of them') gives the Greek and the known meaning; T ('however') says meaning is not enough; P ('But … a second clue') answers T; S describes that clue; U ('that slow matching') needs S. In QRPTSU the 'second clue' arrives before the problem it solves; QRTSPU puts the clue's details before the clue is announced.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-231","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Most phone batteries lose capacity fastest when they are kept fully charged and warm.\n2. Charging to about 80% and avoiding heat can noticeably extend a battery's life.\n3. Many phones now offer a setting that pauses charging at that level overnight.\n4. The first call from a handheld mobile phone was made in 1973.\n5. Such small habits matter because a battery's decline is gradual and easy to ignore until it is severe.","options":["4","5","2","3"],"answer":0,"explanation":"The paragraph is practical advice on battery care: the cause of wear (1), the remedy (2), a phone feature that applies it (3, 'that level' needs 2), and why it matters (5). The date of the first mobile call is a historical aside.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-232","question":"Read the passage and choose the option that best summarises it.\n\nPassage: Most new restaurants close within a few years, and the usual explanation is bad food or poor service. A study of closures found something less dramatic: many of the failed restaurants had good reviews, but their owners had underestimated fixed costs such as rent, which consumed the margin that good reviews could not grow quickly enough.","options":["Bad food and poor service are the main reasons restaurants close","Many restaurants close not because diners dislike them but because fixed costs outrun the income that good reviews bring","Restaurant owners should spend less on rent and more on marketing","Restaurants with good reviews almost never fail"],"answer":1,"explanation":"The passage replaces the usual explanation (bad food) with a financial one (fixed costs exceeding the income reviews generate). It says reviewed restaurants did fail, contradicts the 'bad food' option, and offers no advice about marketing.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-233","question":"Critical reasoning. Our main competitor cut its prices by 10% and its market share rose. So if we cut our prices by 10%, our market share will rise as well.\nThe argument assumes which of the following?","options":["A price cut of more than 10% would be impossible for us","The competitor's prices were higher than ours before its cut","Market share matters more than profit","Our customers would respond to a price cut roughly as the competitor's customers did"],"answer":3,"explanation":"The argument transfers a result from one firm to another, so it needs the two situations to be comparable, in particular the customers' response to price. The relative price level, the importance of share versus profit, and larger cuts are not needed for the conclusion.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-234","question":"Critical reasoning. Cities with more police officers per resident also have more recorded crime. Therefore hiring more police officers increases crime.\nWhich is the most serious flaw in this reasoning?","options":["It assumes that police officers themselves commit crimes","It ignores that cities may hire more police because they already have more crime","It ignores the cost of hiring police officers","It does not say how many cities were studied"],"answer":1,"explanation":"A correlation between police numbers and crime is just as well explained by causation running the other way: high-crime cities hire more officers. The argument assumes a direction it has not shown. The other options are not the inference error at the heart of the argument.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-235","question":"Read the passage and choose the conclusion it best supports.\n\nPassage: A hospital replaced paper prescriptions with an electronic system. Errors caused by illegible handwriting disappeared, but a new kind of error appeared: doctors picking the wrong drug from a drop-down list of similar names. Overall, prescription errors fell by a third.","options":["Removing one source of error can introduce another, even when the overall result is an improvement","Electronic systems eliminate prescription errors","Drop-down lists are more dangerous than handwriting","Doctors were careless with the new system"],"answer":0,"explanation":"The passage reports one error type gone, a new one created, and a net fall: the first option captures all three. Errors did not vanish, the net fall shows the lists were not more dangerous overall, and nothing says doctors were careless rather than misled by similar names.","difficulty":"very-hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-236","question":"Read the passage and answer the question.\n\nPassage: The word 'serendipity' is often used as if it meant pure luck. The writer who coined it in the eighteenth century meant something narrower: discoveries made by accident by people sharp enough to recognise what they had stumbled on. On this view, the mould that contaminated a scientist's dish was luck; noticing that the bacteria around it had died was not. Chance supplies the occasion, but only a prepared mind turns it into a discovery.\n\nQuestion: Which of the following best states the main point of the passage?","options":["The word 'serendipity' was coined by a scientist","Most scientific discoveries are made by accident","Luck matters more than preparation in research","Serendipity, properly understood, combines chance with the insight to recognise what chance has offered"],"answer":3,"explanation":"The passage corrects the 'pure luck' reading: the original meaning joins accident with recognition, as the last sentence states. It makes no claim about most discoveries, the coiner was a writer, and the passage gives preparation at least equal weight with luck.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-237","question":"Read the passage and answer the question.\n\nPassage: The word 'serendipity' is often used as if it meant pure luck. The writer who coined it in the eighteenth century meant something narrower: discoveries made by accident by people sharp enough to recognise what they had stumbled on. On this view, the mould that contaminated a scientist's dish was luck; noticing that the bacteria around it had died was not. Chance supplies the occasion, but only a prepared mind turns it into a discovery.\n\nQuestion: The example of the mould is used to:","options":["prove that the scientist was unusually lucky","separate the part of a discovery that was chance from the part that was not","show that contamination usually ruins experiments","illustrate a meaning of the word that is now obsolete"],"answer":1,"explanation":"The sentence splits the event in two: the contamination 'was luck', the noticing 'was not'. That division is the passage's whole point. The example does not generalise about contamination, it denies that the discovery was mere luck, and the passage argues the original meaning is the correct one, not an obsolete one.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-238","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe professor, whom everyone / believed would retire this year, / has signed / a new three-year contract.","options":["believed would retire this year,","The professor, whom everyone","has signed","No error"],"answer":1,"explanation":"Strip out 'everyone believed': the professor would retire, so the pronoun is the subject of 'would retire' and must be 'who'. The words 'everyone believed' in between make 'whom' look right, which is the trap.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-239","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHe is senior than me / in the department, / but I have more / experience in sales.","options":["but I have more","He is senior than me","No error","in the department,"],"answer":1,"explanation":"Senior, junior, superior, inferior and prior are Latin comparatives that take 'to', not 'than': 'He is senior to me'. The other parts are correct.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-240","question":"Fill in the blank.\nBy this time next year, she ___ at the firm for a full decade.","options":["has been working","will have been working","will be working","would work"],"answer":1,"explanation":"'By this time next year' looks back from a future point, and 'for a full decade' measures a duration up to it: future perfect continuous. 'Will be working' describes an action in progress then but cannot carry the duration up to that point.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-241","question":"Choose the word that best completes the sentence.\nThe company has ___ a loss of ₹20 crore this quarter.","options":["made up","suffered from","done","incurred"],"answer":3,"explanation":"The standard collocation is to incur a loss (or a cost, a debt). 'Suffer a loss' would also work, but 'suffered from' needs an illness or a condition, not a figure; 'made up' means compensated for, and one does not 'do' a loss.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-242","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe once-thriving port town is now MORIBUND, its warehouses empty and its young people gone.","options":["peaceful and quiet","overcrowded","in terminal decline","rebuilt"],"answer":2,"explanation":"Moribund (from Latin 'dying') describes something near its end and without vitality. The details that follow, empty warehouses and departed young people, confirm decline, not calm or renewal.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-243","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe manager's praise was so PERFUNCTORY that the team barely registered it.","options":["done as a routine, without real interest","excessive","heartfelt","sarcastic"],"answer":0,"explanation":"Perfunctory means carried out with minimal effort, as a formality, which is why the team hardly noticed it. 'Heartfelt' is the opposite; 'excessive' praise would be noticed; nothing indicates mockery.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-244","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nThe new CFO is known throughout the industry for her PROBITY.","options":["laziness","inquisitiveness","dishonesty","modesty"],"answer":2,"explanation":"Probity means strict honesty and integrity, so its opposite is dishonesty. 'Inquisitiveness' is the trap for those who link probity with 'probe'.","difficulty":"hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-245","question":"Choose the pair of words that best fills the blanks.\nThe data were ___ rather than conclusive: they hinted at a link but could not ___ it.","options":["irrelevant ... suggest","suggestive ... establish","suggestive ... obscure","decisive ... prove"],"answer":1,"explanation":"'Rather than conclusive' and 'hinted at' both call for a word meaning indicative but not proof: suggestive. What such data cannot do is establish the link. 'Decisive' contradicts 'rather than conclusive'; 'obscure' makes no sense with 'could not'.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-246","question":"Choose the option that best completes the paragraph.\nEarly electric cars failed not because the technology was poor but because there was nowhere to charge them. Petrol stations, by contrast, were everywhere. A driver choosing a car was really choosing a network, and ________.","options":["drivers simply preferred the sound of petrol engines","petrol engines were more efficient than electric motors","for decades, the network that already existed won","electric cars were therefore too expensive to build"],"answer":2,"explanation":"The paragraph's logic is that cars were bought as part of a refuelling network; the ending must say which network prevailed. Cost, efficiency and engine sound are explanations the paragraph has just set aside ('not because the technology was poor').","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-247","question":"Critical reasoning. A city plans to reduce litter in its parks by doubling the number of litter bins.\nWhich of the following, if true, most strongly supports the plan?","options":["Some park visitors already take their litter home","Litter bins are cheap to buy and install","Surveys show that most park litter is dropped at spots where no bin is in sight","Litter is also a serious problem on the city's streets"],"answer":2,"explanation":"The plan works only if a lack of nearby bins causes littering; the survey shows exactly that. Cost makes the plan affordable, not effective; street litter is a different problem; visitors who take litter home are not the ones the plan targets.","difficulty":"hard","source":"TCS NQT · Accenture"},
  {"id":"apt-verbal-placement-248","question":"If all three statements are true, which of the following must be FALSE?\nEvery employee who works remotely attends the Monday call. Some members of the sales team do not attend the Monday call. Meera is a member of the sales team.","options":["Some members of the sales team work remotely","Every member of the sales team works remotely","Meera does not attend the Monday call","Meera works remotely"],"answer":1,"explanation":"The sales members who skip the call cannot be remote workers (every remote worker attends), so not every sales member works remotely. Each of the other options could be true: nothing fixes whether Meera is remote or attends, or whether some other sales members work remotely.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-verbal-placement-249","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nThe new procurement rules were meant to LEVEL THE PLAYING FIELD for small suppliers.","options":["reduce the number of competing suppliers","make the rules simpler to read","favour small suppliers over large ones","give everyone a fair and equal chance to compete"],"answer":3,"explanation":"Levelling the playing field removes advantages so that all competitors face the same conditions. It aims at fairness, not at tilting things towards the small suppliers.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-250","question":"Choose the meaning of the phrasal verb in capitals as used in the sentence.\nThe manager asked the team to IRON OUT the remaining problems before the launch.","options":["resolve","ignore","report","list"],"answer":0,"explanation":"To iron out problems is to smooth them away, i.e. resolve them, as an iron removes creases.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-251","question":"In which sentence is 'imply' or 'infer' used correctly?","options":["Are you inferring that I lied to you?","I implied from his tone that he was upset.","The data infers a link between diet and sleep.","From her silence, I inferred that she disagreed."],"answer":3,"explanation":"A speaker or a piece of evidence implies (suggests); a listener infers (concludes). So I infer from her silence, but 'you imply that I lied' and 'the data implies a link'. The last option reverses the roles.","difficulty":"hard","source":"Capgemini · CAT VARC"},
  {"id":"apt-verbal-placement-252","question":"In which sentence is 'continual' or 'continuous' used correctly?","options":["The factory runs on a continuous supply of power, with no breaks at all.","The rain was continual for six hours without a single pause.","The continuous interruptions, every few minutes, made it impossible to work.","Her continuous visits to the clinic, every Monday, worried us."],"answer":0,"explanation":"Continuous means without any break; continual means repeated again and again with gaps. Unbroken power is continuous. Interruptions every few minutes and weekly visits are continual; six hours of rain without a pause is continuous.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-253","question":"Choose the pair that has the same relationship as SCRIBBLE : WRITE.","options":["mumble : speak","shout : speak","read : write","type : write"],"answer":0,"explanation":"To scribble is to write carelessly and illegibly; to mumble is to speak carelessly and indistinctly. Shouting is loud, not careless; reading is a different activity; typing is just another way of writing, not a sloppy one.","difficulty":"very-hard","source":"AMCAT · CAT"},
  {"id":"apt-verbal-placement-254","question":"Read the passage and answer the question.\n\nPassage: The minister announced that the scheme had been 'an outstanding success', citing the number of application forms distributed. How many of those forms were filled in, and how many applicants received anything, the announcement did not say.\n\nQuestion: The author implies that:","options":["the minister measured activity rather than results","the scheme was a complete failure","the minister lied about the number of forms distributed","the forms were badly designed"],"answer":0,"explanation":"The author contrasts the figure cited (forms handed out) with the figures that would show results (forms completed, benefits received). That implies the measure was of activity. The author does not claim the scheme failed, criticises no form design, and does not dispute the figure given.","difficulty":"very-hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-255","question":"Choose the best replacement for the part in capitals. If no change is needed, choose \"No improvement\".\nThe new leave policy is applicable FOR ALL employees who joined after 2020.","options":["on all employees","No improvement","to all employees","for every employees"],"answer":2,"explanation":"'Applicable' takes the preposition 'to': a rule is applicable to someone. 'For every employees' also breaks agreement, since 'every' needs a singular noun.","difficulty":"moderate","source":"Wipro · AMCAT"},
  {"id":"apt-verbal-placement-256","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Their idea was to charge a tiny fee for every email sent, too small to bother a person but enough to ruin a spammer sending millions.\nQ: In the early 2000s, some engineers proposed an elegant fix for email spam.\nR: The idea foundered on a practical problem: no one could agree on who would collect the fees, or how.\nS: Spam was eventually curbed by something far less elegant: filters that learned to recognise it.","options":["QRPS","QPSR","PQRS","QPRS"],"answer":3,"explanation":"Q introduces the engineers; P ('Their idea') describes the fix; R ('The idea foundered') explains why it failed; S ('eventually', 'less elegant') gives what worked instead, contrasting with Q's 'elegant fix'. R before P would reject an idea not yet described.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-257","question":"Choose the word closest in meaning to the word in capitals as used in the sentence.\nDespite the evidence against him, the official remained OBDURATE and refused to admit any mistake.","options":["ambiguous","obedient","remorseful","unyielding"],"answer":3,"explanation":"Obdurate means stubbornly refusing to change one's opinion or course. 'Remorseful' is close to its opposite; 'obedient' sounds similar but means the reverse of defiance.","difficulty":"hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-258","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Attention finally turned from the leaves to the soil.\nQ: For years, a vineyard's best-known plot produced grapes that ripened unevenly, and nobody could say why.\nR: The growers tried pruning the vines differently and thinning the leaves, with no effect.\nS: A survey found a band of clay running under half the plot, holding water long after the rest had dried.\nT: Drainage pipes laid along it evened out the ripening within two seasons.","options":["RQPST","QRSPT","QRPST","QPRST"],"answer":2,"explanation":"Q states the problem; R gives the failed leaf-based fixes; P ('finally', 'from the leaves') follows those failures; S reports what the soil survey found; T ('along it') needs S's band of clay immediately before it. QRSPT separates 'it' from the band; QPRST makes 'finally' come before the attempts.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-259","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Children, it turns out, do not learn this rule from being corrected.\nQ: English-speaking children go through a phase of saying 'goed' and 'runned', even after they have used 'went' and 'ran' correctly.\nS: The errors are a sign of progress: the child has worked out the regular past tense and is applying it everywhere.\nT: They work it out from patterns in what they hear, and only later learn the exceptions one by one.","options":["QPST","QSTP","SQPT","QSPT"],"answer":3,"explanation":"Q describes the errors; S ('The errors') reinterprets them as a rule being applied; P ('this rule') needs S; T ('They work it out') says how children do learn it, answering P's denial. QSTP puts the explanation before the claim it answers; QPST has 'this rule' before any rule is mentioned.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-260","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. A good password manager generates a different random password for every site.\n2. If one site is breached, the stolen password is useless anywhere else.\n3. The user has to remember only a single master password.\n4. Many early computers were programmed using punched cards.\n5. That master password therefore needs to be long and never reused.","options":["5","2","4","3"],"answer":2,"explanation":"Sentences 1, 2, 3 and 5 explain how a password manager works and what it asks of the user (5 depends on 3). Sentence 4, about punched cards, is computing history with no link to the argument.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-261","question":"Read the passage and choose the option that best summarises it.\n\nPassage: Economists once assumed that people save too little for retirement because they cannot do the arithmetic. Yet when firms stopped asking workers to opt into pension schemes and instead enrolled them automatically, leaving them free to opt out, participation jumped from under half to over ninety per cent. The workers' arithmetic had not changed; only the default had.","options":["Most workers are poor at arithmetic","How much people save depends heavily on the default option, not just on their ability to calculate what they need","Automatic enrolment forces workers to save against their will","Pension schemes are more popular today than they used to be"],"answer":1,"explanation":"The passage uses automatic enrolment to show that the default, not calculating ability, drove the change. It does not claim workers are bad at arithmetic (that was the old assumption it questions), they could opt out, and it makes no claim about popularity over time.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-262","question":"Critical reasoning. A study found that people who drink green tea every day have 20% lower rates of heart disease than people who do not. A researcher concludes that drinking green tea reduces the risk of heart disease.\nWhich of the following, if true, most weakens the researcher's conclusion?","options":["Green tea is expensive in some countries","The daily tea drinkers in the study also exercised more and smoked less than the others","Black tea is more popular than green tea worldwide","Some patients with heart disease drink green tea every day"],"answer":1,"explanation":"If the tea drinkers also lived healthier lives, exercise and not smoking could explain the 20% gap, so the tea may do nothing. A lower rate is compatible with some tea drinkers having heart disease; price and popularity are irrelevant.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-263","question":"Critical reasoning. An airport plans to cut security queues by installing new scanners that process bags in half the time of the current ones.\nThe plan depends on which assumption?","options":["Passengers prefer shorter queues to longer ones","The new scanners cost less than the current ones","Bag scanning, rather than another step such as ID checks, is what currently limits how fast the queue moves","Every passenger carries at least one bag"],"answer":2,"explanation":"Speeding up a step that is not the bottleneck does not shorten a queue; the plan works only if scanning is the slowest step. Preference for short queues and cost do not affect whether the plan works, and not every passenger needs a bag for faster scanning to help.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-264","question":"Critical reasoning. All ten of a firm's top salespeople last year used its new customer-tracking tool. However, 90% of all its salespeople used the tool.\nWhat does the second fact most strongly suggest?","options":["The 10% who did not use the tool found it useless","The tool made the salespeople less effective","The top performers did not need the tool","Using the tool does little to distinguish the top performers from the rest"],"answer":3,"explanation":"If almost everyone used the tool, it is no surprise that the top ten did, so their use is weak evidence that the tool caused their success. Nothing shows the tool did harm, that top performers did not need it, or why the 10% did not use it.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-265","question":"Read the passage and answer the question.\n\nPassage: Ancient Roman concrete has outlasted much modern concrete, especially in sea walls. Researchers long credited the volcanic ash in its mix. Recent analysis points to something else as well: small white lumps of lime, once dismissed as signs of careless mixing. When cracks form and water seeps in, these lumps dissolve and recrystallise, sealing the cracks. What looked like a flaw was, in effect, a repair kit.\n\nQuestion: According to the passage, the lime lumps were once regarded as:","options":["evidence of careless mixing","a sign of damage by seawater","the main source of the concrete's strength","later repairs added to old structures"],"answer":0,"explanation":"The passage says the lumps were 'once dismissed as signs of careless mixing'. The strength was credited to the volcanic ash, and nothing suggests they were taken for repairs or seawater damage.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-266","question":"Read the passage and answer the question.\n\nPassage: Ancient Roman concrete has outlasted much modern concrete, especially in sea walls. Researchers long credited the volcanic ash in its mix. Recent analysis points to something else as well: small white lumps of lime, once dismissed as signs of careless mixing. When cracks form and water seeps in, these lumps dissolve and recrystallise, sealing the cracks. What looked like a flaw was, in effect, a repair kit.\n\nQuestion: The final sentence suggests that the earlier view of the lime lumps:","options":["was correct about their chemistry but wrong about their age","mistook a useful feature for a defect","was based on studies of modern concrete","overstated the lumps' importance"],"answer":1,"explanation":"'What looked like a flaw was … a repair kit' says the lumps were misread as a defect when they actually help the concrete. The earlier view understated, not overstated, them, and the passage says nothing about their age or about what the earlier studies examined.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-267","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nUnless you do not submit / the form by Friday, / your application / will be rejected.","options":["your application","Unless you do not submit","the form by Friday,","No error"],"answer":1,"explanation":"'Unless' already means 'if not', so 'unless you do not submit' is a double negative that says the opposite of what is intended. It should be 'Unless you submit' or 'If you do not submit'.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-268","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe new intern is / more smarter than / anyone else / in the batch.","options":["more smarter than","anyone else","The new intern is","No error"],"answer":0,"explanation":"'Smarter' is already comparative, so 'more smarter' is a double comparative. 'Anyone else' is correct: the intern is compared with the others, not with himself.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-269","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nA large amount of / applicants / have applied for / the two vacancies.","options":["applicants","A large amount of","No error","have applied for"],"answer":1,"explanation":"'Amount' is for uncountable nouns (an amount of money); for countable nouns like applicants, use 'number': 'A large number of applicants have applied'. With 'a number of', the plural verb is correct.","difficulty":"hard","source":"AMCAT · Infosys"},
  {"id":"apt-verbal-placement-270","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nNeither the manager / or the director / attended / the review meeting.","options":["or the director","attended","No error","Neither the manager"],"answer":0,"explanation":"'Neither' pairs with 'nor', not 'or': 'Neither the manager nor the director attended'. 'Either' is the word that pairs with 'or'.","difficulty":"moderate","source":"Wipro · CoCubes"},
  {"id":"apt-verbal-placement-271","question":"Fill in the blank.\nThe lights are off and nobody is answering the door; they ___ left already.","options":["can have","would have","should have","must have"],"answer":3,"explanation":"'Must have' expresses a confident deduction about the past from present evidence. 'Should have' suggests what was expected or advisable; 'can have' is not used for positive deductions; 'would have' needs a condition.","difficulty":"hard","source":"Infosys · Accenture"},
  {"id":"apt-verbal-placement-272","question":"Fill in the blank with the correct preposition.\nThe new CEO is averse ___ taking unnecessary risks.","options":["from","against","to","of"],"answer":2,"explanation":"'Averse' takes 'to': averse to risk, averse to taking risks. 'From' and 'of' come from confusing it with 'away from' and 'afraid of'.","difficulty":"very-hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-273","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe startup's growth was MERCURIAL: record months were followed by sudden slumps.","options":["secretive","steady and reliable","unpredictably changeable","extremely rapid"],"answer":2,"explanation":"Mercurial means subject to sudden, unpredictable changes, as the swings between records and slumps show. 'Extremely rapid' is the trap for those who think of the speedy messenger god Mercury.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-274","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe court's ruling was SALUTARY: painful for the company, but a lesson the whole industry needed.","options":["widely ignored","celebratory","harsh and unjust","beneficial, even if unwelcome"],"answer":3,"explanation":"Salutary describes something that does good, often in an unpleasant way, which is exactly what 'painful … but a lesson … needed' says. 'Harsh and unjust' keeps the pain but drops the benefit.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-275","question":"Choose the word or phrase opposite in meaning to the word in capitals as used in the sentence.\nThe negotiator remained IMPERTURBABLE throughout the hostile questioning.","options":["impolite","well prepared","easily agitated","unfriendly"],"answer":2,"explanation":"Imperturbable means impossible to upset, calm under pressure. The opposite is easily agitated. Unfriendly and impolite describe manners, not composure.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-276","question":"Choose the pair of words that best fills the blanks.\nThe scientist was careful to ___ her claims, presenting the result as a ___ finding that still needed to be replicated.","options":["exaggerate ... tentative","retract ... confirmed","hedge ... definitive","hedge ... tentative"],"answer":3,"explanation":"'Careful' and 'still needed to be replicated' point to caution: she hedged (qualified) her claims and called the finding tentative. 'Definitive' and 'confirmed' contradict the need for replication; 'exaggerate' contradicts 'careful'.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-277","question":"Choose the sentence that best fills the blank.\nMost people assume that a crowded restaurant must be good. ________. A restaurant that seats its first customers by the window, where passers-by can see them, can set off this chain on an otherwise quiet evening.","options":["Diners use other diners as a signal of quality, so a few early customers can draw in many more","Restaurant critics rarely visit on quiet evenings","Window tables are usually the least popular seats in a restaurant","Crowded restaurants often have slower service and higher prices"],"answer":0,"explanation":"The last sentence refers to 'this chain', so the blank must describe a chain reaction; the first option does (customers attract customers). Service, seat popularity and critics introduce no chain at all.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-278","question":"In a company, 60% of employees are engineers. Half of the engineers work remotely, and a quarter of the other employees work remotely.\nWhich of the following must be true?","options":["Half of all employees work remotely","More than half of the remote workers are engineers","Engineers are more productive when working remotely","Most non-engineers work remotely"],"answer":1,"explanation":"Remote engineers are 30% of all staff and remote non-engineers 10%, so engineers make up 30 / 40 = 75% of remote workers. Only 40% of staff work remotely, only a quarter of non-engineers do, and productivity is never mentioned.","difficulty":"hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-279","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nThe minister's promise of a government job for every graduate was PIE IN THE SKY.","options":["an unrealistic hope","a generous reward","a secret agreement","a carefully costed plan"],"answer":0,"explanation":"'Pie in the sky' is a pleasant prospect that is very unlikely to come true. 'A carefully costed plan' is close to its opposite.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-280","question":"In which sentence is 'begs the question' used in its traditional, logical sense?","options":["His late arrival begs the question: where was he all morning?","The reporter begged the question to the minister twice.","The rising costs beg the question of who will pay for the project.","Saying the policy is right because it is the correct policy begs the question."],"answer":3,"explanation":"Traditionally, to beg the question is to assume in a premise the very conclusion being argued for, as in the circular first sentence. The second and fourth use it in the popular sense 'raise the question'; the third misuses it entirely.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-281","question":"Choose the word that completes the analogy.\nCARTOGRAPHER : MAPS :: LEXICOGRAPHER : ?","options":["manuscripts","dictionaries","languages","letters"],"answer":1,"explanation":"A cartographer compiles maps; a lexicographer compiles dictionaries. A lexicographer studies words in languages, but the product, which is what the analogy pairs, is the dictionary.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-282","question":"Choose the pair that has the same relationship as INDOLENT : WORK.","options":["diligent : effort","taciturn : talk","gregarious : people","voracious : eat"],"answer":1,"explanation":"An indolent person avoids work; a taciturn person avoids talk. The other pairs show the opposite relationship: a voracious person eats a lot, a gregarious person seeks company, a diligent person puts in effort.","difficulty":"very-hard","source":"AMCAT · CAT"},
  {"id":"apt-verbal-placement-283","question":"Read the passage and choose the conclusion it best supports.\n\nPassage: A museum removed the labels from beside its paintings for a month. Visitors spent, on average, twice as long in front of each painting, but in exit surveys they rated their visit lower than visitors in the month before.","options":["Labels make paintings harder to understand","The museum should never use labels again","Visitors dislike paintings that hang without frames","Spending more time looking at art does not necessarily make a visit more satisfying"],"answer":3,"explanation":"Time spent went up while satisfaction went down, so more looking did not bring more enjoyment. The data do not show that labels hinder understanding (if anything the reverse), frames are not mentioned, and 'never' is far too strong.","difficulty":"hard","source":"Infosys · Accenture"},
  {"id":"apt-verbal-placement-284","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: A spreadsheet that took a clerk a week to recalculate by hand could now be redone in seconds.\nQ: VisiCalc, released in 1979, was the first electronic spreadsheet for personal computers.\nR: Businesses bought computers just to run it, which is why it is often called the first 'killer app'.\nS: That speed meant that, for the first time, managers could ask 'what if?' and see the answer at once.","options":["QPSR","PQSR","QRPS","QSPR"],"answer":0,"explanation":"Q names the program; P describes its speed; S ('That speed') draws out the consequence; R gives the commercial result and needs 'it' to refer back to VisiCalc. S cannot precede P because 'That speed' has nothing to refer to.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-285","question":"Critical reasoning. Over five years, the number of cars registered in a city rose by 20%, yet the number of road deaths fell by 30%.\nWhich of the following, if true, best explains this?","options":["During those years the city lowered speed limits and built protected crossings at its most dangerous junctions","Most of the new cars were bought by families with young children","New cars cost more than they did five years earlier","Ridership on the city's buses also rose during the period"],"answer":0,"explanation":"Lower speeds and safer junctions reduce the chance that a crash happens and that it kills, which can outweigh more cars. Car prices, who bought the cars and bus ridership do not explain why the roads became safer per car.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-286","question":"Which of these conditional sentences about a late vendor is grammatically correct?","options":["Were the vendor to miss the deadline again, we will cancel the contract.","If the vendor was to miss the deadline again, we will cancel the contract.","If the vendor were to miss the deadline again, we would cancel the contract.","If the vendor would miss the deadline again, we would cancel the contract."],"answer":2,"explanation":"For an unlikely future condition, 'were to' in the if-clause pairs with 'would' in the main clause. The second pairs a hypothetical with 'will'; the third puts 'would' in the if-clause; the fourth inverts correctly but then uses 'will'.","difficulty":"hard","source":"Capgemini · Accenture"},
  {"id":"apt-verbal-placement-287","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The second group, told nothing, did the same work but showed no change at all.\nQ: In one study, half of a group of hotel cleaners were told that their daily work already met official guidelines for an active lifestyle.\nR: A month later, those cleaners had lost weight and lowered their blood pressure, though their workload was unchanged.\nS: Belief, it seems, can change the body even when behaviour does not.","options":["QPRS","RQPS","QRPS","QRSP"],"answer":2,"explanation":"Q sets up the informed half; R ('those cleaners') reports their result; P ('The second group') supplies the comparison; S draws the conclusion. In QPRS, R's 'those cleaners' would wrongly attach to the second group, which showed no change; S cannot come before the control group, which is what makes the conclusion valid.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-288","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: This made tulips the first speculative bubble on record, or so the story goes.\nQ: In the 1630s, prices for rare tulip bulbs in the Dutch Republic rose to astonishing levels.\nR: Contracts for single bulbs reportedly changed hands for the price of a house.\nS: Historians who have studied the surviving court and trade records tell a more modest tale.\nT: Most of the trading was confined to a small circle of merchants, and few people were ruined when prices fell.\nU: The legend of mass bankruptcy, it appears, owes more to later moralising pamphlets than to the evidence.","options":["QRPTSU","QRSPTU","QPRSTU","QRPSTU"],"answer":3,"explanation":"Q and R give the famous facts; P ('This made … or so the story goes') sums up the popular story and signals doubt; S introduces the historians' view; T gives their evidence; U concludes. QRSPTU puts the historians' rebuttal before the story it rebuts; QRPTSU gives the evidence before saying whose it is.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-289","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Octopuses can change the colour and texture of their skin in a fraction of a second.\n2. They do this with thousands of pigment cells controlled directly by the nervous system.\n3. Remarkably, octopuses appear to be colour-blind.\n4. Some researchers think light-sensitive proteins in the skin itself may help them match their surroundings.\n5. Octopus is a popular dish in many Mediterranean countries.","options":["3","5","2","4"],"answer":1,"explanation":"Sentences 1 to 4 form a puzzle and a possible answer: an animal that matches colours it apparently cannot see, perhaps sensing light through its skin. Sentence 5 is about cuisine and plays no part in that puzzle.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-290","question":"Choose the option that best completes the paragraph.\nAn economist was asked why he had carried an umbrella on a sunny day. He replied that the forecast had given a 30% chance of rain. His questioner pointed out that it had not rained. ________","options":["The forecast was later corrected to a 10% chance of rain.","The economist admitted that weather forecasts are usually wrong.","The economist answered that a sensible decision is not proved wrong by a lucky outcome.","The questioner concluded that umbrellas are rarely needed in summer."],"answer":2,"explanation":"The anecdote separates the quality of a decision (based on the odds at the time) from its outcome (no rain). The first option makes that point. Admitting forecasts are wrong, generalising about summer, or revising the forecast all miss it.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-291","question":"Critical reasoning. Since a new manager joined, the support team's average time to resolve a ticket has fallen from three days to two. So the manager deserves the credit.\nThe argument assumes which of the following?","options":["The manager has more experience than her predecessor","The team's size did not change during the period","Customers care more about speed than about the quality of answers","No other change in the period, such as fewer or simpler tickets, accounts for the improvement"],"answer":3,"explanation":"Crediting the manager requires ruling out other causes of the faster resolutions. The fourth option is just one such cause; the first covers the assumption the argument actually needs. Her experience and customers' priorities do not affect the reasoning.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-292","question":"Critical reasoning. Some owls have one ear opening set slightly higher on the head than the other. Researchers argue that this asymmetry helps the owls locate prey in the dark by judging a sound's height.\nWhich of the following, if true, most strengthens the researchers' argument?","options":["Few other bird families have been studied for ear asymmetry","Owl species that hunt by day, using sight, have symmetrical ears","Owls have exceptionally large eyes for their body size","Some owls hunt fish rather than small mammals"],"answer":1,"explanation":"If the feature appears in night hunters that rely on sound and is absent in day hunters that rely on sight, that pattern links the asymmetry to hunting by ear. Large eyes point to vision; prey type and the number of studies say nothing about what the asymmetry does.","difficulty":"very-hard","source":"CAT"},
  {"id":"apt-verbal-placement-293","question":"Critical reasoning. A school banned phones during school hours, and its test scores rose by 8% the following year. The principal says the ban caused the improvement.\nWhich of the following, if true, most weakens the principal's claim?","options":["That same year, the state made its tests shorter and easier for every school","Some students hid their phones and used them anyway","Most teachers supported the ban","Many students complained about the ban"],"answer":0,"explanation":"Easier tests for every school would raise scores whether or not phones were banned, so the 8% rise no longer points to the ban. Students hiding phones slightly weakens it at most; teachers' support and students' complaints say nothing about what caused the rise.","difficulty":"hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-294","question":"Read the passage and answer the question.\n\nPassage: A city once tried to reduce its rat population by paying a bounty for every rat tail handed in. Collections soared, yet the rats did not seem to decline. Inspectors soon found tailless rats running in the sewers: residents had been cutting off the tails and releasing the rats to breed more. The scheme had paid for tails, and tails were what it got.\n\nQuestion: The main point of the passage is that:","options":["rats are harder to kill than officials expected","a reward tied to an easily counted stand-in for a goal can be exploited in ways that defeat the goal","cities should never pay bounties to their residents","inspectors are needed to make sure any public scheme works"],"answer":1,"explanation":"Tails were the countable stand-in for dead rats, and paying for the stand-in rewarded producing tails, not reducing rats. The passage does not ban bounties in general, is not about how hard rats are to kill, and mentions inspectors only as the people who found the trick.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-295","question":"Read the passage and answer the question.\n\nPassage: A city once tried to reduce its rat population by paying a bounty for every rat tail handed in. Collections soared, yet the rats did not seem to decline. Inspectors soon found tailless rats running in the sewers: residents had been cutting off the tails and releasing the rats to breed more. The scheme had paid for tails, and tails were what it got.\n\nQuestion: The final sentence implies that the scheme:","options":["succeeded in reducing the number of rats","failed because too few residents took part","was cancelled once the fraud came to light","achieved exactly what it measured rather than what it was meant to achieve"],"answer":3,"explanation":"'Paid for tails, and tails were what it got' says the scheme hit its own measure while missing its purpose. Participation was high ('collections soared'), nothing is said about cancellation, and the rats did not decline.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-296","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe board has approved / the budget, but / its implementation / have been delayed.","options":["No error","its implementation","have been delayed","The board has approved"],"answer":2,"explanation":"The subject of the second clause is 'its implementation', which is singular, so the verb must be 'has been delayed'. 'The board has approved' is correctly singular.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-297","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nI have been knowing / him since college, / and he has always been / a reliable colleague.","options":["I have been knowing","No error","and he has always been","him since college,"],"answer":0,"explanation":"'Know' is a stative verb and is not normally used in continuous forms: the sentence needs the present perfect, 'I have known him since college'.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-298","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nShe is one of the most / talented engineer / that the company / has ever hired.","options":["talented engineer","No error","that the company","She is one of the most"],"answer":0,"explanation":"'One of the most …' picks one person out of a group, so the noun must be plural: 'one of the most talented engineers'.","difficulty":"moderate","source":"Wipro · CoCubes"},
  {"id":"apt-verbal-placement-299","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHad I known / about the traffic, / I would leave / much earlier.","options":["Had I known","No error","about the traffic,","I would leave"],"answer":3,"explanation":"'Had I known' is an inverted past-perfect condition about the past (= If I had known), so the result clause needs 'would have left'. 'I would leave' belongs to a present or future hypothetical.","difficulty":"very-hard","source":"Product company OA · CAT VARC"},
  {"id":"apt-verbal-placement-300","question":"Which version of the sentence about the writing course is correctly parallel?","options":["The course teaches students to write clearly, argue logically and listening carefully.","The course teaches students to write clearly, logical argument and careful listening.","The course teaches students to write clearly, to argue logically and to listen carefully.","The course teaches students writing clearly, to argue logically and to listen carefully."],"answer":2,"explanation":"Items in a list must share a grammatical form. The first keeps three infinitive phrases. The others mix infinitives with a gerund ('listening', 'writing') or with noun phrases ('logical argument').","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-301","question":"Fill in the blank.\nThe quarterly report, ___ was submitted two weeks late, contained several errors.","options":["who","which","what","that"],"answer":1,"explanation":"The clause between commas adds extra information about a report already identified, so it is non-restrictive, and non-restrictive clauses take 'which', not 'that'. 'Who' is for people and 'what' cannot introduce a relative clause after a noun.","difficulty":"hard","source":"Infosys · Accenture"},
  {"id":"apt-verbal-placement-302","question":"Fill in the blank.\nNot until the final whistle ___ that the match had been fixed.","options":["the fans realised","realised the fans","did the fans realise","the fans did realise"],"answer":2,"explanation":"A sentence that opens with 'Not until …' needs inversion in the main clause, with an auxiliary before the subject: 'did the fans realise'. 'The fans realised' keeps normal order; 'realised the fans' inverts without the auxiliary 'did'.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-303","question":"Choose the word closest in meaning to the word in capitals as used in the sentence.\nAfter twelve hours, the negotiations reached an IMPASSE.","options":["agreement","deadlock","breakthrough","adjournment"],"answer":1,"explanation":"An impasse is a situation in which no progress is possible: a deadlock. 'Adjournment' is a formal pause, which might follow an impasse but is not the same thing.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-304","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nHer criticism, though TRENCHANT, was always fair.","options":["incisive and forceful","unfair and biased","mild","vague"],"answer":0,"explanation":"Trenchant criticism is sharp and to the point. The 'though … always fair' contrast shows that trenchant is not itself unfair; it just makes fairness worth mentioning. 'Mild' is the opposite.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-305","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe firm's claims about its battery life were soon DEBUNKED by independent testers.","options":["exposed as false","publicised","copied","confirmed"],"answer":0,"explanation":"To debunk a claim is to show that it is false or exaggerated. Independent testers 'soon' doing this to a firm's claims fits exposure, not confirmation.","difficulty":"hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-verbal-placement-306","question":"Choose the pair of words that best fills the blanks.\nThe professor's lectures were ___; even the most complex ideas became ___ in her hands.","options":["lucid ... accessible","lucid ... impenetrable","opaque ... accessible","dull ... exciting"],"answer":0,"explanation":"The semicolon introduces an explanation: lectures that make complex ideas accessible are lucid (clear). 'Opaque' contradicts 'accessible', 'impenetrable' contradicts 'lucid', and 'dull … exciting' clashes within the sentence.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-307","question":"Choose the pair of words that best fills the blanks.\nFar from being a ___, the decision to delay the launch was a ___ response to evidence that the product was not ready.","options":["capitulation ... cowardly","triumph ... reckless","capitulation ... prudent","blunder ... impulsive"],"answer":2,"explanation":"'Far from being X, it was Y' needs X negative and Y positive. A capitulation (giving in) is rejected in favour of a prudent (wise) response to evidence. 'Blunder … impulsive' and 'capitulation … cowardly' are both negative; 'triumph … reckless' reverses the contrast.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-308","question":"Which argument follows the same pattern of reasoning as this one?\nIf it rains, the match is cancelled. The match was not cancelled. So it did not rain.","options":["If the code compiles, the tests run. The tests did not run. So the code did not compile.","If the code compiles, the tests run. The tests ran. So the code compiled.","If the code compiles, the tests run. The code did not compile. So the tests did not run.","If the tests ran, the code compiled. The tests ran. So the code compiled."],"answer":0,"explanation":"The original denies the consequence to deny the condition (if P then Q; not Q; so not P). Only the first does the same. The second denies the condition and the fourth affirms the consequence, both invalid; the third is a valid argument but of a different form (if P then Q; P; so Q).","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-309","question":"Statements: All managers are graduates. No graduate is under 21.\nConclusions: I. No manager is under 21. II. Some graduates are managers.\nWhich conclusion(s) follow?","options":["Only II follows","Both I and II follow","Neither follows","Only I follows"],"answer":1,"explanation":"Every manager is a graduate and no graduate is under 21, so no manager is under 21 (I). 'All managers are graduates' converts to 'some graduates are managers' (II), on the standard assumption in these questions that managers exist.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-310","question":"Statements: Some engineers are artists. No artist is lazy.\nConclusions: I. Some engineers are not lazy. II. Some lazy people are not engineers.\nWhich conclusion(s) follow?","options":["Only II follows","Neither follows","Both I and II follow","Only I follows"],"answer":3,"explanation":"The engineers who are artists cannot be lazy, so some engineers are not lazy (I). Nothing says any lazy people exist at all, or where they fall relative to engineers, so II does not follow.","difficulty":"very-hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-311","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nFinishing the migration in one week was A TALL ORDER for a team of three.","options":["a very difficult task","an unusual request","a large purchase","an urgent instruction"],"answer":0,"explanation":"A tall order is a task that is very hard to fulfil. The phrase is about difficulty, not urgency or size of an order of goods.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-312","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nMost board members are still ON THE FENCE about the proposed merger.","options":["strongly opposed","enthusiastic","undecided","uninformed"],"answer":2,"explanation":"To be on the fence is to have not yet chosen a side. It does not imply lack of information, only lack of a decision.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-313","question":"Choose the pair that completes the analogy.\nPRUNE : HEDGE :: EDIT : ?","options":["author","pen","library","manuscript"],"answer":3,"explanation":"You prune a hedge by cutting away what is unwanted; you edit a manuscript the same way. An author does the editing (an agent, not the object), and a pen is a tool.","difficulty":"hard","source":"AMCAT · CAT"},
  {"id":"apt-verbal-placement-314","question":"In which sentence is 'stationary' or 'stationery' used correctly?","options":["The stationery bike in the gym is broken.","The office ran out of stationery, so we wrote on the backs of old reports.","The car remained stationery at the signal.","Please order more stationary for the new joiners."],"answer":1,"explanation":"Stationery (with e, as in envelope) is writing materials; stationary (with a) means not moving. The second and fourth need 'stationary'; the third needs 'stationery'.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-315","question":"Read the passage and answer the question.\n\nPassage: When a bridge in a small town was closed for repairs, the shops on the far side expected to lose customers. Instead, several reported higher sales. The detour, it turned out, sent drivers along their high street, and many of them stopped.\n\nQuestion: Which of the following can be inferred?","options":["The detour will remain in place permanently","Before the closure, many of the drivers now passing these shops did not use that street","Shops on the near side of the bridge lost customers","The closure increased total spending in the town"],"answer":1,"explanation":"The detour 'sent drivers along their high street', which only adds customers if those drivers did not pass that way before. The passage gives no figure for the whole town, says nothing about the near side, and the repairs imply the closure is temporary.","difficulty":"very-hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-316","question":"Choose the option that most logically completes the argument.\nMany cities subsidise new sports stadiums, claiming they bring jobs and spending. Yet studies find little effect on local economies. One reason is that most of the money fans spend at a stadium is money they would otherwise have spent ________.","options":["on building the stadium","in the stadium's own shops","at other local entertainment, such as cinemas and restaurants","on tickets for away games"],"answer":2,"explanation":"The argument explains why stadiums add little: their spending is mostly diverted from other local businesses rather than new. Away games, construction and the stadium's shops do not describe money that would otherwise have stayed in the local economy.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-317","question":"Choose the one word for: a person who speaks several languages fluently.","options":["polymath","linguist","philologist","polyglot"],"answer":3,"explanation":"A polyglot speaks many languages. A linguist studies how language works and need not speak many; a polymath is learned in many fields; a philologist studies the history of languages and texts.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-318","question":"Choose the one word for: a supposed remedy for all problems or diseases.","options":["antidote","palliative","placebo","panacea"],"answer":3,"explanation":"A panacea is a cure-all. A placebo has no active effect, an antidote counters one particular poison, and a palliative relieves symptoms without curing the cause.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-319","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Engineers call this 'technical debt', and like financial debt it accrues interest.\nQ: A team racing a deadline often takes shortcuts: hard-coded values, copied code, tests skipped 'for now'.\nR: Each shortcut saves a day today but makes every later change a little slower and riskier.\nS: Teams that never pay it down end up spending most of their time servicing it, with little left for new features.\nT: The cure is not to avoid every shortcut but to record them and schedule time to repay them.","options":["QRPST","RQPST","QPRST","QRPTS"],"answer":0,"explanation":"Q lists the shortcuts; R ('Each shortcut') gives their cost; P ('this') names that cost and introduces 'interest'; S ('pay it down', 'servicing it') extends the debt metaphor; T offers the remedy. P before R would name a cost not yet described; T before S offers a cure before the full damage is shown.","difficulty":"hard","source":"Product company OA · CAT VARC"},
  {"id":"apt-verbal-placement-320","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The method worked, but only for the kinds of sentence it had been designed for.\nQ: Early machine-translation systems relied on hand-written grammar rules and dictionaries.\nR: Every new idiom, exception or ambiguity required a linguist to write yet another rule.\nS: Later systems abandoned rules altogether and learned from millions of sentences that people had already translated.\nT: Their output was less predictable, but they handled the messiness of real language far better.\nU: As the rule books swelled to thousands of pages, the systems grew slower and more fragile.","options":["QRUPST","QPRUTS","QPURST","QPRUST"],"answer":3,"explanation":"Q describes the rule-based method; P judges it; R explains why it struggled; U ('As the rule books swelled') follows from R's endless new rules; S brings in the replacement; T ('Their output') needs S. In QPURST, the swelling rule books come before the reason they swelled; T cannot precede S because 'Their' would have no referent.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-321","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Coral reefs cover less than one per cent of the ocean floor.\n2. Yet they shelter roughly a quarter of all known marine species.\n3. Their complex structure offers countless niches where fish, crabs and other animals can hide and feed.\n4. When reefs bleach and die, that structure slowly crumbles, and the species it supported vanish with it.\n5. Many coastal resorts promote reef diving as their main attraction.","options":["1","4","3","5"],"answer":3,"explanation":"Sentences 1 to 4 make one ecological argument: small area, huge diversity, explained by structure, lost when the structure collapses. Sentence 5 is about tourism marketing, which none of the others needs or supports.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-322","question":"Read the passage and choose the option that best summarises it.\n\nPassage: It is tempting to judge a medical test by how often it is right. But for a rare disease, a test that is 99% accurate can still be wrong most of the times it says 'positive', because the healthy people it misclassifies vastly outnumber the sick people it correctly identifies. What matters to a patient who tests positive is not the test's accuracy but the chance that a positive result is true.","options":["Rare diseases are usually diagnosed wrongly","Medical tests that are 99% accurate should not be used","For a rare condition, even a very accurate test can give mostly false positives, so its accuracy alone is a misleading guide","Patients should ignore positive test results for rare diseases"],"answer":2,"explanation":"The passage argues that base rates turn a high accuracy into a low chance that a positive result is right, so accuracy is the wrong measure for the patient. It does not reject such tests, claim most diagnoses are wrong, or tell patients to ignore results.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-323","question":"Critical reasoning. A gym chain found that its members who paid annually visited less often, on average, than members who paid month by month, even though the annual members had paid in advance and had more reason to get their money's worth.\nWhich of the following, if true, best explains this finding?","options":["Monthly members who stopped visiting usually cancelled, so the remaining monthly members were mostly regular users","Annual memberships cost less per month than monthly ones","Many annual members joined in January","The gyms are busiest on weekday evenings"],"answer":0,"explanation":"Monthly members who lose interest leave the data, while annual members who lose interest stay counted until their year ends. The comparison is therefore between filtered monthly members and unfiltered annual ones. Price, joining month and peak hours do not explain the gap.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-324","question":"Critical reasoning. Customers who use our app's budgeting feature save more money than customers who do not. So adding the feature to our basic plan will help more customers save.\nThe argument assumes which of the following?","options":["Most customers are on the basic plan","Saving money is the main reason customers use the app","The budgeting feature is easy to use","The feature itself helps people save, rather than people who already save being the ones who choose to use it"],"answer":3,"explanation":"The observed gap could come from self-selection: careful savers seek out budgeting tools. The plan works only if the feature causes the saving. How many customers are on the basic plan or why they use the app does not touch that causal link.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-325","question":"Critical reasoning. An archaeologist argues that an excavated building was a market rather than a temple, because many standardised weights were found inside it.\nWhich of the following, if true, most strengthens the argument?","options":["The weights are made of bronze","Weights of this kind have been found at other known market sites but never at known temples","Some temples kept weights to measure offerings","The building stands close to a river"],"answer":1,"explanation":"The argument treats weights as a marker of trade. Evidence that such weights occur at markets and not at temples makes them a reliable marker. Temples using weights would weaken it; the river and the metal say nothing about the building's purpose.","difficulty":"hard","source":"CAT"},
  {"id":"apt-verbal-placement-326","question":"Critical reasoning. Patients who had a particular operation at Hospital A died within a month more often than patients who had it at Hospital B. A journalist concludes that Hospital B is the safer place for the operation.\nWhich of the following, if true, most weakens the conclusion?","options":["Some patients at Hospital B travelled from other regions","Hospital B is newer than Hospital A","Hospital A is the region's specialist centre and receives most of the highest-risk patients","Hospital A performs the operation more often than Hospital B"],"answer":2,"explanation":"If Hospital A treats far sicker patients, a higher death rate is expected even with equal or better care; the raw comparison is confounded by case mix. A newer building or patients' travel says nothing about risk, and doing the operation more often, if anything, suggests more experience.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-327","question":"Read the passage and answer the question.\n\nPassage: Most of us picture a forest as a crowd of individual trees competing for light. Recent research complicates the picture. Through networks of fungi that wrap their roots, trees can exchange sugars and chemical signals, and older trees appear to send resources to seedlings growing in deep shade. Some researchers go further and describe forests as cooperative communities led by 'mother trees'. Critics caution that the fungi are not charities: they trade nutrients for sugar on their own terms, and what looks like generosity may simply be the network's plumbing.\n\nQuestion: The critics' objection is best described as:","options":["the fungal networks connecting trees do not exist","older trees actually compete with seedlings for light","the cooperative language reads purpose into a process that may serve the fungi's own interests","the research was carried out in too few forests"],"answer":2,"explanation":"The critics accept the networks but reinterpret them: the fungi trade 'on their own terms' and the flows may be 'plumbing', not generosity. They do not deny the networks exist, and the passage mentions neither renewed competition nor sample size.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-328","question":"Read the passage and answer the question.\n\nPassage: Most of us picture a forest as a crowd of individual trees competing for light. Recent research complicates the picture. Through networks of fungi that wrap their roots, trees can exchange sugars and chemical signals, and older trees appear to send resources to seedlings growing in deep shade. Some researchers go further and describe forests as cooperative communities led by 'mother trees'. Critics caution that the fungi are not charities: they trade nutrients for sugar on their own terms, and what looks like generosity may simply be the network's plumbing.\n\nQuestion: Which best describes the author's own position?","options":["The author is chiefly concerned with protecting forests from logging","The author dismisses the recent research as unscientific","The author reports the new findings and the caution about interpreting them without fully endorsing either extreme","The author is convinced that forests are cooperative communities"],"answer":2,"explanation":"The author says the research 'complicates the picture', notes that some go 'further', and gives the critics the last word without taking a side; 'appear to' signals caution. Nothing dismisses the research, and logging is never mentioned.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-329","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHe has went / to the client's office / to resolve / the billing dispute.","options":["No error","to the client's office","He has went","to resolve"],"answer":2,"explanation":"The present perfect needs the past participle: 'has gone', not the simple past 'went'.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-330","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThough he is rich, / yet he lives / in a small flat / near the station.","options":["No error","Though he is rich,","in a small flat","yet he lives"],"answer":3,"explanation":"'Though' already sets up the contrast, so adding 'yet' doubles the connective. Standard English uses one: 'Though he is rich, he lives …' or 'He is rich, yet he lives …'.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-331","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe CEO emphasised on / the need to cut costs / during her address / to the shareholders.","options":["The CEO emphasised on","during her address","No error","the need to cut costs"],"answer":0,"explanation":"'Emphasise' takes a direct object: she emphasised the need. 'On' belongs with the noun: 'laid emphasis on the need'. Mixing the two gives the error.","difficulty":"hard","source":"AMCAT · Infosys"},
  {"id":"apt-verbal-placement-332","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe reason for the delay / is due to / a shortage / of trained staff.","options":["No error","a shortage","The reason for the delay","is due to"],"answer":3,"explanation":"'The reason … is due to' says the same thing twice: a reason is already a cause. Write 'The reason for the delay is a shortage of trained staff' or 'The delay is due to a shortage …'.","difficulty":"very-hard","source":"CAT VARC · Capgemini"},
  {"id":"apt-verbal-placement-333","question":"In which sentence is 'rise' or 'raise' used correctly?","options":["The company will raise salaries by 8% next year.","The sun raises in the east.","Please rise your hand if you have a question.","Prices have raised sharply this quarter."],"answer":0,"explanation":"'Raise' needs an object (you raise something): raise salaries, raise your hand. 'Rise' takes no object (something rises by itself): prices have risen, the sun rises.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-334","question":"Fill in the blank.\nScarcely ___ the server been restarted when the alerts began again.","options":["was","had","did","has"],"answer":1,"explanation":"'Scarcely … when' describes one past event following another immediately and takes the past perfect with inversion: 'Scarcely had the server been restarted when …'. 'Did' cannot combine with 'been restarted'.","difficulty":"hard","source":"Product company OA · CAT VARC"},
  {"id":"apt-verbal-placement-335","question":"Fill in the blank.\nI would rather you ___ the review meeting tomorrow instead of today.","options":["held","will hold","had held","hold"],"answer":0,"explanation":"'Would rather' followed by a different subject takes the past (subjunctive) form for present or future wishes: 'I would rather you held it tomorrow'. 'Had held' would refer to the past.","difficulty":"very-hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-336","question":"Fill in the blank.\nHalfway through the audit, she stopped ___ a cup of tea.","options":["having","to having","have","to have"],"answer":3,"explanation":"'Stop to do' means pause one activity in order to do another; 'stop doing' means cease doing. She paused the audit to have tea; 'stopped having a cup of tea' would mean she gave up drinking it.","difficulty":"very-hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-337","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe CEO's speech was full of PLATITUDES about teamwork and customer focus.","options":["trite, overused remarks","specific proposals","detailed statistics","sharp criticisms"],"answer":0,"explanation":"A platitude is a remark used so often that it carries little meaning, like the vague slogans about teamwork the sentence implies.","difficulty":"hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-338","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe panel found the evidence for the claim TENUOUS at best.","options":["excessive","concealed","convincing","weak or slight"],"answer":3,"explanation":"Tenuous means very thin or weak, and 'at best' signals a poor judgement. 'Convincing' is the opposite.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-339","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe founders were CAVALIER about data privacy until the breach cost them their biggest client.","options":["carelessly unconcerned","secretive","well informed","extremely careful"],"answer":0,"explanation":"Cavalier describes an offhand lack of proper concern. The sentence implies their attitude changed only after a costly breach, which fits carelessness, not caution.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-340","question":"Choose the word that best fills the blank.\nNobody could accuse the reviewer of ___: she praised the film's acting and condemned its script with equal frankness.","options":["erudition","partiality","candour","brevity"],"answer":1,"explanation":"Praising and condemning 'with equal frankness' shows she was even-handed, so she cannot be accused of partiality (bias). Candour is what she did show, so you could not say nobody could accuse her of it.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-341","question":"Choose the pair of words that best fills the blanks.\nThe tone of the memo was ___, but its message was ___: anyone who missed another deadline would be let go.","options":["friendly ... unclear","mild ... unmistakable","mild ... ambiguous","harsh ... vague"],"answer":1,"explanation":"'But' contrasts tone with message, and the colon shows the message was blunt: so a mild tone carrying an unmistakable warning. The other options make the message vague or unclear, which the colon contradicts.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-342","question":"Statements: No laptops are tablets. All tablets are devices.\nConclusions: I. No laptops are devices. II. Some devices are not laptops.\nWhich conclusion(s) follow?","options":["Neither follows","Both I and II follow","Only II follows","Only I follows"],"answer":2,"explanation":"The tablets are devices that are not laptops, so some devices are not laptops (II), taking tablets to exist as these questions assume. Nothing stops laptops from also being devices, so I does not follow.","difficulty":"very-hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-343","question":"Statement: A company has announced a bonus for any employee whose referred candidate is hired.\nConclusions: I. The company wants to attract candidates through its employees' networks. II. Every referred candidate will be hired.\nWhich conclusion(s) follow?","options":["Only II follows","Both I and II follow","Only I follows","Neither follows"],"answer":2,"explanation":"A referral bonus exists to encourage referrals, so I follows. The bonus is paid only 'if hired', which implies that some referred candidates will not be, so II does not follow.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-344","question":"Statement: A theatre's advertisement says, \"Book your tickets early to avoid disappointment.\"\nAssumptions: I. Tickets may sell out. II. People want to avoid disappointment.\nWhich assumption(s) are implicit?","options":["Both I and II are implicit","Neither is implicit","Only I is implicit","Only II is implicit"],"answer":0,"explanation":"Booking early prevents disappointment only if late bookers might miss out, so I is assumed. The advertisement appeals to avoiding disappointment, which works only if people want to avoid it, so II is assumed too.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-345","question":"Statement: Every year, many students in a town fail the mathematics paper of the board exam.\nCourses of action: I. The board should abolish the mathematics paper. II. Schools should identify weak students early and give them extra coaching.\nWhich course(s) of action follow?","options":["Both I and II follow","Only II follows","Only I follows","Neither follows"],"answer":1,"explanation":"A sound course of action tackles the problem without creating a worse one. Abolishing the paper removes the symptom and the subject with it; early identification and coaching addresses the cause.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-346","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nOur competitor's sudden price cut has PUT A SPOKE IN OUR WHEEL.","options":["helped us move faster","obstructed our plans","made us more popular","copied our strategy"],"answer":1,"explanation":"To put a spoke in someone's wheel is to hinder their plans, as a stick jammed into the wheel would stop it turning.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-347","question":"In which sentence is the idiom used INCORRECTLY?","options":["The audit was just the tip of the iceberg; bigger problems emerged later.","The new hire was a dark horse; nobody expected her to win the hackathon.","After the scandal, the minister was given the cold shoulder by his colleagues.","He let the cat out of the bag by keeping the surprise party a secret."],"answer":3,"explanation":"To let the cat out of the bag is to reveal a secret, so it cannot happen by keeping one. The other three use the idioms correctly: being snubbed, an unexpected winner, and a small visible part of a larger problem.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-348","question":"Choose the pair that has the same relationship as OSTENTATIOUS : MODESTY.","options":["eloquent : speech","reckless : caution","cunning : intelligence","generous : charity"],"answer":1,"explanation":"An ostentatious person lacks modesty; a reckless person lacks caution. A generous person shows charity, an eloquent person excels in speech, and cunning involves a kind of intelligence: those pairs show presence, not absence.","difficulty":"very-hard","source":"AMCAT · CAT"},
  {"id":"apt-verbal-placement-349","question":"Read the passage and answer the question.\n\nPassage: Before refrigeration, ice was cut from frozen lakes in New England and shipped as far as India. Much of it melted on the voyage, but enough survived, packed in sawdust in the ships' holds, to make the trade profitable.\n\nQuestion: Which of the following can be inferred?","options":["Sawdust was more valuable than the ice it protected","Ice fetched a high enough price at its destination to cover the loss from melting","Refrigeration was first developed in India","There were no lakes in India"],"answer":1,"explanation":"A trade that loses much of its cargo yet stays profitable must sell what survives at a price that covers the losses. Nothing compares the value of sawdust, claims India had no lakes, or says where refrigeration was invented.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-350","question":"Choose the one word for: a person who endures pain or hardship without showing feelings or complaining.","options":["ascetic","cynic","stoic","hedonist"],"answer":2,"explanation":"A stoic bears hardship calmly without complaint. An ascetic deliberately denies himself comforts, which is a different thing; a cynic distrusts others' motives; a hedonist pursues pleasure.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-351","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The team's answer was to stop asking which accounts were busiest and ask instead which ones were changing.\nQ: A bank's fraud team once flagged accounts with unusually high numbers of transactions.\nR: The rule caught little fraud, because the busiest accounts belonged to shops and payroll services.\nS: A dormant account that suddenly made dozens of small transfers turned out to be a far better warning sign.\nT: What matters, in other words, is a departure from an account's own normal, not from everyone else's.","options":["QRPST","RQPST","QRSPT","QPRST"],"answer":0,"explanation":"Q gives the first rule; R ('The rule') explains its failure; P gives the new question; S is an example that the new question finds; T generalises ('in other words'). R cannot open without Q's rule; in QRSPT, the better warning sign is found before the team changes its question.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-352","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The trick is that the brain does not wait for all the evidence before deciding what it sees.\nQ: Read a familiar sentence quickly and you will probably not notice if one of its letters is wrong.\nR: It guesses from context and early clues, and checks the details only if the guess fails.\nS: This shortcut works almost all of the time, which is exactly why proofreading your own writing is so hard.","options":["QPSR","QRPS","PQRS","QPRS"],"answer":3,"explanation":"Q gives the everyday experience; P ('The trick') introduces the explanation; R ('It guesses') continues it with 'it' = the brain; S ('This shortcut') evaluates it and links it back to proofreading. In QRPS, 'It' in R has no referent; S needs the shortcut described in R.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-353","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. The first vaccines were developed long before anyone understood the immune system.\n2. Edward Jenner noticed that milkmaids who had caught cowpox seemed protected from smallpox.\n3. He tested the idea by infecting a boy with cowpox and later exposing him to smallpox.\n4. Cattle were first domesticated around ten thousand years ago.\n5. Only much later did scientists begin to explain why the method worked.","options":["4","2","5","3"],"answer":0,"explanation":"The paragraph argues that vaccination worked before it was understood: claim (1), observation (2), test (3), later explanation (5). The date of cattle domestication shares only the word 'cow' with the argument.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-354","question":"Choose the option that best completes the paragraph.\nA library that wants to know which books to buy can count how often each book is borrowed. But loan figures miss the books readers consult inside the library and put back, and they say nothing about books readers wanted but could not find. ________","options":["This is why libraries now buy more e-books than printed books.","A buying policy based only on loans will therefore consistently under-buy some of the books readers need.","Most readers prefer borrowing books to reading them in the library.","Libraries should therefore stop counting loans altogether."],"answer":1,"explanation":"Both gaps in the data point the same way: real demand is higher than loans show for some books, so a loans-only policy will under-buy them. Abandoning loan counts overreaches, reader preference is not discussed, and e-books are a new topic.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-355","question":"Critical reasoning. To cut fuel costs, a delivery company plans to have its drivers follow a route-planning app that minimises the total distance driven.\nWhich of the following, if true, most seriously undermines the plan?","options":["The app costs a monthly subscription fee","Many drivers dislike the app's voice instructions","Most of the company's fuel is burned idling in traffic, and the shortest routes run through the most congested streets","Fuel prices are expected to fall next year"],"answer":2,"explanation":"If fuel use is driven by idling rather than distance, routes that are shorter but more congested could burn more fuel, defeating the plan's goal. The fee affects net savings only slightly, the voice is a matter of taste, and falling prices do not change whether the plan saves fuel.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-356","question":"Critical reasoning. Since our new website went live, the number of calls to customer support has dropped. Customers must be finding the answers they need on the site.\nThe conclusion depends on which assumption?","options":["Customers have not simply given up on contacting support, for example because the new site makes the phone number harder to find","The new website cost less to build than the old one","Most customers prefer the website to the phone","Support staff answer calls faster than before"],"answer":0,"explanation":"Fewer calls could mean fewer problems solved, not more, if customers were blocked from calling. The conclusion needs that rival ruled out. Cost, preference and answering speed do not bear on why calls fell.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-357","question":"Company X made a profit in both of the last two years. Last year its revenue rose by 10% while its profit fell by 10%.\nWhich of the following must be true?","options":["Its total costs rose by more than 10%","Its total costs rose by exactly 20%","Its profit fell because it cut its prices","Its number of customers rose by 10%"],"answer":0,"explanation":"Costs = revenue − profit. With revenue R and profit P > 0, new costs are 1.1R − 0.9P, which exceeds 1.1(R − P) by 0.2P, so costs grew by more than 10%. The exact percentage depends on R and P; customers and prices are never mentioned.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-358","question":"Read the passage and answer the question.\n\nPassage: In the 1850s, London's River Thames was effectively an open sewer, yet Parliament ignored proposals for a modern drainage system for years. What finally moved it was not an epidemic but a heatwave: in the summer of 1858 the stench grew so strong that curtains in the Houses of Parliament were soaked in lime to mask it. Within weeks, a bill funding the sewers had passed. Reformers had supplied the arguments for a decade; the smell supplied the urgency.\n\nQuestion: The passage suggests that the bill passed quickly mainly because:","options":["reformers produced new evidence that summer","an epidemic broke out in the city","the heatwave made construction cheaper","lawmakers were personally confronted with the problem"],"answer":3,"explanation":"The smell reached Parliament itself (curtains soaked in lime), and the bill followed within weeks. The passage says it was 'not an epidemic', the arguments were a decade old, and cost is never discussed.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-359","question":"Read the passage and answer the question.\n\nPassage: In the 1850s, London's River Thames was effectively an open sewer, yet Parliament ignored proposals for a modern drainage system for years. What finally moved it was not an epidemic but a heatwave: in the summer of 1858 the stench grew so strong that curtains in the Houses of Parliament were soaked in lime to mask it. Within weeks, a bill funding the sewers had passed. Reformers had supplied the arguments for a decade; the smell supplied the urgency.\n\nQuestion: The final sentence implies that:","options":["the reformers' arguments had been mistaken","Parliament never listens to reformers","sound arguments alone had not been enough to bring about action","bad smells are a cause of disease"],"answer":2,"explanation":"The sentence divides the credit: the reformers had the arguments for ten years, but action came only with the urgency the smell created. It does not call the arguments wrong, makes no medical claim, and 'never' overgeneralises one episode.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-360","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe committee consisting / of five members / have submitted / its final report.","options":["of five members","The committee consisting","have submitted","No error"],"answer":2,"explanation":"The subject is 'the committee', treated here as a single body (note 'its final report'), so the verb must be singular: 'has submitted'. 'Five members' sits inside a modifying phrase and does not control the verb.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-361","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe more you practise, / the more better / you will perform / in the interview.","options":["No error","The more you practise,","you will perform","the more better"],"answer":3,"explanation":"In 'the more …, the …' comparisons, each half takes a single comparative: 'the better you will perform'. 'More better' is a double comparative.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-362","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nShe returned back / to the office / after lunch / to finish the report.","options":["after lunch","She returned back","No error","to the office"],"answer":1,"explanation":"'Return' already means 'go back', so 'returned back' is redundant: 'She returned to the office'.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-363","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHe is the only one of the trainees / who have / cleared all / three assessments.","options":["He is the only one of the trainees","who have","cleared all","No error"],"answer":1,"explanation":"After 'the only one of …', the relative clause refers to 'the only one', which is singular: 'the only one of the trainees who has cleared'. Contrast 'one of the trainees who have cleared', where 'who' refers to the plural trainees.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-364","question":"Which sentence uses apostrophes correctly?","options":["The company's profit's rose, but its share price fell.","The companys' profits rose, but its share price fell.","The company's profits rose, but it's share price fell.","The company's profits rose, but its share price fell."],"answer":3,"explanation":"One company takes 's (company's). The possessive of 'it' is 'its' with no apostrophe; 'it's' means 'it is'. A plain plural like 'profits' takes no apostrophe, and 'companys'' is not a form of anything.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-365","question":"Fill in the blank.\nIt was not the price ___ the delivery time that made us switch suppliers.","options":["nor","and","but","or"],"answer":2,"explanation":"'Not X but Y' rejects X and puts Y in its place: the delivery time, not the price, was the reason. 'Nor' would need 'neither' and would deny both.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-366","question":"Fill in the blank.\nUnder no circumstances ___ share your password with anyone, including IT staff.","options":["you must","should you","you should","must"],"answer":1,"explanation":"A negative adverbial at the start of a sentence ('Under no circumstances', 'Never', 'At no time') triggers inversion: auxiliary before subject, 'should you share'. Normal word order is the trap.","difficulty":"hard","source":"Product company OA · CAT VARC"},
  {"id":"apt-verbal-placement-367","question":"Choose the word closest in meaning to the word in capitals as used in the sentence.\nThe CEO's resignation was the CULMINATION of months of pressure from investors.","options":["reversal","climax","beginning","cause"],"answer":1,"explanation":"A culmination is the highest point or final result reached after a build-up: here, the end point of months of pressure. 'Cause' reverses the relationship, and 'beginning' is the opposite.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-368","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nHer tone was so DIDACTIC that the audience felt they were being lectured.","options":["intended to instruct, in a preachy way","humorous","hesitant","confused"],"answer":0,"explanation":"Didactic means meant to teach, often with an annoying moralising air, which is why the audience felt lectured.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-369","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nThe witness was VOLUBLE about everything except the night of the crime.","options":["taciturn","truthful","nervous","forgetful"],"answer":0,"explanation":"Voluble means talking readily and at length; taciturn means saying little. The sentence's contrast ('everything except') hints at silence on one topic, but truthfulness and memory are different scales.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-370","question":"Choose the word that best fills the blank.\nThe new evidence ___ the defence's case: it showed that the accused had been in another city that night.","options":["undermined","bolstered","preceded","mirrored"],"answer":1,"explanation":"An alibi helps the defence, so the evidence strengthened (bolstered) its case. 'Undermined' reverses the effect; 'preceded' and 'mirrored' do not describe an effect on the case.","difficulty":"hard","source":"AMCAT · Infosys"},
  {"id":"apt-verbal-placement-371","question":"Choose the pair of words that best fills the blanks.\nWhat makes the essay ___ is not its argument, which is familiar, but its ___: every paragraph surprises.","options":["persuasive ... length","memorable ... thesis","memorable ... style","forgettable ... style"],"answer":2,"explanation":"'Not its argument … but its ___' needs something other than the argument, and 'every paragraph surprises' describes the writing itself: its style. That quality makes the essay memorable. 'Thesis' is just another word for the argument it rules out.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-372","question":"Read the argument and answer the question.\nA study found that hospital patients whose windows faced trees recovered faster than patients whose windows faced a brick wall. Some have concluded that hospitals should be redesigned around views of nature. But the patients with the tree view were also on a quieter ward, and quiet may itself speed recovery.\n\nWhat role does the final sentence play?","options":["It explains why brick walls slow recovery","It offers an alternative explanation for the study's finding","It questions whether the patients really recovered faster","It supports the proposal to redesign hospitals"],"answer":1,"explanation":"The last sentence accepts the finding but points to a confounding factor, quiet, that could explain it instead of the view. It weakens the redesign proposal, does not dispute the recovery data, and says nothing about brick walls themselves.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-373","question":"If the server goes down, an alert fires. If an alert fires, the on-call engineer is paged. Last night the on-call engineer was not paged.\nWhich of the following must be true?","options":["The server did not go down last night","The on-call engineer was asleep","The server went down but the alert failed","An alert fired last night"],"answer":0,"explanation":"Chain the conditions: server down → alert → page. No page means no alert, and no alert means the server did not go down (contrapositive twice). The third option contradicts the first rule, which says the alert always fires.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-374","question":"Statements: Some reports are confidential. All confidential documents are encrypted.\nConclusions: I. Some reports are encrypted. II. All encrypted documents are confidential.\nWhich conclusion(s) follow?","options":["Only I follows","Both I and II follow","Neither follows","Only II follows"],"answer":0,"explanation":"The confidential reports are encrypted, so some reports are encrypted (I). 'All confidential documents are encrypted' cannot be reversed: other documents may be encrypted too, so II does not follow.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-375","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nAfter a long call, the two departments are finally ON THE SAME PAGE about the budget.","options":["in competition","reading the same document","waiting for approval","in agreement"],"answer":3,"explanation":"To be on the same page is to share the same understanding or agree. The literal sense of reading the same page is the trap.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-376","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nWhen the launch failed, the project lead had to FACE THE MUSIC at the board meeting.","options":["celebrate a success","make a speech","accept criticism or punishment for what went wrong","ask for more funding"],"answer":2,"explanation":"To face the music is to confront the unpleasant consequences of one's actions, here explaining a failed launch to the board.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-377","question":"Choose the pair that has the same relationship as FLOOD : TRICKLE.","options":["ice : water","ocean : wave","storm : rain","gale : breeze"],"answer":3,"explanation":"A flood and a trickle are the same thing, flowing water, at extreme and slight intensity. A gale and a breeze are moving air at strong and gentle intensity. Storm : rain is whole and part, ocean : wave is source and feature, ice : water is two states.","difficulty":"very-hard","source":"AMCAT · CAT"},
  {"id":"apt-verbal-placement-378","question":"Choose the one word for: an intense fear of open or crowded public places.","options":["acrophobia","claustrophobia","agoraphobia","xenophobia"],"answer":2,"explanation":"Agoraphobia comes from agora, the Greek marketplace. Claustrophobia is fear of confined spaces, acrophobia fear of heights, and xenophobia dislike of foreigners.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-379","question":"In which sentence is 'eminent' or 'imminent' used correctly?","options":["The storm is eminent, so stay indoors.","She is an imminent authority on tax law.","With the deadline imminent, the team worked through the night.","An imminent scientist will give the keynote address."],"answer":2,"explanation":"Imminent means about to happen (a deadline, a storm); eminent means distinguished (a scientist, an authority). Only the first pairs the word with the right kind of noun.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-380","question":"Read the passage and answer the question.\n\nPassage: The report praises the new policy for 'streamlining' approvals. In practice, streamlining has meant that requests once checked by three people are now checked by one, who is given half the time.\n\nQuestion: The author's use of the word 'streamlining' is best described as:","options":["enthusiastic: it endorses the report's praise","ironic: it presents a cut in scrutiny as if it were an efficiency","confused: it uses the word in two unrelated senses","neutral: it simply repeats the report's term"],"answer":1,"explanation":"The author quotes the report's word and then shows what it means in practice, less checking in less time, so the term is turned against itself: irony. The tone is critical, not approving or neutral, and the word keeps one sense throughout.","difficulty":"very-hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-381","question":"Choose the sentence that best fills the blank.\n________. A city that bans cars from its centre may find that shops there lose passing trade at first, then gain as the streets fill with people on foot. Measuring the policy after one month and after one year can give opposite answers.","options":["People generally prefer walking to driving","Car bans always hurt local shops","Most cities are reluctant to ban cars from their centres","The effects of a policy can reverse over time"],"answer":3,"explanation":"The example shows an early loss turning into a later gain, and the last sentence draws the lesson about timing; the opening must state that idea. 'Always hurt' contradicts the example, and reluctance or preferences are not what it illustrates.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-382","question":"Choose the best replacement for the part in capitals. If no change is needed, choose \"No improvement\".\nThe meeting was postponed DUE TO THE FACT THAT the CEO was travelling.","options":["owing to the fact being that","No improvement","since the time that","because"],"answer":3,"explanation":"'Due to the fact that' is a wordy way of saying 'because'. 'Owing to the fact being that' is ungrammatical, and 'since the time that' refers to time, not cause.","difficulty":"moderate","source":"Wipro · AMCAT"},
  {"id":"apt-verbal-placement-383","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The surprise was that the pilots who had scored best in routine training were not the ones who coped best.\nQ: An airline once studied how its pilots handled rare, unexpected emergencies in the simulator.\nR: The best performers in a real crisis were often those with fewer hours of scripted drills, who had learned to diagnose problems from first principles.\nS: Drills, it seems, can teach pilots to recognise familiar failures while making them slower to notice unfamiliar ones.","options":["PQRS","QRPS","QPRS","QPSR"],"answer":2,"explanation":"Q sets up the study; P states the surprising result; R identifies who did cope best; S interprets the pattern. P cannot open because 'The surprise' needs the study; S needs both P and R to have something to explain.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-384","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Sorting these duplicates soon took more staff time than fixing the holes.\nQ: A city launched an app that let residents report potholes with a photo and a tap.\nR: Reports poured in, many of them about the same few holes on busy roads.\nS: Meanwhile, potholes on quiet streets, where few people drove, went unreported for months.\nT: Making a problem easy to report, the city learned, is not the same as finding out where the problems are.","options":["QRSPT","QRPST","QPRST","QRPTS"],"answer":1,"explanation":"Q launches the app; R describes the flood of repeated reports; P ('these duplicates') must follow R immediately; S ('Meanwhile') adds the opposite gap on quiet streets; T draws the lesson. In QRSPT, 'these duplicates' is separated from the reports it refers to.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-385","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Each was right about the part he could touch, and wrong about the whole.\nQ: In the old parable, several blind men examine an elephant to learn what it is.\nR: One feels the trunk and declares it a snake; another feels a leg and calls it a tree.\nS: Large organisations often understand themselves the same way.\nT: Sales sees the customer, engineering the product, finance the numbers, and each mistakes its own view for the company.\nU: That is why the most useful meetings are often those that force these partial views into the same room.","options":["QRPSTU","QRSPTU","QRPTSU","QPRSTU"],"answer":0,"explanation":"Q tells the parable; R gives the men's verdicts; P judges them ('Each was right … wrong about the whole'); S turns to organisations; T gives the parallel; U draws the practical lesson. P needs R's examples first; T needs S to announce the comparison.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-386","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Their solution was a simple checklist, read aloud before every take-off.\nQ: In 1935, a new bomber crashed on a demonstration flight because the pilots forgot to release a control lock.\nR: Investigators concluded that the plane was not too dangerous to fly, only too complicated for any pilot to remember every step.\nS: Checklists are now standard not only in aviation but also in operating theatres.","options":["QRSP","QRPS","RQPS","QPRS"],"answer":1,"explanation":"Q describes the crash; R gives the investigators' diagnosis; P ('Their solution') follows from that diagnosis; S extends the idea beyond aviation. P before R would offer a solution before the problem has been identified.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-387","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. As the climate warms, sea levels rise for two main reasons.\n2. Water expands as it warms, taking up more space.\n3. Melting land ice, from glaciers and ice sheets, adds new water to the oceans.\n4. Melting sea ice, by contrast, adds almost nothing, because floating ice already displaces its own weight of water.\n5. Many coastal cities were originally founded as trading ports.","options":["2","3","4","5"],"answer":3,"explanation":"Sentences 2 and 3 give the two reasons promised in 1, and 4 sharpens the second by contrast. Sentence 5 is about why coastal cities exist, not about why the sea rises.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-388","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Mobile banking spread fastest in countries where few people had bank accounts.\n2. Without branches nearby, customers had little to lose by switching to their phones.\n3. In countries with dense branch networks, customers kept their old habits for longer.\n4. Many banks now use chatbots to answer routine questions.\n5. Arriving late to an old technology, in other words, can make it easier to adopt a new one.","options":["4","5","2","3"],"answer":0,"explanation":"The paragraph argues that lacking the old system (branches) speeded adoption of the new one (mobile banking): 1 and 2 give the case, 3 the contrast, 5 the moral. Sentence 4 is about banking but not about that argument.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-389","question":"Choose the option that best completes the paragraph.\nRecommendation algorithms learn from what users click. Users, in turn, click on what the algorithm shows them. Over time, ________.","options":["clicks become a perfect measure of what users enjoy","the system can mistake its own influence for users' preferences and keep narrowing what it recommends","the algorithms become unable to show any content","users stop using such services altogether"],"answer":1,"explanation":"The two sentences describe a feedback loop: the algorithm shapes the clicks it then learns from. The natural consequence is self-reinforcement, mistaking its own influence for taste. The other options are either extreme or contradict the loop, which makes clicks a less reliable measure, not a perfect one.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-390","question":"Choose the sentence that best fills the blank.\nMany runners believe that stretching before a race prevents injury. ________. Several large trials have found that runners who stretched beforehand were injured about as often as those who did not.","options":["Injuries are more common in long races than in short ones","The evidence for this belief, however, is weak","Most runners stretch for less than five minutes","Stretching also improves flexibility over time"],"answer":1,"explanation":"The final sentence reports trials that contradict the belief, so the blank must signal that turn. Flexibility, stretching time and race length do not connect the belief to the contrary evidence.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-391","question":"Choose the option that best completes the paragraph.\nA translation app can turn a menu from Japanese into English in a second. What it cannot yet do is tell you that the dish it calls 'mountain potato' is slimy, prized for that very texture, and an acquired taste. ________","options":["Menus should always be printed in English.","The app should therefore be banned from restaurants.","Meaning, in other words, is more than the words.","Japanese food is difficult for foreigners to enjoy."],"answer":2,"explanation":"The example shows that a correct word-for-word translation can miss what a diner needs to know: the context and connotation behind the words. Banning apps, judging the cuisine or rewriting menus are all off the point.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-392","question":"Read the passage and choose the option that best summarises it.\n\nPassage: Ant colonies find the shortest route to food without any ant knowing the map. Each ant lays a scent trail; shorter routes are completed faster, so their trails are reinforced more often, and more ants follow them. The colony's intelligence lies not in any individual but in the simple rules they all share.","options":["Ants have an unusually good sense of direction","The shortest route is always the one most ants already use","Ant colonies are led by a few experienced scouts","Simple rules followed by individuals can produce intelligent behaviour in the group as a whole"],"answer":3,"explanation":"The passage explains how group-level problem solving arises from simple local rules and says so in its last sentence. It denies that any individual ant knows the way, which rules out the second and fourth options; the third reverses cause and effect.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-393","question":"Read the passage and choose the option that best summarises it.\n\nPassage: Many companies measure customer satisfaction with a single survey question. The score is easy to track, but it hides why customers are unhappy, and teams under pressure to raise it learn to send their surveys at moments when customers are likely to be pleased.","options":["Customer surveys should be abolished","A single satisfaction score is convenient but uninformative, and it can be gamed by the people judged on it","Most customers are pleased with the companies they deal with","Teams improve service quality fastest when judged on one number"],"answer":1,"explanation":"The passage gives one advantage (easy to track) and two problems (it hides causes; it can be gamed through timing). The first option keeps all three. Abolition and claims about customers' or teams' actual performance go beyond the text.","difficulty":"hard","source":"Infosys · Accenture"},
  {"id":"apt-verbal-placement-394","question":"Critical reasoning. Students who take lecture notes by hand remember more of the lecture than students who type their notes. Therefore, the university should ban laptops in lectures to improve learning.\nThe argument assumes which of the following?","options":["Handwriting is faster than typing","Lecturers prefer students who take notes by hand","Every student owns a laptop","If laptops are banned, students who would have typed will take notes by hand rather than take no notes at all"],"answer":3,"explanation":"The benefit depends on banned typists switching to handwriting. If many simply stop taking notes, the ban could reduce learning. Writing speed, laptop ownership and lecturers' preferences are not needed for the conclusion.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-395","question":"Critical reasoning. A bypass around a town opened in March. By December, traffic accidents on the town's main street had fallen by half, and the council credits the bypass.\nWhich of the following, if true, most weakens the council's claim?","options":["Accidents on the bypass itself were rare","The bypass cost more than its original budget","Most residents supported building the bypass","In March, the main street was also closed to lorries and its speed limit was cut to 20 km/h"],"answer":3,"explanation":"A lorry ban and a lower speed limit introduced at the same time are rival explanations for the fall, so the bypass may not deserve the credit. Cost, the bypass's own safety record and public support say nothing about why main-street accidents fell.","difficulty":"hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-396","question":"Critical reasoning. Researchers argue that a species of bird learned to open milk bottles by copying other birds rather than by each bird discovering the trick independently.\nWhich of the following, if true, most strengthens the researchers' argument?","options":["The habit spread outward from a few villages, appearing first in places closest to where it had already been seen","Milk bottles were delivered to doorsteps all over the country","Some birds of other species also opened bottles","The birds are known to be intelligent problem-solvers"],"answer":0,"explanation":"Spread in a wave from a few starting points is the signature of copying; independent discovery would pop up randomly wherever bottles were available. Intelligence, nationwide deliveries and other species fit independent discovery at least as well.","difficulty":"very-hard","source":"CAT"},
  {"id":"apt-verbal-placement-397","question":"Critical reasoning. After a company introduced unlimited paid leave, employee satisfaction rose, yet the average number of days off that employees took fell.\nWhich of the following, if true, best explains this?","options":["Many employees left the company that year","The company's busiest season fell in that year","The company also raised salaries that year","Without a fixed allowance, employees were unsure how much leave was acceptable and took less, while still valuing the flexibility"],"answer":3,"explanation":"Only the first option explains both halves: uncertainty about norms cuts leave taken, and the freedom itself lifts satisfaction. A pay rise explains satisfaction but not less leave; turnover and a busy season explain less leave but not higher satisfaction.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-398","question":"Critical reasoning. A study found that dog owners live longer, on average, than people without dogs. A pet company advertises that owning a dog extends your life.\nWhich would be most useful to know in evaluating the company's claim?","options":["How many dogs live in the country","Whether people who are already healthier are more likely to get a dog in the first place","How long dogs themselves typically live","Which dog breeds are most popular"],"answer":1,"explanation":"If healthy, active people are the ones who choose dogs, the longer lives could come from their health, not from the dogs. That possibility decides whether the claim holds. The number of dogs, popular breeds and dogs' own lifespans are irrelevant.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-399","question":"Every train that stops at Park Road also stops at Central. The 8:15 train does not stop at Central.\nWhich of the following must be true?","options":["The 8:15 train does not stop at Park Road","The 8:15 train is an express","The 8:15 train stops at Park Road","Every train that stops at Central also stops at Park Road"],"answer":0,"explanation":"If the 8:15 stopped at Park Road, it would have to stop at Central; it does not, so it cannot stop at Park Road (contrapositive). The third option reverses the rule, and nothing says why the 8:15 skips Central.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-400","question":"Critical reasoning. In a survey of visitors to our shopping website, 85% said they prefer online shopping to visiting stores. So most shoppers in the country prefer shopping online.\nWhat is the main flaw in this reasoning?","options":["The survey did not ask which products people buy","85% is too small a majority to be meaningful","People already visiting a shopping website are unlikely to represent all shoppers","The survey should have been conducted in stores"],"answer":2,"explanation":"The sample is self-selected from people who are, by definition, shopping online, so it is biased towards the conclusion. Product types are irrelevant, 85% is a large majority, and surveying only in stores would just bias it the other way.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-401","question":"Critical reasoning. A city made its buses free in order to reduce car traffic, but a year later car traffic had barely changed, even though bus ridership had risen sharply.\nWhich of the following, if true, best explains this?","options":["Some car owners also used the free buses at weekends","The city's population grew slightly during the year","Bus fares had been low even before the change","Most of the new bus riders were people who had previously walked or cycled"],"answer":3,"explanation":"If the extra riders came from walking and cycling, ridership could jump without taking cars off the road. Low previous fares would explain little change in ridership, which is not what happened; slight population growth and weekend use do not explain the pattern.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-402","question":"Read the passage and answer the question.\n\nPassage: For most of the twentieth century, economists assumed that a minimum wage high enough to matter must cost jobs: make labour dearer, and employers will buy less of it. A famous study of fast-food restaurants on either side of a state border challenged this. When one state raised its minimum wage and its neighbour did not, employment in the affected restaurants did not fall, and by some measures rose. Critics questioned the data; defenders replied that in towns with few employers, firms already pay workers less than they produce, leaving room for a higher wage. The debate has since shifted from whether a minimum wage costs jobs to how high it can go before it does.\n\nQuestion: The study's design depended on:","options":["surveying economists about their views on the minimum wage","following the same restaurants for most of the twentieth century","measuring how much workers produced in each restaurant","comparing similar restaurants that differed mainly in whether their state raised the wage"],"answer":3,"explanation":"Restaurants on either side of a border share local conditions, so the wage rise is the main difference: a natural comparison group. The study did not survey economists, the productivity point comes from its defenders, and the timescale is the old assumption's, not the study's.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-403","question":"Read the passage and answer the question.\n\nPassage: For most of the twentieth century, economists assumed that a minimum wage high enough to matter must cost jobs: make labour dearer, and employers will buy less of it. A famous study of fast-food restaurants on either side of a state border challenged this. When one state raised its minimum wage and its neighbour did not, employment in the affected restaurants did not fall, and by some measures rose. Critics questioned the data; defenders replied that in towns with few employers, firms already pay workers less than they produce, leaving room for a higher wage. The debate has since shifted from whether a minimum wage costs jobs to how high it can go before it does.\n\nQuestion: The final sentence suggests that the debate now:","options":["has proved the border study wrong","has been abandoned by economists","accepts that some minimum-wage increases need not cost jobs, while recognising that there is a limit","holds that minimum wages always increase employment"],"answer":2,"explanation":"Asking 'how high it can go before it does' concedes that moderate rises may not cost jobs and assumes that very high ones would. The sentence neither refutes the study nor claims wages always raise employment, and a shifted debate is not an abandoned one.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-404","question":"Read the passage and answer the question.\n\nPassage: The Library of Alexandria is often imagined as destroyed in a single catastrophic fire. The surviving sources tell a slower story. Funding was cut under later rulers, scholars were expelled during a political purge, and the collection was damaged in several separate conflicts over centuries. By the time of the last reported destruction, there may have been little left to burn. The dramatic ending is memorable; the gradual one is more instructive, because neglect is harder to notice than flames.\n\nQuestion: According to the passage, the library's decline involved:","options":["cuts in funding, the expulsion of scholars and repeated damage over a long period","the theft of its books by rival libraries","a single fire that destroyed the whole collection","a gradual loss of interest among readers"],"answer":0,"explanation":"The passage lists exactly these three causes, spread over centuries. The single fire is the popular image it corrects; theft and readers' interest are never mentioned.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-405","question":"Read the passage and answer the question.\n\nPassage: The Library of Alexandria is often imagined as destroyed in a single catastrophic fire. The surviving sources tell a slower story. Funding was cut under later rulers, scholars were expelled during a political purge, and the collection was damaged in several separate conflicts over centuries. By the time of the last reported destruction, there may have been little left to burn. The dramatic ending is memorable; the gradual one is more instructive, because neglect is harder to notice than flames.\n\nQuestion: The author finds the gradual account 'more instructive' because it:","options":["proves that the library was never burned at all","makes a better story than the single fire","is supported by more surviving sources than any other account","shows how an institution can be lost through neglect that is hard to notice while it happens"],"answer":3,"explanation":"The reason is given directly: 'neglect is harder to notice than flames', so the slow story teaches a lesson the dramatic one hides. The author does not deny a final destruction, does not count sources, and concedes that the fire is the more memorable story.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-406","question":"Read the passage and answer the question.\n\nPassage: Most people think of a fever as something an illness does to them. Biologists increasingly see it as something the body does to the illness. Many bacteria and viruses reproduce best at normal body temperature, and a rise of a degree or two slows them while speeding up parts of the immune response. Animals that cannot raise their internal temperature, such as lizards, seek out warm spots when infected, and lizards prevented from doing so are more likely to die.\n\nQuestion: The example of the lizards is used to:","options":["support the view that raising body temperature helps fight infection","show that lizards are especially prone to infection","argue that fevers are dangerous for cold-blooded animals","explain why lizards cannot produce their own heat"],"answer":0,"explanation":"Infected lizards seek heat, and those blocked from it die more often: evidence that warmth itself helps against infection, which backs the biologists' view. The example is not about how prone lizards are to infection, why they cannot make heat, or any danger of fever.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-407","question":"Read the passage and answer the question.\n\nPassage: Most people think of a fever as something an illness does to them. Biologists increasingly see it as something the body does to the illness. Many bacteria and viruses reproduce best at normal body temperature, and a rise of a degree or two slows them while speeding up parts of the immune response. Animals that cannot raise their internal temperature, such as lizards, seek out warm spots when infected, and lizards prevented from doing so are more likely to die.\n\nQuestion: Which of the following can be inferred from the passage?","options":["Routinely suppressing a moderate fever may, in some cases, slow recovery","Lizards cannot be infected by viruses","Fevers are always harmless and should never be treated","Most viruses reproduce faster at higher temperatures"],"answer":0,"explanation":"If a modest rise in temperature slows pathogens and helps immunity, removing it could sometimes work against the body; the cautious 'may, in some cases' matches the evidence. 'Always harmless' overreaches, lizards are said to be infected, and the passage says pathogens prefer normal temperature.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-408","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe quality of the products / sold at these outlets / are / not satisfactory.","options":["sold at these outlets","No error","The quality of the products","are"],"answer":3,"explanation":"The subject is 'the quality', which is singular; 'of the products sold at these outlets' only describes it. The verb must be 'is'. Agreeing with the nearest noun ('outlets') is the trap.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-409","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHardly anybody / turned up for the meeting, / did they?","options":["Hardly anybody","did they?","No error","turned up for the meeting,"],"answer":2,"explanation":"'Hardly' makes the statement negative, so the tag is positive ('did they?'), and indefinite pronouns like 'anybody' take 'they' in tags. The tempting correction, 'didn't they?', treats the sentence as positive.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-410","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHe has been working / in this company / since five years / and plans to stay.","options":["No error","in this company","since five years","He has been working"],"answer":2,"explanation":"'Since' marks a starting point (since 2020); a length of time takes 'for': 'for five years'.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-411","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nOne should respect / his elders / and take care of / them in old age.","options":["No error","and take care of","his elders","One should respect"],"answer":2,"explanation":"In formal usage, a sentence that begins with the impersonal 'one' keeps it: 'One should respect one's elders'. Switching to 'his' is the error placement tests look for.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-412","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nI prefer tea / than coffee / in the mornings / before work.","options":["I prefer tea","than coffee","in the mornings","No error"],"answer":1,"explanation":"'Prefer' takes 'to' when comparing two nouns: 'I prefer tea to coffee'. 'Than' belongs with 'rather' ('I would rather have tea than coffee').","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-413","question":"Which version of the sentence about the hiring freeze is grammatically correct?","options":["Neither the hiring freeze nor the budget cuts were announced in advance.","Neither the hiring freeze or the budget cuts were announced in advance.","Neither the hiring freeze nor the budget cuts was announced in advance.","Neither was the hiring freeze nor the budget cuts announced in advance."],"answer":0,"explanation":"With 'neither … nor', the verb agrees with the nearer subject, here the plural 'budget cuts', so 'were'. 'Neither' pairs with 'nor', not 'or'; the last option inverts the clause and also uses the wrong number.","difficulty":"very-hard","source":"Capgemini · CAT VARC"},
  {"id":"apt-verbal-placement-414","question":"Which version of the sentence about the cyclist avoids a dangling modifier?","options":["The cyclist's injury was not serious, wearing a helmet.","Serious injury, wearing a helmet, was avoided by the cyclist.","Wearing a helmet, the cyclist escaped serious injury.","Wearing a helmet, serious injury was avoided by the cyclist."],"answer":2,"explanation":"An opening participle phrase must attach to the subject that follows it. Only the first makes 'the cyclist' the one wearing the helmet; the others make 'serious injury' or 'the injury' wear it, or leave the phrase dangling at the end.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-415","question":"Fill in the blank.\nThe new rules apply to all staff, ___ seniority.","options":["regardless of","irrespective to","regarding","despite of"],"answer":0,"explanation":"'Regardless of' (or 'irrespective of') means without being affected by. 'Irrespective to' has the wrong preposition, 'regarding' means 'about', and 'despite of' is never correct.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-416","question":"Fill in the blank.\nShe talks about the company as though she ___ the CEO herself.","options":["has been","were","will be","is"],"answer":1,"explanation":"'As though' introducing something contrary to fact takes the past subjunctive: 'as though she were the CEO'. 'Is' would state that she actually is the CEO.","difficulty":"hard","source":"CAT VARC · Capgemini"},
  {"id":"apt-verbal-placement-417","question":"Fill in the blank.\nWe had better ___ before the storm gets worse.","options":["leaving","left","leave","to leave"],"answer":2,"explanation":"'Had better' is followed by the bare infinitive, with no 'to': 'we had better leave'. The past form 'had' here refers to the present or near future, not the past.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-418","question":"Fill in the blank.\nIt is the CFO, not the analysts, who ___ responsible for the forecast.","options":["are","is","have been","were"],"answer":1,"explanation":"In a cleft sentence ('It is X who …'), the verb in the who-clause agrees with X, here 'the CFO'. The parenthetical 'not the analysts' does not change the subject, which is the trap behind 'are'.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-419","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe staff complained that the bonus cuts were ARBITRARY.","options":["generous","carefully calculated","based on whim rather than reason","temporary"],"answer":2,"explanation":"An arbitrary decision is made without a consistent reason or rule, which is what staff would complain about. 'Carefully calculated' is its opposite.","difficulty":"moderate","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-420","question":"Choose the word closest in meaning to the word in capitals as used in the sentence.\nThe diplomat's remarks were deliberately OPAQUE, so that both sides could claim victory.","options":["brief","unclear","offensive","transparent"],"answer":1,"explanation":"Opaque language is hard to see through, i.e. unclear; deliberate vagueness lets both sides read their own meaning into it. 'Transparent' is the opposite.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-421","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nThe new CEO's style was AUTOCRATIC: she made every decision herself.","options":["consultative","automatic","aristocratic","energetic"],"answer":0,"explanation":"An autocratic leader decides alone; the opposite is a consultative one who seeks others' views. 'Aristocratic' and 'automatic' only look similar.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-422","question":"Choose the word that best fills the blank.\nThe author's prose is so ___ that a single sentence can run for half a page, doubling back on itself through clause after clause.","options":["labyrinthine","pithy","terse","lucid"],"answer":0,"explanation":"Long, winding sentences that double back on themselves are labyrinthine (maze-like). Terse and pithy mean brief, and lucid means clear, all the opposite of the description.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-423","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nThe new CEO decided to TAKE THE BULL BY THE HORNS and address the losses at the first board meeting.","options":["act carelessly","blame someone else","avoid an unpleasant topic","confront a difficulty directly and boldly"],"answer":3,"explanation":"To take the bull by the horns is to tackle a difficult problem head-on, as the CEO does by raising the losses immediately.","difficulty":"moderate","source":"TCS NQT · AMCAT"},
  {"id":"apt-verbal-placement-424","question":"Choose the pair that has the same relationship as THERMOMETER : TEMPERATURE.","options":["telescope : planets","seismograph : earth tremors","stethoscope : doctor","compass : map"],"answer":1,"explanation":"A thermometer is an instrument that measures temperature; a seismograph measures earth tremors. A telescope magnifies planets rather than measuring a quantity, a stethoscope is used by a doctor, and a compass is used with a map.","difficulty":"very-hard","source":"AMCAT · CAT"},
  {"id":"apt-verbal-placement-425","question":"Statements: All pens are tools. Some tools are expensive.\nConclusions: I. Some pens are expensive. II. Some expensive things are tools.\nWhich conclusion(s) follow?","options":["Both I and II follow","Only I follows","Only II follows","Neither follows"],"answer":2,"explanation":"'Some tools are expensive' converts directly to 'some expensive things are tools' (II). The expensive tools may all be tools other than pens, so I does not follow.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-426","question":"If Anil attends the meeting, Bina will not. Exactly one of Bina and Chetan attends. Chetan did not attend.\nWhich of the following must be true?","options":["Anil attended","Neither Anil nor Bina attended","Bina did not attend","Anil did not attend"],"answer":3,"explanation":"Chetan's absence means Bina attended (exactly one of them did). If Anil had attended, Bina would not have, so Anil did not attend. The other options contradict one of these two steps.","difficulty":"very-hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-427","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: For the first few years, the gains were dramatic.\nQ: When a factory first brought robots onto its assembly line, managers expected output per worker to keep rising for as long as they kept buying machines.\nR: After that, each new robot added less, because the tasks still left were the ones machines handled worst.\nS: Productivity, it turned out, depended less on how many robots the factory owned than on which tasks were left for them.","options":["PQRS","QPSR","QRPS","QPRS"],"answer":3,"explanation":"Q states the expectation; P reports the early gains; R ('After that') needs P's 'first few years' to refer back to; S draws the conclusion. In QRPS, 'After that' has nothing to follow; S cannot come before R, whose diminishing returns it explains.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-428","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nQ: The claim that people in the Middle Ages believed the earth was flat is itself a myth.\nR: In fact, educated medieval writers routinely described the earth as a sphere, following the ancient Greeks.\nS: The flat-earth story was popularised in the nineteenth century by writers eager to portray earlier ages as backward.\nT: It survives today because it flatters the present at the expense of the past.","options":["QRST","RQST","QRTS","QSRT"],"answer":0,"explanation":"Q calls the claim a myth; R ('In fact') gives the evidence against it; S explains where the myth came from; T ('It survives today') explains why it persists, which only makes sense after its origin is given. R cannot open because 'In fact' needs a claim to correct.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-429","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nQ: Shakespeare is credited with introducing hundreds of words into English.\nT: 'Credited' may be the important word.\nR: Recent searches of digitised texts have found many of those words in print years before he used them.\nS: He may simply have been the first writer whose use of them was remembered.\nU: The lesson goes beyond Shakespeare: we tend to give credit for an idea to the most famous person who used it.","options":["TQRSU","QTRSU","QTRUS","QRTSU"],"answer":1,"explanation":"Q makes the claim; T flags the word 'credited' as doubtful; R gives the evidence; S interprets it; U generalises. QRTSU puts the evidence before the doubt it supports; U cannot precede S, whose explanation it generalises.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-430","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Noise-cancelling headphones work by producing sound, not by blocking it.\n2. A microphone samples the incoming noise many times a second.\n3. The headphones then play a wave that is the mirror image of that noise.\n4. Where the two waves meet, they largely cancel, leaving near silence.\n5. Many travellers wear headphones on long flights to help them sleep.","options":["5","3","2","4"],"answer":0,"explanation":"Sentences 1 to 4 explain the mechanism step by step: the claim, the sampling, the mirror-image wave, the cancellation. Sentence 5 is about why people use headphones, not how the cancelling works.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-431","question":"Choose the option that best completes the sentence.\nA company that rewards its sales staff only for signing new contracts should not be surprised when ________.","options":["its staff become experts in keeping existing customers","existing customers are neglected once their contracts are signed","its sales fall to zero","new contracts stop being signed"],"answer":1,"explanation":"Incentives shape effort: if only new contracts are rewarded, staff time flows away from serving existing customers. The second option is the opposite effect; the third and fourth contradict an incentive that rewards new sales.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-432","question":"Choose the sentence that best fills the blank.\nMuch of a forest fire's damage is done not by the flames but by what they leave behind. ________. Heavy rain on such slopes can then strip away the soil in a single storm.","options":["Firefighters often use aircraft to drop water on the flames","Forest fires are more common in dry summers","With the plants that held the soil burned away, hillsides are left bare and loose","Some trees have thick bark that protects them from fire"],"answer":2,"explanation":"The last sentence refers to 'such slopes', so the blank must describe slopes and link the fire to the later erosion. Only the first option does both; aircraft, bark and fire seasons break the chain.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-433","question":"Read the passage and choose the option that best summarises it.\n\nPassage: Placebo pills work better when they are larger, more expensive or brightly coloured, and injections of salt water work better than placebo pills. None of these features changes the chemistry of an inert treatment; all of them change what the patient expects.","options":["The effect of an inert treatment depends on the expectations its presentation creates","Injections are always more effective than pills","Expensive medicines are better than cheap ones","Brightly coloured pills contain more active ingredients"],"answer":0,"explanation":"The passage lists presentation features that alter results without altering chemistry and attributes the difference to expectation. The other options misread inert treatments as containing active ingredients or generalise to all medicines.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-434","question":"Critical reasoning. To reduce obesity, a city plans to require restaurants to print calorie counts on their menus.\nThe plan depends on which assumption?","options":["Diners already know roughly how many calories each dish contains","Restaurants will not raise their prices","At least some diners will choose lower-calorie dishes when they see the numbers","Most restaurant meals contain more calories than home-cooked ones"],"answer":2,"explanation":"Printing numbers can reduce obesity only if the information changes some choices. If diners already knew the counts, the plan would add nothing, so the last option undermines it. Restaurant versus home cooking and prices are not required.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-435","question":"Critical reasoning. Students who use the university's tutoring centre get higher grades than students who do not. So the tutoring centre improves grades.\nWhich of the following, if true, most weakens the conclusion?","options":["Some tutors at the centre are graduate students","The centre is open only on weekdays","Most students who use the centre were already earning high grades and wanted to aim higher","The centre recently moved to a larger building"],"answer":2,"explanation":"If the centre's users were strong students to begin with, the grade gap reflects who chooses to go, not what the centre does. Opening hours, who the tutors are and the building say nothing about cause and effect.","difficulty":"hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-436","question":"Critical reasoning. A historian argues that an undated letter was written in the 1820s, because it mentions a canal that opened in 1825.\nWhich of the following, if true, most strengthens the historian's argument?","options":["The letter is written in ink of a kind common in the nineteenth century","The writer of the letter lived near the canal","The canal remained in use for over a century","The letter calls the canal 'newly opened' and mentions a bridge that was demolished in 1829"],"answer":3,"explanation":"Mentioning the canal shows only that the letter is no earlier than 1825; it could be decades later. 'Newly opened' and a bridge that stood only until 1829 set an upper limit too. The canal's long life weakens the dating; ink and the writer's address are too vague to help.","difficulty":"very-hard","source":"CAT"},
  {"id":"apt-verbal-placement-437","question":"Critical reasoning. Over ten years, the share of a city's residents who cycle to work doubled, yet the number of cycling accidents in the city fell.\nWhich of the following, if true, best explains this?","options":["Most of the new cyclists were young adults","The city's population grew over the decade","Bicycles became cheaper during the decade","Over the decade, the city built a network of cycle lanes physically separated from car traffic"],"answer":3,"explanation":"More cycling would normally mean more accidents; protected lanes make each trip much safer, which can outweigh the extra trips. Cheaper bikes and new cyclists explain the growth in cycling, not the fall in accidents; population growth would push accidents up.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-verbal-placement-438","question":"Critical reasoning. All of the country's best universities have large endowments. So if every university were given a large endowment, all of them would become excellent.\nWhich is the main flaw in this reasoning?","options":["It assumes the endowments caused the universities' excellence, when excellence may instead have attracted the endowments","It does not say how large an endowment must be","It ignores the cost of running a university","It assumes that every university wants to become excellent"],"answer":0,"explanation":"A shared feature of top universities may be a result of their success (donors give to famous institutions) rather than its cause, so handing it out need not reproduce the success. The size of endowments, costs and motivation are side issues.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-439","question":"Choose the option that most logically completes the argument.\nShared electric scooters were introduced in a city to cut down on short car trips. Surveys now show that most scooter trips replaced walking, not driving. So the scheme ________.","options":["should be expanded to more cities","has eliminated short car trips in the city","has probably done little to reduce car use","has made walking more popular"],"answer":2,"explanation":"If scooters mostly replaced walking, few car trips were displaced, so the scheme's stated goal is barely being met. The second option contradicts the survey, the third reverses it, and the fourth ignores the scheme's failure.","difficulty":"hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-440","question":"Read the passage and answer the question.\n\nPassage: In the early days of aviation, many inventors copied birds, building machines with flapping wings. None of them flew. Progress came only when engineers separated the problems a bird solves all at once: a fixed wing for lift, a propeller for thrust and movable surfaces for control. The aeroplane that finally flew looked nothing like a bird, yet it obeyed the same laws of air that birds do.\n\nQuestion: Which of the following best states the main point of the passage?","options":["Birds are poor models for any kind of engineering","Flapping wings are more efficient than fixed wings","Early inventors failed because they lacked powerful engines","Success came from understanding the principles birds use rather than copying their form"],"answer":3,"explanation":"The passage contrasts copying the bird's form (failure) with separating the problems it solves (success), while stressing that the same laws apply to both. It does not dismiss birds as models, rank flapping wings, or mention engine power.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-441","question":"Read the passage and answer the question.\n\nPassage: In the early days of aviation, many inventors copied birds, building machines with flapping wings. None of them flew. Progress came only when engineers separated the problems a bird solves all at once: a fixed wing for lift, a propeller for thrust and movable surfaces for control. The aeroplane that finally flew looked nothing like a bird, yet it obeyed the same laws of air that birds do.\n\nQuestion: The final clause, 'yet it obeyed the same laws of air that birds do', serves to:","options":["argue that birds and aeroplanes fly in exactly the same way","criticise the early inventors for studying birds at all","explain why flapping wings are needed for control","show that abandoning the bird's form did not mean abandoning what birds had to teach"],"answer":3,"explanation":"'Yet' qualifies 'looked nothing like a bird': the shape differs, but the underlying physics is shared, so birds still had lessons to offer. It does not say they fly identically, does not blame the inventors for studying birds, and the passage gives control to movable surfaces, not flapping.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-442","question":"Read the passage and answer the question.\n\nPassage: When a company reports record profits in the same year it lays off staff, critics call it greed. The company's defenders reply that the layoffs are why profits are high, and that a firm which waited for losses before cutting costs would have to cut far more jobs later. Both sides assume the profits were earned by the cuts; neither asks whether, as often happens in a boom, the profits would have been high anyway.\n\nQuestion: The author's main point is that:","options":["the critics are right to call the layoffs greedy","companies should never lay off staff in a profitable year","the layoffs were justified by the record profits","critics and defenders share an unexamined assumption about what caused the profits"],"answer":3,"explanation":"The last sentence is the author's contribution: both sides take for granted that the cuts produced the profits, without checking whether a boom would have produced them anyway. The author takes neither side in the greed debate.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-443","question":"Read the passage and answer the question.\n\nPassage: When a company reports record profits in the same year it lays off staff, critics call it greed. The company's defenders reply that the layoffs are why profits are high, and that a firm which waited for losses before cutting costs would have to cut far more jobs later. Both sides assume the profits were earned by the cuts; neither asks whether, as often happens in a boom, the profits would have been high anyway.\n\nQuestion: The author would most likely agree that:","options":["layoffs during an economic boom are always unjustified","record profits in a year of layoffs do not by themselves show that the layoffs produced the profits","companies should not be allowed to report record profits","the defenders' argument has been proved correct"],"answer":1,"explanation":"The author questions the causal link that both sides assume; the first option states that doubt. The author makes no judgement that layoffs are unjustified, proposes no rule about reporting, and does not endorse the defenders.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-444","question":"Read the passage and answer the question.\n\nPassage: Archaeologists once dated the arrival of farming in a region by the earliest grains of domesticated wheat found there. Newer methods that detect wheat proteins in the residue on pottery have pushed some of those dates back by centuries. The grains had not lied; they had simply survived only where conditions were unusually dry, while the pots preserved a record of meals eaten everywhere.\n\nQuestion: According to the passage, the newer method changed the dates because:","options":["residue on pottery preserved evidence from places and periods where grains had not survived","pottery is easier to date than grain","farmers began making pots before they grew wheat","the old grains had been wrongly identified as wheat"],"answer":0,"explanation":"Grains survived only in dry conditions, so the earliest surviving grain could postdate the first farming; pots kept traces of meals 'eaten everywhere'. The passage says the grains 'had not lied', ruling out misidentification, and makes no claim about ease of dating or the order of pots and wheat.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-445","question":"Read the passage and answer the question.\n\nPassage: Archaeologists once dated the arrival of farming in a region by the earliest grains of domesticated wheat found there. Newer methods that detect wheat proteins in the residue on pottery have pushed some of those dates back by centuries. The grains had not lied; they had simply survived only where conditions were unusually dry, while the pots preserved a record of meals eaten everywhere.\n\nQuestion: The phrase 'The grains had not lied' suggests that the earlier evidence was:","options":["more reliable than the pottery evidence","deliberately falsified by earlier archaeologists","accurate as far as it went, but incomplete","wrongly identified as domesticated wheat"],"answer":2,"explanation":"The grains were genuine evidence of farming where they survived; the problem was that they survived in too few places, so they gave a late date. That is incomplete, not false or misidentified, and the passage treats the pottery as the fuller record.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-446","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nEvery one of the managers / have agreed / to the new / reporting format.","options":["to the new","Every one of the managers","have agreed","No error"],"answer":2,"explanation":"The subject is 'every one', which is singular; 'of the managers' only says which group. The verb must be 'has agreed'.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-447","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHe did not know / whom to trust / and who to / ignore.","options":["He did not know","and who to","whom to trust","No error"],"answer":1,"explanation":"Both pronouns are objects of the infinitives (trust someone, ignore someone), so both should be 'whom'. Using 'whom' in the first half and 'who' in the second is inconsistent in formal English.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-448","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nLet he who / has finished the test / leave the hall / quietly.","options":["No error","Let he who","has finished the test","leave the hall"],"answer":1,"explanation":"'Let' takes an object: 'Let him who has finished leave'. 'Who' is correct because it is the subject of 'has finished'; the error is 'he', which should be the object form.","difficulty":"very-hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-449","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nIf I was you, / I would accept / the offer / immediately.","options":["If I was you,","the offer","No error","I would accept"],"answer":0,"explanation":"An imaginary condition takes the subjunctive 'were' for every person: 'If I were you'. 'Was' is common in speech but is marked wrong in formal tests.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-450","question":"In which sentence is 'whose' or 'who's' used correctly?","options":["The manager whose leaving next month is training her successor.","The firm, whose merger was approved last week, has announced new targets.","The firm, who's merger was approved last week, has announced new targets.","Who's report is this on my desk?"],"answer":1,"explanation":"'Whose' is possessive (the firm's merger); 'who's' means 'who is' or 'who has'. The third needs 'who's leaving' (who is leaving) and the fourth needs 'Whose report'.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-451","question":"Fill in the blank.\nThe proposal was rejected, ___ the committee had praised it only a week earlier.","options":["unless","so that","although","because"],"answer":2,"explanation":"Rejecting a proposal that had just been praised is a contrast, which 'although' expresses. 'Because' would make the praise the reason for rejection; 'unless' and 'so that' express condition and purpose.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-452","question":"Fill in the blank.\nHad the auditors ___ the error earlier, the report would have been withdrawn before publication.","options":["been spotted","spotting","spot","spotted"],"answer":3,"explanation":"'Had the auditors …' is an inverted past conditional (If the auditors had …), which needs the past participle: 'had spotted'. 'Been spotted' would make the auditors the ones spotted.","difficulty":"hard","source":"Product company OA · CAT VARC"},
  {"id":"apt-verbal-placement-453","question":"Fill in the blank.\nThe CEO, ___ we had never met before, greeted each of us by name.","options":["whose","which","who","whom"],"answer":3,"explanation":"Inside the clause the pronoun is the object of 'met' (we had never met him or her), so the object form 'whom' is correct. 'Which' is for things, and 'whose' needs a noun after it.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-454","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nHis apology seemed CONTRITE enough to satisfy even his harshest critics.","options":["sincerely remorseful","carefully worded","brief","defiant"],"answer":0,"explanation":"Contrite means feeling or showing genuine regret for a wrong. 'Carefully worded' describes how an apology is phrased, not the remorse behind it; 'defiant' is the opposite.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-455","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nThe new manager is known for her ALACRITY in answering client requests.","options":["alertness","reluctance","accuracy","politeness"],"answer":1,"explanation":"Alacrity is brisk and cheerful readiness, so its opposite is reluctance (slow unwillingness). 'Alertness' is close in meaning, and accuracy and politeness measure different things.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-456","question":"Choose the word that completes the analogy.\nMISER : GENEROSITY :: COWARD : ?","options":["courage","weakness","fear","army"],"answer":0,"explanation":"A miser is defined by a lack of generosity; a coward is defined by a lack of courage. Fear is what a coward has, not what he lacks.","difficulty":"hard","source":"AMCAT · CoCubes"},
  {"id":"apt-verbal-placement-457","question":"All the reports that Priya reviewed were approved. Some approved reports contained errors.\nWhich of the following must be true?","options":["Every approved report was reviewed by Priya","If a report was not approved, Priya did not review it","Every report that contained errors was approved","Some of the reports Priya reviewed contained errors"],"answer":1,"explanation":"'Reviewed by Priya → approved' has the contrapositive 'not approved → not reviewed by Priya', which must hold. The approved reports with errors may all be ones she did not review, and neither statement says all erroneous or all approved reports fall in the other group.","difficulty":"very-hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-458","question":"Which version of the sentence about the customs delay is grammatically correct?","options":["The shipment, together with its invoices, was held at customs for a week.","Together with its invoices, the shipment have been held at customs for a week.","The shipment and its invoices was held at customs for a week.","The shipment, together with its invoices, were held at customs for a week."],"answer":0,"explanation":"'Together with', like 'as well as', adds information without making the subject plural, so 'the shipment' takes the singular 'was'. With 'and' the subject becomes plural and would need 'were'; the last option pairs the singular subject with 'have'.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-459","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nEach of the candidates who / have cleared the written test / will be called / for an interview.","options":["No error","have cleared the written test","will be called","Each of the candidates who"],"answer":0,"explanation":"'Who' refers to 'candidates' (plural), so 'who have cleared' is right, while the main verb 'will be called' goes with 'Each'. Changing 'have' to 'has' is the trap: it makes the relative clause agree with 'Each' instead of its real antecedent.","difficulty":"very-hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-460","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe committee comprises of / five senior partners / and two external / advisers.","options":["five senior partners","The committee comprises of","and two external","No error"],"answer":1,"explanation":"'Comprise' takes a direct object: the committee comprises five partners, or consists of / is composed of them. 'Comprises of' mixes the two patterns.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-461","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nNot only he apologised / for the delay, / but he also offered / a full refund.","options":["for the delay,","but he also offered","Not only he apologised","No error"],"answer":2,"explanation":"When 'Not only' opens a sentence, the clause after it is inverted with an auxiliary: 'Not only did he apologise for the delay, but he also offered …'. The second half is already correct.","difficulty":"hard","source":"TCS NQT · Accenture"},
  {"id":"apt-verbal-placement-462","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe manager, whom / everyone assumed / was about to retire, / announced a new project.","options":["everyone assumed","was about to retire,","announced a new project.","The manager, whom"],"answer":3,"explanation":"Remove the inserted 'everyone assumed' and the clause reads '… who was about to retire': the pronoun is the subject of 'was', so it must be 'who'. 'Whom' looks right only because it sits next to the verb 'assumed'.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-463","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe furniture in both / conference rooms have / been replaced with / ergonomic chairs.","options":["conference rooms have","The furniture in both","been replaced with","No error"],"answer":0,"explanation":"The subject is 'furniture', an uncountable noun, so the verb must be singular: 'has been replaced'. The plural 'rooms' just before the verb is the distraction.","difficulty":"moderate","source":"Wipro · AMCAT"},
  {"id":"apt-verbal-placement-464","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nDespite working late / every night this week, / the report is still / not ready.","options":["Despite working late","No error","the report is still","every night this week,"],"answer":2,"explanation":"The opening phrase needs a subject that did the working, but the main clause makes 'the report' that subject. The fix is in the main clause: '… we still have not finished the report'.","difficulty":"very-hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-465","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nFive kilometres / are not a long distance / for a runner / of her experience.","options":["Five kilometres","for a runner","of her experience.","are not a long distance"],"answer":3,"explanation":"A plural amount of distance, money or time treated as a single quantity takes a singular verb: 'Five kilometres is not a long distance'. The plural form of 'kilometres' is the trap.","difficulty":"hard","source":"Capgemini · Infosys"},
  {"id":"apt-verbal-placement-466","question":"Fill in the blank.\nThe board was ___ to approve the merger until it had seen the audited accounts.","options":["reluctant","reticent","adverse","averse"],"answer":0,"explanation":"'Reluctant to approve' means unwilling to approve. 'Reticent' means unwilling to speak; 'adverse' means harmful; 'averse' needs 'to approving' (a noun or gerund after 'to').","difficulty":"hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-verbal-placement-467","question":"Fill in the blank.\nIf she had accepted the Bengaluru offer last year, she ___ a much bigger team now.","options":["would have led","would be leading","will be leading","had been leading"],"answer":1,"explanation":"This is a mixed conditional: a past condition ('had accepted last year') with a present result ('now'), so the result clause takes 'would be leading'. 'Would have led' clashes with 'now'.","difficulty":"very-hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-468","question":"Fill in the blank.\nThe analyst's warning proved ___: within six months sales had fallen almost exactly as she had predicted.","options":["precocious","presumptuous","prescient","pernicious"],"answer":2,"explanation":"'Prescient' means having foreknowledge, which is what an accurate prediction shows. 'Precocious' is developed early, 'presumptuous' overstepping, 'pernicious' harmful: all look alike but miss the meaning.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-469","question":"Fill in the blank.\nThe vendor's reply was so ___ — two lines, no apology and no answer to any of our questions — that we wondered whether it wanted the contract at all.","options":["effusive","meticulous","conciliatory","curt"],"answer":3,"explanation":"A two-line reply that skips the apology and the questions is curt: rudely brief. 'Effusive' and 'conciliatory' are the opposite in warmth; 'meticulous' contradicts 'no answer to any of our questions'.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-470","question":"Choose the pair of words that best fills the blanks.\nAlthough the minister's speech was ___ in delivery, its content was ___: almost every promise in it had been made, and broken, before.","options":["polished ... stale","halting ... novel","hesitant ... fresh","ornate ... original"],"answer":0,"explanation":"The colon explains the second blank: promises made before are stale. 'Although' then needs a positive word for the delivery: polished. 'Halting … novel' is also a contrast, but 'novel' contradicts the explanation after the colon.","difficulty":"hard","source":"CAT VARC · TCS NQT"},
  {"id":"apt-verbal-placement-471","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe CFO was clearly NONPLUSSED by the auditor's question; she paused, looked down at her notes and asked for it to be repeated.","options":["unbothered","perplexed","delighted","offended"],"answer":1,"explanation":"'Nonplussed' traditionally means so confused that one does not know how to react, which the pause and the request to repeat confirm. Reading it as 'unbothered' is a common modern error that the context rules out.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-472","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThree weeks of all-night negotiations had ENERVATED the team, and nobody had the energy to celebrate the deal.","options":["energised","enraged","drained","united"],"answer":2,"explanation":"To enervate is to drain of energy, which matches 'nobody had the energy to celebrate'. The sound of the word misleads many into 'energised', its opposite.","difficulty":"hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-473","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe chairman's FULSOME tribute to the departing CEO, who was widely known to have been forced out, struck many in the room as hollow.","options":["complete and generous","brief and grudging","sincere and moving","excessively flattering"],"answer":3,"explanation":"'Fulsome' praise is overdone to the point of insincerity, which fits a tribute that struck listeners as hollow. 'Complete and generous' takes 'full' at face value; the context of a forced exit points to flattery.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-474","question":"Choose the meaning of the word in capitals as used in the sentence.\nShareholders grew RESTIVE as the promised turnaround failed to arrive for a third straight year.","options":["impatient and hard to control","calm and well rested","resigned to losses","indifferent"],"answer":0,"explanation":"'Restive' means restless and increasingly unwilling to be held back, the natural reaction to three years of broken promises. It does not mean 'restful'; 'resigned' and 'indifferent' describe passive acceptance instead.","difficulty":"hard","source":"Infosys · CAT VARC"},
  {"id":"apt-verbal-placement-475","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nDespite two weak quarters, the founder remained SANGUINE about the company's prospects.","options":["optimistic","pessimistic","indifferent","furious"],"answer":1,"explanation":"'Sanguine' means cheerfully confident, as 'Despite two weak quarters' suggests, so its opposite is 'pessimistic'. 'Optimistic' is a synonym; 'indifferent' and 'furious' are about a different dimension.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-476","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nThe workers felt that their union leaders had SOLD THEM DOWN THE RIVER by accepting the pay cut without a vote.","options":["rescued them","exhausted them","betrayed them","overstated their demands"],"answer":2,"explanation":"To sell someone down the river is to betray people who trusted you, here by agreeing to a pay cut on their behalf without consulting them.","difficulty":"moderate","source":"Accenture · Capgemini"},
  {"id":"apt-verbal-placement-477","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nWith the funding round delayed, the mobile app has been put ON THE BACK BURNER.","options":["cancelled for good","handed to another team","rushed to completion","given low priority for the time being"],"answer":3,"explanation":"Something on the back burner is kept but set aside as less urgent, to be returned to later. 'Cancelled for good' overstates it; the idiom implies the work can resume.","difficulty":"moderate","source":"TCS NQT · AMCAT"},
  {"id":"apt-verbal-placement-478","question":"Choose the one word for: a paid post that involves little or no actual work.","options":["sinecure","sabbatical","stipend","honorarium"],"answer":0,"explanation":"A sinecure is a position that pays without demanding real duties. A sabbatical is a period of leave; a stipend is a fixed allowance; an honorarium is a payment for a service given without a normal fee.","difficulty":"hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-479","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Ebbinghaus found that most of what we learn is lost within days unless it is revisited.\nQ: His subject was himself: for years he memorised lists of nonsense syllables and tested how many he could recall.\nR: In the 1880s, a German psychologist set out to measure forgetting.\nS: Today's flashcard apps, which space their reviews further and further apart, are built on that finding.","options":["QRPS","RQPS","RPQS","RQSP"],"answer":1,"explanation":"R introduces 'a German psychologist'; Q ('His subject was himself') describes his method; P names him and gives the result; S applies 'that finding'. Q cannot open, since 'His' needs an antecedent, and S needs P's finding before it.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-480","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The result is a culture in which nobody admits a mistake until it is too late to fix cheaply.\nQ: Many firms say they want employees to report errors early.\nR: Yet the same firms often promote the people who appear never to make any.\nS: Staff learn quickly which behaviour is actually rewarded, as opposed to which is praised in speeches.","options":["QSRP","RQSP","QRSP","QRPS"],"answer":2,"explanation":"Q states the stated aim; R ('Yet the same firms') contradicts it; S explains how staff read the contradiction; P gives 'the result'. P must come last because it is the consequence of S, and R needs Q for 'the same firms'.","difficulty":"very-hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-481","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Steel and concrete expand in summer heat and contract in winter cold.\n2. Over a long bridge deck, this movement can add up to several centimetres.\n3. Concrete is weak in tension, which is why it is reinforced with steel bars.\n4. A deck fixed rigidly at both ends would crack under the resulting stresses.\n5. Expansion joints, the toothed gaps that thump under a car's tyres, let the deck move freely.","options":["Sentence 1","Sentence 2","Sentence 4","Sentence 3"],"answer":3,"explanation":"The paragraph traces one chain: thermal movement (1), its size (2), the danger of restraining it (4) and the solution (5). Sentence 3 is about bridge materials too, but about tensile strength, not thermal movement, so it breaks the chain.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-482","question":"Read the passage and answer the question.\n\nPassage: People tend to value what they have built themselves more than identical things built by others. In one set of experiments, participants who assembled a plain storage box were willing to pay considerably more for it than people offered the same box ready-made, but only if they finished it. Those asked to build the box and then take it apart before it was complete showed no such premium. If effort alone created value, the half-builders, who also worked, should have valued their boxes more. Instead, it seems that what we prize is the evidence of our own competence that a finished object provides.\n\nQuestion: The experiment with the half-built boxes serves mainly to:","options":["show that people dislike assembling furniture","prove that ready-made products are overpriced","rule out effort by itself as the explanation for the extra value","show that people value objects they did not make"],"answer":2,"explanation":"The half-builders worked but showed no premium, so effort alone cannot explain it; the author draws exactly this inference ('If effort alone created value …'). Nothing in the passage concerns disliking assembly or the pricing of ready-made goods.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-483","question":"Read the passage and answer the question.\n\nPassage: People tend to value what they have built themselves more than identical things built by others. In one set of experiments, participants who assembled a plain storage box were willing to pay considerably more for it than people offered the same box ready-made, but only if they finished it. Those asked to build the box and then take it apart before it was complete showed no such premium. If effort alone created value, the half-builders, who also worked, should have valued their boxes more. Instead, it seems that what we prize is the evidence of our own competence that a finished object provides.\n\nQuestion: Which finding, if true, would most WEAKEN the author's final explanation?","options":["People who fold their own paper cranes value them more than bought ones.","The half-builders spent as long on their boxes as the people who finished.","Buyers of the ready-made boxes earned more on average than the builders.","Builders told convincingly that their finished box was badly made still valued it just as highly."],"answer":3,"explanation":"If the premium survives clear evidence of incompetence, it cannot rest on 'evidence of our own competence'. Equal time spent supports the passage by ruling out effort; the paper cranes extend the effect; the buyers' incomes are irrelevant to the explanation.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-484","question":"Read the passage and answer the question.\n\nPassage: Words drift. 'Nice' once meant foolish; 'silly' once meant blessed; 'awful' meant worthy of awe. Such shifts are usually told as curiosities, but they follow patterns. Words for innocence and weakness tend to slide towards contempt, perhaps because a society that prizes strength finds the innocent easy to mock. Intensifiers wear out fastest: 'very' comes from a word meaning 'true', and 'terribly' and 'awfully' now mean little more than 'very' themselves. Speakers reach for a stronger word, use it until it is ordinary, then reach again. If there is a lesson, it is that no dictionary can freeze meaning; the most it can do is record where a word stood when its editors last looked.\n\nQuestion: The author's view of dictionaries is best described as:","options":["They record usage at a moment in time rather than fix it.","They should be ignored because meanings change.","They are responsible for slowing down change in meaning.","They wrongly record the older meanings of words."],"answer":0,"explanation":"The last sentence says a dictionary cannot freeze meaning and can only record where a word stood when last checked: a snapshot, not a rule. The author never says dictionaries should be ignored, slow change or get old meanings wrong.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-485","question":"Read the passage and answer the question.\n\nPassage: Words drift. 'Nice' once meant foolish; 'silly' once meant blessed; 'awful' meant worthy of awe. Such shifts are usually told as curiosities, but they follow patterns. Words for innocence and weakness tend to slide towards contempt, perhaps because a society that prizes strength finds the innocent easy to mock. Intensifiers wear out fastest: 'very' comes from a word meaning 'true', and 'terribly' and 'awfully' now mean little more than 'very' themselves. Speakers reach for a stronger word, use it until it is ordinary, then reach again. If there is a lesson, it is that no dictionary can freeze meaning; the most it can do is record where a word stood when its editors last looked.\n\nQuestion: According to the passage, intensifiers change faster than other words because:","options":["dictionaries do not record them","constant use makes them ordinary, so speakers keep needing new ones","they began as words for innocence and weakness","they were always informal and so never had a fixed meaning"],"answer":1,"explanation":"The passage describes a cycle: a strong word is used until it becomes ordinary, and then a stronger one is needed. The innocence-to-contempt pattern belongs to a different group of words, and nothing is said about dictionaries ignoring intensifiers.","difficulty":"hard","source":"CAT VARC · TCS NQT"},
  {"id":"apt-verbal-placement-486","question":"Read the passage and answer the question.\n\nPassage: Words drift. 'Nice' once meant foolish; 'silly' once meant blessed; 'awful' meant worthy of awe. Such shifts are usually told as curiosities, but they follow patterns. Words for innocence and weakness tend to slide towards contempt, perhaps because a society that prizes strength finds the innocent easy to mock. Intensifiers wear out fastest: 'very' comes from a word meaning 'true', and 'terribly' and 'awfully' now mean little more than 'very' themselves. Speakers reach for a stronger word, use it until it is ordinary, then reach again. If there is a lesson, it is that no dictionary can freeze meaning; the most it can do is record where a word stood when its editors last looked.\n\nQuestion: The history of 'silly' best illustrates which claim in the passage?","options":["Intensifiers wear out fastest.","No dictionary can freeze meaning.","Words for innocence tend to slide towards contempt.","Shifts in meaning are mere curiosities."],"answer":2,"explanation":"'Silly' moved from 'blessed' (innocent, favoured) to 'foolish' (mocked): the innocence-to-contempt slide. It is not an intensifier, and the passage rejects the idea that such shifts are mere curiosities.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-487","question":"Critical reasoning. A company found that staff at branches with a free fruit bowl in the break room took 15% fewer sick days than staff at branches without one. HR therefore plans to put fruit bowls in every branch to cut sick leave.\nWhich of the following, if true, most seriously weakens the plan?","options":["Fruit is cheaper than the cost of one day of sick leave per employee.","The branches that had fruit bowls are the ones with the youngest staff, who take less sick leave wherever they work.","Some employees at the fruit-bowl branches do not eat fruit at all.","Sick leave at all branches has fallen over the last five years."],"answer":1,"explanation":"If the fruit-bowl branches simply have younger staff, age, not fruit, explains the gap, and adding bowls elsewhere will change little. Cost supports the plan; some non-eaters only dilutes the effect; a general fall over time does not touch the comparison between branches.","difficulty":"hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-488","question":"Critical reasoning. \"Our competitor's app has been downloaded twice as often as ours, so its design must be better than ours.\"\nThe argument assumes that:","options":["our app has fewer features than the competitor's","download numbers will stay the same next year","the number of downloads reflects design quality rather than, say, advertising spend or price","users who download an app always keep using it"],"answer":2,"explanation":"The conclusion about design follows only if downloads are driven by design and not by other causes such as marketing or price; that hidden link is the assumption. Features, future numbers and retention are not needed for the argument to go through.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-489","question":"Critical reasoning. After a city introduced a charge for driving into its centre, average traffic speed in the centre rose, but so did the number of road accidents there.\nWhich of the following, if true, best explains this?","options":["The charge was higher than in most other cities.","Traffic speed outside the centre did not change.","Drivers who paid the charge were mostly commuters.","With fewer cars, far more people began cycling in the centre, and most of the new accidents involved cyclists."],"answer":3,"explanation":"The puzzle is that less traffic came with more accidents. A large rise in cyclists, who are the people involved in the new accidents, reconciles the two facts. The other options say nothing about why accidents went up.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-490","question":"All the projects that overran their budgets last year used external contractors. No project in the Pune office used external contractors.\nWhich of the following must be true?","options":["No project in the Pune office overran its budget last year.","Every project that used external contractors overran its budget.","Every project outside Pune used external contractors.","Some Pune projects came in under budget because they avoided contractors."],"answer":0,"explanation":"Overrunning implies using contractors; Pune projects used none, so none of them overran. The second option reverses the rule (not all contractor projects need have overrun); the last adds a cause the statements never give.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-491","question":"Critical reasoning. \"Ninety per cent of the people who attended our free webinar said they found it useful, so most of our customers would find it useful too.\"\nWhich is the main flaw in this reasoning?","options":["It assumes that ninety per cent is a majority.","It generalises from people who chose to attend, who are likely to be the most interested, to all customers.","It ignores the cost of running the webinar.","It does not say how long the webinar lasted."],"answer":1,"explanation":"Attendees selected themselves, so they are probably more interested than the average customer; their opinion is not a fair sample of all customers. Ninety per cent is indeed a majority, and cost or length do not bear on the inference.","difficulty":"hard","source":"Accenture · CAT VARC"},
  {"id":"apt-verbal-placement-492","question":"Critical reasoning. A school says that its new reading programme worked, because this year's students in the programme scored higher on the reading test than last year's students, who did not have the programme.\nThe answer to which question would be most useful in judging this claim?","options":["How much did the programme cost per student?","Did the teachers enjoy using the programme?","Was this year's test the same as, or as difficult as, last year's test?","How many books are in the school library?"],"answer":2,"explanation":"Comparing two years is valid only if the measuring stick stayed the same; an easier test alone could produce higher scores. Cost, teacher enjoyment and the library do not affect whether the score rise was caused by the programme.","difficulty":"very-hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-493","question":"Statements: All coders are thinkers. Some thinkers are poets. No poet is lazy.\nConclusions:\nI. Some coders are poets.\nII. Some thinkers are not lazy.","options":["Only I follows","Both I and II follow","Neither I nor II follows","Only II follows"],"answer":3,"explanation":"The thinkers who are poets cannot be lazy, so some thinkers are not lazy: II follows. Coders are only some of the thinkers, and nothing places any coder among the poets, so I does not follow.","difficulty":"hard","source":"TCS NQT · Capgemini"},
  {"id":"apt-verbal-placement-494","question":"Statements: No manager is an intern. Some interns are graduates.\nConclusions:\nI. Some graduates are not managers.\nII. Some managers are not graduates.","options":["Only I follows","Only II follows","Both I and II follow","Neither I nor II follows"],"answer":0,"explanation":"The graduates who are interns cannot be managers, so I follows. The statements say nothing about which managers are graduates; every manager could be one, so II does not follow.","difficulty":"very-hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-495","question":"\"The deal will close this week unless the regulator objects.\" It turns out that the deal did not close this week.\nIf the first statement is true, which of the following must also be true?","options":["The regulator did not object.","The regulator objected.","The deal will close next week.","The regulator's objection was the only problem with the deal."],"answer":1,"explanation":"'A unless B' means 'if B does not happen, A happens'. Its contrapositive is 'if A does not happen, B happened': the deal failed to close, so the regulator must have objected. Nothing follows about next week or about other problems.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-verbal-placement-496","question":"Choose the word that completes the analogy.\nMAVERICK : CONFORMITY :: SCEPTIC : ?","options":["doubt","enquiry","credulity","rebellion"],"answer":2,"explanation":"A maverick is defined by rejecting conformity; a sceptic is defined by rejecting credulity (readiness to believe). 'Doubt' is what a sceptic has, not what he rejects; 'rebellion' fits the maverick, not the sceptic.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-497","question":"Choose the pair that has the same relationship as QUARRY : STONE.","options":["bakery : flour","library : reader","kiln : clay","mine : ore"],"answer":3,"explanation":"A quarry is the place from which stone is extracted, as a mine is for ore. A bakery uses flour rather than producing it, a kiln processes clay, and a library serves readers.","difficulty":"moderate","source":"AMCAT · Wipro"},
  {"id":"apt-verbal-placement-498","question":"Choose the best replacement for the part in capitals. If no change is needed, choose \"No improvement\".\nThe new billing process is more efficient AS COMPARED TO the old one.","options":["than the old one","compared with the old one","as the old one","No improvement"],"answer":0,"explanation":"A comparative adjective ('more efficient') is completed by 'than'. 'More … as compared to' and 'more … compared with' double up the comparison; 'more … as' is ungrammatical.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-499","question":"You have to tell a candidate that she was not selected after the final interview. Which closing line is most appropriate for the email?","options":["Better luck next time!","Unfortunately, you were not good enough for this role.","We were impressed by your preparation and will keep your profile on file for future openings that match your experience.","We will definitely call you for the next opening."],"answer":2,"explanation":"The third option is courteous and honest and promises nothing it cannot keep. 'Better luck next time' is too casual, the second is needlessly hurtful, and the last makes a promise the company may not keep.","difficulty":"moderate","source":"Accenture · Capgemini"},
  {"id":"apt-verbal-placement-500","question":"Read the passage and choose the option that best summarises it.\n\nPassage: Cities short of housing often cap rents. Tenants who already have flats gain at once. But when renting out a flat pays less, owners sell to buyers who will live in it, convert buildings to other uses, or skimp on repairs, so fewer flats come up for rent each year. The people who bear the cost are not today's tenants but tomorrow's: newcomers searching a shrinking market.","options":["Rent caps hurt current tenants by lowering the quality of housing.","Landlords always prefer selling flats to renting them out.","Rent caps should be replaced by direct payments to tenants.","Rent caps help existing tenants but shrink the supply of rental housing, pushing the cost onto future renters."],"answer":3,"explanation":"The passage weighs an immediate gain for sitting tenants against a reduced supply that hurts later arrivals. It says current tenants gain, does not claim landlords always sell, and proposes no alternative policy.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-501","question":"Choose the option that best completes the paragraph.\nSecurity teams long required users to change their passwords every 90 days. The logic seemed sound: a stolen password would soon expire. But users forced to invent new passwords constantly made predictable changes, so that 'Summer2023' became 'Autumn2023', and attackers learned the patterns. ________","options":["Many organisations have therefore stopped forcing routine changes and ask for one only when there is evidence that a password has been stolen.","Users therefore enjoy changing their passwords every season.","Attackers therefore prefer systems in which passwords never change.","Ninety days has therefore been confirmed as the ideal interval for a password change."],"answer":0,"explanation":"The paragraph shows that the rule backfired because forced changes became predictable; the natural conclusion is to drop routine changes in favour of changes when there is a reason. The other options contradict the passage or draw a conclusion it does not support.","difficulty":"hard","source":"TCS NQT · Product company OA"},
  {"id":"apt-verbal-placement-502","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. On a busy motorway, one driver brakes slightly harder than needed.\n2. The driver behind brakes a little harder still, and the effect grows down the line.\n3. Minutes later, cars far behind come to a complete stop for no visible reason.\n4. Many drivers believe that changing lanes often gets them home faster.\n5. Researchers have reproduced such 'phantom jams' with cars simply driving in a circle on an empty track.","options":["Sentence 2","Sentence 4","Sentence 3","Sentence 5"],"answer":1,"explanation":"Sentences 1, 2, 3 and 5 explain how a jam can arise from nothing but amplified braking, and how this has been shown experimentally. Sentence 4 is about driver beliefs on lane changing, a different topic.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-503","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Counting output is easy when the product is a widget.\nQ: A programmer who deletes a thousand lines of tangled code may have had her most productive week.\nR: In knowledge work, the obvious counts often point the wrong way.\nS: Measured by lines written, she has gone backwards.\nT: Managers who cannot see this end up rewarding the activity that merely looks like work.","options":["RPQST","PRSQT","PRQST","PQSRT"],"answer":2,"explanation":"P sets up the easy case; R contrasts knowledge work; Q gives the example; S shows the naive count misreading it ('she'); T draws the managerial lesson ('this'). S needs Q for 'she', and R must precede Q to frame it as a counter-example.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-504","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The idea is to soften criticism by placing it between two compliments.\nQ: Many managers are taught to give feedback as a 'sandwich'.\nR: Worse, they begin to distrust every compliment, expecting criticism to follow.\nS: In practice, listeners soon learn to ignore the bread and wait for the filling.","options":["QSPR","PQSR","QPRS","QPSR"],"answer":3,"explanation":"Q names the technique; P explains the idea; S shows how it fails in practice (the bread-and-filling image needs P's explanation first); R ('Worse') escalates the problem. R must follow S because it builds on listeners having learned the pattern.","difficulty":"hard","source":"TCS NQT · Accenture"},
  {"id":"apt-verbal-placement-505","question":"Read the passage and answer the question.\n\nPassage: When a painting is cleaned, centuries of yellowed varnish come away and colours return that no living person has seen. Restorers call this recovering the artist's intention; their critics call it inventing one. The difficulty is that pigments themselves change: some blues fade, some reds darken, and no amount of cleaning returns a canvas to the day it left the studio. What the restorer produces is therefore not the original but a judgement about what the original looked like: informed, often brilliant, but a judgement. Critics do not usually argue for leaving the grime in place. Their point is narrower: a cleaned painting should be presented as an interpretation, with a record of what was removed kept as carefully as the paint that remains.\n\nQuestion: The critics' position, as described in the passage, is best summarised as:","options":["Cleaning may go ahead, but the result should be presented as an interpretation and the removal documented.","Paintings should never be cleaned, because cleaning destroys the original.","Restorers are not skilled enough to clean paintings safely.","The yellowed varnish is part of the artist's intention and should be preserved."],"answer":0,"explanation":"The passage says critics do not want grime left in place; their narrower point is about presentation and record-keeping. The second option is the very misreading the author heads off, and the passage praises restorers' judgement as 'often brilliant'.","difficulty":"hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-506","question":"Read the passage and answer the question.\n\nPassage: When a painting is cleaned, centuries of yellowed varnish come away and colours return that no living person has seen. Restorers call this recovering the artist's intention; their critics call it inventing one. The difficulty is that pigments themselves change: some blues fade, some reds darken, and no amount of cleaning returns a canvas to the day it left the studio. What the restorer produces is therefore not the original but a judgement about what the original looked like: informed, often brilliant, but a judgement. Critics do not usually argue for leaving the grime in place. Their point is narrower: a cleaned painting should be presented as an interpretation, with a record of what was removed kept as carefully as the paint that remains.\n\nQuestion: With which statement would the author most likely agree?","options":["Removing varnish restores faded blues to their original shade.","Even a flawless cleaning cannot show us exactly what the artist saw.","Restorers deliberately mislead the public about their work.","Old varnish should be left on paintings to protect them."],"answer":1,"explanation":"Because pigments themselves change, cleaning cannot return a canvas to its studio state, so even perfect work yields a judgement, not the original. The passage says blues fade regardless of cleaning, never accuses restorers of deceit, and does not defend keeping varnish.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-507","question":"Read the passage and answer the question.\n\nPassage: When a painting is cleaned, centuries of yellowed varnish come away and colours return that no living person has seen. Restorers call this recovering the artist's intention; their critics call it inventing one. The difficulty is that pigments themselves change: some blues fade, some reds darken, and no amount of cleaning returns a canvas to the day it left the studio. What the restorer produces is therefore not the original but a judgement about what the original looked like: informed, often brilliant, but a judgement. Critics do not usually argue for leaving the grime in place. Their point is narrower: a cleaned painting should be presented as an interpretation, with a record of what was removed kept as carefully as the paint that remains.\n\nQuestion: The sentence \"Critics do not usually argue for leaving the grime in place\" mainly serves to:","options":["show that the critics have changed their minds","prove that cleaning is always beneficial","head off a likely misreading of the critics' position","suggest that grime protects paintings from damage"],"answer":2,"explanation":"After 'inventing one', a reader might assume the critics oppose cleaning altogether; this sentence blocks that reading before the author states their narrower point. Nothing suggests a change of mind, a universal benefit, or a protective role for grime.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-508","question":"Choose the meaning of the word in capitals as used in the sentence.\nAsked directly whether the layoffs would continue, the spokesperson PREVARICATED for ten minutes without giving an answer.","options":["spoke confidently","apologised repeatedly","made a forecast","spoke evasively"],"answer":3,"explanation":"To prevaricate is to avoid giving a straight answer, which matches ten minutes 'without giving an answer'. Confidence, apology and forecasting all imply engaging with the question.","difficulty":"hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-509","question":"In which sentence is 'enormity' used in its traditional, exam-standard sense?","options":["The enormity of the fraud shocked even hardened investigators.","The enormity of the new stadium impressed the visitors.","She underestimated the enormity of the paperwork involved.","The enormity of the elephant made the children gasp."],"answer":0,"explanation":"In careful usage 'enormity' means great wickedness or a grave crime, which fits a fraud. Using it for sheer size (a stadium, paperwork, an elephant) is the common error; 'enormousness' or 'immensity' is the word for size.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-510","question":"In which sentence is 'complement' or 'compliment' used correctly?","options":["She complemented him on his clear presentation.","The new sauce complements the grilled fish perfectly.","The hotel offers a complementary breakfast to every guest.","With two new hires, the team is now at full compliment."],"answer":1,"explanation":"'Complement' means to complete or go well with something, as a sauce does a dish. Praise is a compliment ('complimented him'); free is 'complimentary'; a full set is a 'full complement'.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-511","question":"Fill in the blank with the correct preposition.\nThe new travel policy is at odds ___ the company's stated commitment to work–life balance.","options":["to","against","with","from"],"answer":2,"explanation":"The fixed phrase is 'at odds with', meaning in conflict with. The other prepositions are not idiomatic after 'at odds'.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-512","question":"Fill in the blank.\nThe manager asked us to ___ the old approval process altogether and design a simpler one from scratch.","options":["do up","put up with","make do with","do away with"],"answer":3,"explanation":"'Do away with' means to abolish, which fits scrapping the process 'altogether'. 'Put up with' and 'make do with' mean tolerating it, the opposite of replacing it; 'do up' means to repair or fasten.","difficulty":"moderate","source":"Capgemini · AMCAT"},
  {"id":"apt-verbal-placement-513","question":"Critical reasoning. A bakery chain says its new loyalty app has increased repeat visits, because customers who use the app visit its shops twice as often as customers who do not.\nWhich of the following, if true, most strengthens the chain's claim?","options":["Before the app was launched, the customers who later downloaded it visited no more often than other customers.","The app was downloaded by the chain's most loyal customers in its first week.","Customers who use the app also spend more per visit.","Several rival bakeries have launched similar apps."],"answer":0,"explanation":"The obvious objection is that frequent visitors are the ones who download the app; showing that users visited no more often before the launch removes that reverse-causation explanation. The second option strengthens the objection; spending per visit and rivals' apps are beside the point.","difficulty":"very-hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-514","question":"Which of these sentences about Priya's Friday routine is grammatically correct?","options":["She is used to work late on Fridays.","She used to working late on Fridays.","She is used to working late on Fridays.","She is use to working late on Fridays."],"answer":2,"explanation":"'Be used to' means 'be accustomed to', and its 'to' is a preposition, so it takes a gerund: 'is used to working'. 'Used to work' (without 'is') would describe a past habit; the other options mix the two patterns or misspell 'used'.","difficulty":"hard","source":"AMCAT · TCS NQT"},
  {"id":"apt-verbal-placement-515","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nOne of the key reasons / for the delays / are the shortage / of skilled welders.","options":["One of the key reasons","for the delays","No error","are the shortage"],"answer":3,"explanation":"The subject is 'One', so the verb must be singular: 'is the shortage'. The plurals 'reasons' and 'delays' between subject and verb are the distraction.","difficulty":"moderate","source":"Wipro · Capgemini"},
  {"id":"apt-verbal-placement-516","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHaving been delayed / by the storm, / the passengers were offered / free meals by the airline.","options":["No error","Having been delayed","by the storm,","the passengers were offered"],"answer":0,"explanation":"The opening phrase describes the passengers, and 'the passengers' is exactly the subject of the main clause, so the modifier is attached correctly and the passive 'were offered' is fine. Students trained to hunt dangling modifiers often mark a correct one.","difficulty":"very-hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-517","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nI look forward to / hear from you / at your earliest / convenience.","options":["I look forward to","hear from you","at your earliest","No error"],"answer":1,"explanation":"In 'look forward to', 'to' is a preposition, so it is followed by a gerund: 'I look forward to hearing from you'. Treating it as part of an infinitive is the usual slip.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-518","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe new manager is / more stricter than / the old one, / but she is fair.","options":["The new manager is","the old one,","more stricter than","but she is fair."],"answer":2,"explanation":"'Stricter' is already comparative, so adding 'more' makes a double comparative. It should be 'stricter than the old one'.","difficulty":"moderate","source":"Wipro · AMCAT"},
  {"id":"apt-verbal-placement-519","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe data clearly shows / that customers who / receives reminders / pay their bills on time.","options":["The data clearly shows","that customers who","No error","receives reminders"],"answer":3,"explanation":"'Who' stands for 'customers', which is plural, so the verb must be 'receive'. ('The data shows' is acceptable in modern usage, so the first part is not the error.)","difficulty":"hard","source":"Infosys · Accenture"},
  {"id":"apt-verbal-placement-520","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nWhomever / submits the best proposal / will win / the contract.","options":["Whomever","submits the best proposal","will win","No error"],"answer":0,"explanation":"The pronoun is the subject of 'submits', so it must be 'Whoever'. The case of 'whoever/whomever' is set by its role inside its own clause, not by the main sentence.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-521","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nEvery employee and every contractor / are required / to wear an ID badge / inside the building.","options":["Every employee and every contractor","are required","to wear an ID badge","No error"],"answer":1,"explanation":"When two singular nouns joined by 'and' are each preceded by 'every' (or 'each'), the verb is singular: 'is required'. The 'and' tempts a plural verb.","difficulty":"very-hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-522","question":"Fill in the blank.\nShe would rather ___ the project herself than hand it to an untested team.","options":["handled","handling","handle","to handle"],"answer":2,"explanation":"When the subject of 'would rather' does the action herself, it is followed by the bare infinitive: 'would rather handle'. A past form ('handled') is used only when the action belongs to someone else: 'I would rather you handled it'.","difficulty":"hard","source":"Accenture · Infosys"},
  {"id":"apt-verbal-placement-523","question":"Fill in the blank.\nSeldom ___ such a clear-cut case of fraud.","options":["the auditors have seen","had seen the auditors","the auditors saw","have the auditors seen"],"answer":3,"explanation":"A negative adverb such as 'Seldom' at the start of a sentence triggers inversion with an auxiliary: 'Seldom have the auditors seen …'. Normal word order is wrong after it, and the main verb cannot move before the subject on its own.","difficulty":"hard","source":"CAT VARC · TCS NQT"},
  {"id":"apt-verbal-placement-524","question":"Fill in the blank.\nFar from helping to ___ the parking problem, the new office tower has made it considerably worse.","options":["ameliorate","exacerbate","obviate","galvanise"],"answer":0,"explanation":"'Far from …, it made it worse' needs a verb meaning 'improve': ameliorate. 'Exacerbate' describes what actually happened, so it cannot follow 'Far from'; 'obviate' means to make unnecessary, and 'galvanise' means to spur into action.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-525","question":"Choose the pair of words that best fills the blanks.\nThe union leader's ___ stance, refusing to give ground on a single point, left the talks ___ for weeks.","options":["conciliatory ... deadlocked","intransigent ... deadlocked","flexible ... stalled","intransigent ... flourishing"],"answer":1,"explanation":"Refusing to give ground is intransigence, and its natural result is deadlock. 'Conciliatory' and 'flexible' contradict 'refusing to give ground'; 'flourishing' contradicts the effect of such a stance.","difficulty":"hard","source":"Capgemini · CAT VARC"},
  {"id":"apt-verbal-placement-526","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe committee gave the proposal only a CURSORY glance before rejecting it.","options":["careful","hostile","hasty and superficial","final"],"answer":2,"explanation":"A cursory look is quick and not thorough, which 'only' and the swift rejection reinforce. 'Careful' is the opposite; 'hostile' and 'final' describe attitude or timing, not thoroughness.","difficulty":"moderate","source":"TCS NQT · AMCAT"},
  {"id":"apt-verbal-placement-527","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe founder's INSOUCIANT reply to the fraud allegations, a shrug and a joke, alarmed the investors.","options":["furious","evasive","apologetic","carelessly unconcerned"],"answer":3,"explanation":"Insouciance is a casual lack of concern, shown by the shrug and the joke, and it alarms investors precisely because the allegations are serious. 'Evasive' is close but describes dodging a question, not treating it lightly.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-528","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nHer GARRULOUS colleague could turn a two-minute update into a half-hour monologue.","options":["taciturn","talkative","cheerful","rude"],"answer":0,"explanation":"'Garrulous' means excessively talkative, as the half-hour monologue shows; its opposite is 'taciturn', saying very little. 'Talkative' is a synonym.","difficulty":"hard","source":"AMCAT · Infosys"},
  {"id":"apt-verbal-placement-529","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe minister's plan to digitise every land record in the state within a month was admirable but QUIXOTIC.","options":["cunning and secretive","idealistic but impractical","cheap but effective","dull and routine"],"answer":1,"explanation":"Quixotic (from Don Quixote) describes a noble aim pursued without regard to practicality; 'admirable but' and the absurd one-month deadline point there. The other options miss the mix of idealism and unrealism.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-530","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe auditors found an EGREGIOUS error in the balance sheet: a debt of ₹40 crore had simply been left out.","options":["minor","clever","outstandingly bad","repeated"],"answer":2,"explanation":"An egregious error is shockingly bad, and leaving out a ₹40-crore debt is exactly that. The word's Latin root once meant 'distinguished', which misleads some candidates into a positive reading such as 'clever'.","difficulty":"very-hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-531","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nThe new export rules have opened A CAN OF WORMS for small exporters, who now face three overlapping sets of paperwork.","options":["created a profitable opportunity","settled a long dispute","caused a temporary delay","created a set of complicated new problems"],"answer":3,"explanation":"To open a can of worms is to start something that produces many unexpected, troublesome problems, here three overlapping sets of paperwork. 'Temporary delay' understates it.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-verbal-placement-532","question":"Choose the one word for: a person who believes that people are motivated purely by self-interest.","options":["cynic","sceptic","misanthrope","pessimist"],"answer":0,"explanation":"A cynic distrusts people's motives, assuming self-interest. A sceptic doubts claims, a misanthrope dislikes humankind, and a pessimist expects the worst outcome; none of these is specifically about motives.","difficulty":"hard","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-533","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Airlines know from experience that some passengers will not turn up for any given flight.\nQ: Selling exactly as many tickets as there are seats would therefore mean flying with empty seats.\nR: So they sell a few more tickets than seats, betting that the no-shows will make room.\nS: When the bet fails, someone has to be paid to take a later flight.\nT: That compensation is usually far cheaper than flying half-empty would be.","options":["PRQST","PQRST","QPRST","PQRTS"],"answer":1,"explanation":"P gives the fact; Q ('therefore') draws its consequence; R ('So') gives the airlines' response; S describes the failure of 'the bet'; T weighs 'that compensation'. T must follow S, which introduces the compensation.","difficulty":"hard","source":"TCS NQT · Accenture"},
  {"id":"apt-verbal-placement-534","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: That, at least, is the theory.\nQ: Open-book exams are meant to test understanding rather than memory.\nR: In practice, students who have not studied waste so much time searching their notes that they rarely finish.\nS: With the facts on the desk, only the reasoning is left to be judged.","options":["QPSR","SQPR","QSPR","QSRP"],"answer":2,"explanation":"Q states the purpose; S explains the reasoning behind it; P ('That … is the theory') sums up Q and S and signals a turn; R ('In practice') delivers it. Placing P right after Q leaves S stranded after the turn to practice.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-535","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Cutting an onion breaks open its cells and lets enzymes mix with sulphur compounds.\n2. The reaction produces a volatile gas that drifts up towards the eyes.\n3. There it stimulates nerves that trigger tears to wash the irritant away.\n4. Onions also contain compounds that some studies link to lower blood pressure.\n5. Chilling the onion first slows the reaction, which is why cold onions cause fewer tears.","options":["Sentence 2","Sentence 3","Sentence 5","Sentence 4"],"answer":3,"explanation":"Sentences 1, 2, 3 and 5 explain why cutting onions causes tears and how to reduce them. Sentence 4 is about onions, but about their effect on health, not about tears.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-verbal-placement-536","question":"Read the passage and answer the question.\n\nPassage: Boredom has a poor reputation. We treat it as wasted time, something to be filled at once with a screen. Yet psychologists who study it describe it less as an empty state than as a signal: a feeling that what we are doing does not match what we want to be doing. Like pain, it is unpleasant precisely because it is meant to move us. Seen this way, the trouble with filling every idle minute is not that we lose the boredom but that we silence the message before reading it. A person who never feels bored is not necessarily engaged; he may simply have learned to switch the alarm off.\n\nQuestion: The author compares boredom to pain in order to:","options":["suggest that its unpleasantness serves a purpose","argue that boredom is physically harmful","show that boredom should be treated by doctors","claim that boredom is worse than pain"],"answer":0,"explanation":"The comparison makes the point that both feel bad 'precisely because' they are meant to prompt action. The author does not say boredom is harmful, medical or worse than pain.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-537","question":"Read the passage and answer the question.\n\nPassage: Boredom has a poor reputation. We treat it as wasted time, something to be filled at once with a screen. Yet psychologists who study it describe it less as an empty state than as a signal: a feeling that what we are doing does not match what we want to be doing. Like pain, it is unpleasant precisely because it is meant to move us. Seen this way, the trouble with filling every idle minute is not that we lose the boredom but that we silence the message before reading it. A person who never feels bored is not necessarily engaged; he may simply have learned to switch the alarm off.\n\nQuestion: In the last sentence, 'switch the alarm off' most nearly refers to:","options":["finding work that is truly engaging","habitually distracting oneself so that boredom's signal is never acted on","learning to sleep through noise","refusing to use screens altogether"],"answer":1,"explanation":"The 'alarm' is boredom's signal; switching it off means suppressing it, by the instant distraction described earlier, without heeding the message. Being truly engaged is the alternative the author contrasts it with.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-538","question":"Read the passage and answer the question.\n\nPassage: Boredom has a poor reputation. We treat it as wasted time, something to be filled at once with a screen. Yet psychologists who study it describe it less as an empty state than as a signal: a feeling that what we are doing does not match what we want to be doing. Like pain, it is unpleasant precisely because it is meant to move us. Seen this way, the trouble with filling every idle minute is not that we lose the boredom but that we silence the message before reading it. A person who never feels bored is not necessarily engaged; he may simply have learned to switch the alarm off.\n\nQuestion: Which advice is most in keeping with the passage?","options":["Avoid boredom by always carrying something to read.","Accept boredom as a permanent part of modern life.","When bored, first ask what you would rather be doing before reaching for a distraction.","Treat boredom as a sign that you need more rest."],"answer":2,"explanation":"If boredom signals a gap between what we are doing and what we want to be doing, the sensible response is to read that message, which is what the third option says. The first option is the reflex the author criticises; the others ignore the signal idea.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-539","question":"Critical reasoning. To cut plastic waste, the office canteen will charge ₹5 for every disposable cup, and the facilities team expects cup use to fall sharply as a result.\nThe team's expectation depends on which assumption?","options":["Most staff drink more than one cup of tea a day.","Disposable cups are more expensive to buy than ₹5 each.","The canteen will make a profit from the charge.","A ₹5 charge is enough to change staff behaviour, and they have a practical alternative such as their own mugs."],"answer":3,"explanation":"The charge reduces use only if people respond to it and can switch to something else; if either fails, they simply pay. The number of cups per person, the cups' cost and the canteen's profit do not decide whether use falls.","difficulty":"very-hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-540","question":"Critical reasoning. A firm raised the price of its premium headphones by 20%, and their sales went up.\nWhich of the following, if true, best explains this?","options":["Many buyers of premium headphones judge quality by price, so the higher price made them seem better.","The firm's cheaper headphones sold less well in the same period.","Raw material costs rose during the year.","The firm did not advertise the headphones that year."],"answer":0,"explanation":"Normally a price rise cuts sales; if buyers read a higher price as a sign of quality, the rise can attract them. Falling sales of cheaper models, higher costs and no advertising do not explain why demand went up.","difficulty":"hard","source":"Product company OA · CAT VARC"},
  {"id":"apt-verbal-placement-541","question":"Some of the invoices that Karan checked were overdue. Every overdue invoice was sent to the legal team.\nWhich of the following must be true?","options":["Every invoice Karan checked was sent to the legal team.","At least one invoice that Karan checked was sent to the legal team.","Every invoice sent to the legal team was checked by Karan.","Karan checked only overdue invoices."],"answer":1,"explanation":"The overdue invoices among Karan's went to legal, so at least one of his did. Nothing says all his invoices were overdue, or that legal received only his invoices.","difficulty":"very-hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-542","question":"Read the passage and choose the option that best summarises it.\n\nPassage: Most new drugs are approved after trials showing that they work better than a dummy pill. That tells regulators the drug does something. It does not tell a doctor whether the new drug is better than the one she already prescribes, and that is the question her patient is asking. Trials that compare a new drug with the existing treatment are rarer, partly because a manufacturer has little to gain from a test it might lose.","options":["Most new drugs are no better than dummy pills.","Regulators should stop approving new drugs.","Trials against dummy pills show that a drug works, but the more useful comparison with existing treatments is often missing.","Doctors should prescribe only older drugs."],"answer":2,"explanation":"The passage contrasts what placebo trials prove (the drug works) with what patients need (whether it beats the current drug), and notes why head-to-head trials are rare. It does not claim drugs are useless or recommend banning or avoiding them.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-543","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe profits were / divided equally / among the two / partners.","options":["The profits were","divided equally","No error","among the two"],"answer":3,"explanation":"'Between' is used for two parties and 'among' for three or more, so it should be 'between the two partners'.","difficulty":"hard","source":"Wipro · AMCAT"},
  {"id":"apt-verbal-placement-544","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe vendor denied / to have received / the purchase order / on time.","options":["to have received","The vendor denied","the purchase order","No error"],"answer":0,"explanation":"'Deny' is followed by a gerund, not an infinitive: 'denied having received' (or 'denied receiving'). Verbs like deny, admit, avoid and risk take the -ing form.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-545","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nLittle she knew / that the client / had already signed / with a competitor.","options":["that the client","Little she knew","had already signed","No error"],"answer":1,"explanation":"'Little', used negatively at the start of a sentence, requires inversion with an auxiliary: 'Little did she know that …'. The rest of the sentence is correct.","difficulty":"hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-546","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nMathematics are / the subject / she enjoys / most.","options":["the subject","she enjoys","Mathematics are","No error"],"answer":2,"explanation":"Names of subjects ending in -ics, such as mathematics, physics and economics, take a singular verb when they mean the discipline: 'Mathematics is the subject …'.","difficulty":"moderate","source":"AMCAT · Capgemini"},
  {"id":"apt-verbal-placement-547","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe lesser known / of the two candidates / was, surprisingly, / the more qualified.","options":["The lesser known","of the two candidates","was, surprisingly,","No error"],"answer":3,"explanation":"With two candidates, comparatives are correct: 'the lesser known' and 'the more qualified' (superlatives would be wrong here). The singular 'was' agrees with 'The lesser known'. Candidates who expect 'least' or 'most' talk themselves into a false error.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-548","question":"Fill in the blank.\nThe report must be submitted by Friday ___ an extension is approved in writing.","options":["unless","until","lest","provided"],"answer":0,"explanation":"'Unless' means 'except if': Friday is the deadline except when an extension is approved. 'Provided' would make the deadline apply only when an extension is approved, the reverse of the intended meaning; 'until' and 'lest' do not fit.","difficulty":"hard","source":"TCS NQT · Capgemini"},
  {"id":"apt-verbal-placement-549","question":"Fill in the blank.\n___ the gloomy weather forecast, the outdoor launch went ahead as planned.","options":["Despite of","Notwithstanding","Although","Inspite"],"answer":1,"explanation":"'Notwithstanding' is a preposition meaning 'in spite of' and can take a noun phrase directly. 'Despite of' is a common error ('despite' takes no 'of'); 'Although' needs a full clause; 'inspite' is a misspelling of 'in spite of'.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-verbal-placement-550","question":"Fill in the blank.\nIt was not until the audit ___ the full scale of the losses became clear.","options":["completed when","was completed then","was completed that","had completed so"],"answer":2,"explanation":"The cleft pattern is 'It was not until X that Y': 'It was not until the audit was completed that the full scale … became clear'. The audit is completed by someone, so the passive is also needed; 'when', 'then' and 'so' break the pattern.","difficulty":"very-hard","source":"CAT VARC · TCS NQT"},
  {"id":"apt-verbal-placement-551","question":"Choose the pair of words that best fills the blanks.\nThe scientist was ___ about her results, calling them 'suggestive at best', even though the press hailed them as ___.","options":["boastful ... modest","cautious ... tentative","dismissive ... trivial","circumspect ... groundbreaking"],"answer":3,"explanation":"'Suggestive at best' shows caution (circumspect), and 'even though' needs the press to say something much stronger: groundbreaking. 'Cautious … tentative' has no contrast; 'boastful' contradicts her words.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-552","question":"Choose the meaning of the word in capitals as used in the sentence.\nThe inquiry found that several VENAL officials had approved the contracts in exchange for expensive gifts.","options":["open to bribery","minor and forgivable","careless","senior"],"answer":0,"explanation":"'Venal' means willing to act dishonestly for money, as approving contracts for gifts shows. 'Minor and forgivable' is the meaning of the look-alike 'venial', the trap here.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-553","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nThe new CFO is known for being PARSIMONIOUS with the travel budget.","options":["thrifty","lavish","strict","secretive"],"answer":1,"explanation":"'Parsimonious' means extremely unwilling to spend, so its opposite is 'lavish'. 'Thrifty' is a near-synonym; 'strict' and 'secretive' do not oppose it.","difficulty":"hard","source":"AMCAT · Wipro"},
  {"id":"apt-verbal-placement-554","question":"Choose the meaning of the word in capitals as used in the sentence.\nAfter the keynote speaker left, the panel discussion became DESULTORY, drifting from one topic to another without reaching any point.","options":["heated","scholarly","lacking focus or purpose","confidential"],"answer":2,"explanation":"'Desultory' describes something unfocused and half-hearted, which the drifting, pointless discussion illustrates. 'Heated' and 'scholarly' suggest intensity or depth, which the sentence rules out.","difficulty":"very-hard","source":"CAT VARC · AMCAT"},
  {"id":"apt-verbal-placement-555","question":"Choose the word or phrase closest in meaning to the word in capitals as used in the sentence.\nThe sudden wave of resignations proved to be a HARBINGER of the crisis that followed.","options":["result","cure","cause","forerunner"],"answer":3,"explanation":"A harbinger is something that signals that another thing is coming. The resignations came before the crisis and announced it; they are not described as its cause or result.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-556","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nTake the vendor's claims about '100% uptime' WITH A PINCH OF SALT until you have seen independent data.","options":["with some scepticism","with complete trust","with great enthusiasm","with legal advice"],"answer":0,"explanation":"To take something with a pinch of salt is to treat it with doubt; the advice to wait for independent data confirms the sense.","difficulty":"moderate","source":"Accenture · Capgemini"},
  {"id":"apt-verbal-placement-557","question":"Choose the meaning of the idiom in capitals as used in the sentence.\nThe huge convention centre, used for barely ten days a year, has become a WHITE ELEPHANT for the city.","options":["a symbol of civic pride","a costly possession that is more trouble than it is worth","a rare and valuable asset","a project that was finished early"],"answer":1,"explanation":"A white elephant is something expensive to maintain that brings little benefit, like a building used ten days a year. 'Rare and valuable asset' takes the image literally and misses the idiom's sense of burden.","difficulty":"hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-verbal-placement-558","question":"Choose the pair that has the same relationship as ARCHIPELAGO : ISLAND.","options":["ocean : water","forest : branch","constellation : star","library : page"],"answer":2,"explanation":"An archipelago is a group made up of islands, as a constellation is a group of stars. A forest is made of trees, not branches; a library of books, not pages; and water is a substance, not a member of a group.","difficulty":"hard","source":"AMCAT · CAT VARC"},
  {"id":"apt-verbal-placement-559","question":"Choose the pair that has the same relationship as PEDESTRIAN : IMAGINATION.","options":["fragrant : smell","loud : sound","generous : wealth","insipid : flavour"],"answer":3,"explanation":"Writing that is pedestrian lacks imagination; food that is insipid lacks flavour. In 'fragrant : smell' and 'loud : sound' the first word has the quality rather than lacking it, and generosity is not a lack of wealth.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-560","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Because every plant is genetically identical, a disease that can kill one can kill them all.\nQ: Almost all the bananas sold in supermarkets belong to a single variety, grown from cuttings rather than seeds.\nR: This is not an idle worry: the variety that dominated before it was largely wiped out by a fungus in the mid-twentieth century.\nS: Growers are now racing to breed resistant varieties before history repeats itself.","options":["QPRS","QRPS","PQRS","QPSR"],"answer":0,"explanation":"Q introduces the single, cloned variety; P draws the risk ('every plant is genetically identical'); R ('This is not an idle worry') gives a historical precedent; S describes the response ('history repeats itself' needs R). P cannot open, as it explains Q.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-verbal-placement-561","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Several public libraries have abolished fines for overdue books.\nQ: They had assumed that fines were what got books returned on time.\nR: Instead, they found that fines mostly kept poorer borrowers away, while books came back no later than before.\nS: Some even saw returns rise, as people who had been avoiding the library over unpaid fines came back with their books.\nT: A penalty meant to protect the collection had been protecting it from its readers.","options":["PRQST","PQSRT","PQRST","QPRST"],"answer":2,"explanation":"P states the change; Q ('They had assumed') gives the old belief; R ('Instead') reports what was found; S ('even') goes further; T sums up the irony. Q needs P for 'They', and S intensifies R, so it must follow it.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-562","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Sunlight contains all the colours of the visible spectrum.\n2. As it passes through the atmosphere, it is scattered by gas molecules.\n3. Shorter wavelengths, towards the blue end, are scattered far more strongly than longer ones.\n4. Rainbows form when sunlight is refracted and reflected inside raindrops.\n5. So blue light reaches our eyes from every part of the sky, making the whole sky look blue.","options":["Sentence 1","Sentence 3","Sentence 5","Sentence 4"],"answer":3,"explanation":"Sentences 1, 2, 3 and 5 explain why the sky is blue through scattering. Sentence 4 is also about sunlight and colour, but about rainbows, a different mechanism, so it breaks the chain.","difficulty":"hard","source":"Capgemini · Infosys"},
  {"id":"apt-verbal-placement-563","question":"Read the passage and answer the question.\n\nPassage: In 1847 a doctor working in a Vienna hospital noticed that women who gave birth in the ward staffed by doctors died of fever far more often than those in the ward run by midwives. He guessed that the doctors, who often came straight from performing autopsies, were carrying something on their hands, and when he made them wash in a chlorine solution, deaths fell sharply. His colleagues were not persuaded. Part of the problem was that he could not say what the 'something' was; germ theory lay decades in the future. But part of it was personal: to accept his explanation, doctors had to accept that they themselves had been killing their patients. Evidence that asks people to think worse of themselves faces a higher bar than evidence that does not.\n\nQuestion: The passage is mainly concerned with:","options":["explaining why a well-supported finding was resisted","describing how germ theory was discovered","comparing the skills of doctors and midwives","showing that chlorine was the first antiseptic"],"answer":0,"explanation":"The passage presents the finding briefly and spends most of its length on the two reasons it was rejected, ending with a general claim about such resistance. Germ theory is mentioned only as not yet existing, and the passage makes no claims about skills or 'firsts'.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-564","question":"Read the passage and answer the question.\n\nPassage: In 1847 a doctor working in a Vienna hospital noticed that women who gave birth in the ward staffed by doctors died of fever far more often than those in the ward run by midwives. He guessed that the doctors, who often came straight from performing autopsies, were carrying something on their hands, and when he made them wash in a chlorine solution, deaths fell sharply. His colleagues were not persuaded. Part of the problem was that he could not say what the 'something' was; germ theory lay decades in the future. But part of it was personal: to accept his explanation, doctors had to accept that they themselves had been killing their patients. Evidence that asks people to think worse of themselves faces a higher bar than evidence that does not.\n\nQuestion: With which statement would the author most likely agree?","options":["The colleagues were right to reject a result that had no known mechanism.","Even if germ theory had existed, every doctor would have accepted his finding at once.","The lack of an explanatory mechanism was only one of the reasons the finding was rejected.","The midwives were more careful than the doctors because they were better trained."],"answer":2,"explanation":"The author gives two reasons ('Part of the problem … But part of it was personal'), so the missing mechanism was not the whole story. The author does not endorse the rejection, and the personal reason would have survived germ theory, so 'every doctor at once' goes too far.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-565","question":"Read the passage and answer the question.\n\nPassage: In 1847 a doctor working in a Vienna hospital noticed that women who gave birth in the ward staffed by doctors died of fever far more often than those in the ward run by midwives. He guessed that the doctors, who often came straight from performing autopsies, were carrying something on their hands, and when he made them wash in a chlorine solution, deaths fell sharply. His colleagues were not persuaded. Part of the problem was that he could not say what the 'something' was; germ theory lay decades in the future. But part of it was personal: to accept his explanation, doctors had to accept that they themselves had been killing their patients. Evidence that asks people to think worse of themselves faces a higher bar than evidence that does not.\n\nQuestion: Which situation best illustrates the passage's final sentence?","options":["A new phone is criticised because it is more expensive than the old model.","A study blaming a firm's own managers for high staff turnover is attacked far more fiercely inside the firm than one blaming the job market.","A weather forecast is ignored because it was wrong last week.","A scientist's paper is rejected because it contains a calculation error."],"answer":1,"explanation":"The final sentence says that evidence implicating its audience meets more resistance. Managers resisting a study that blames them, but not one that blames outside conditions, is the same pattern. The other options involve price, a past record or a genuine error, not self-image.","difficulty":"very-hard","source":"CAT VARC"},
  {"id":"apt-verbal-placement-566","question":"Read the passage and answer the question.\n\nPassage: In 1847 a doctor working in a Vienna hospital noticed that women who gave birth in the ward staffed by doctors died of fever far more often than those in the ward run by midwives. He guessed that the doctors, who often came straight from performing autopsies, were carrying something on their hands, and when he made them wash in a chlorine solution, deaths fell sharply. His colleagues were not persuaded. Part of the problem was that he could not say what the 'something' was; germ theory lay decades in the future. But part of it was personal: to accept his explanation, doctors had to accept that they themselves had been killing their patients. Evidence that asks people to think worse of themselves faces a higher bar than evidence that does not.\n\nQuestion: According to the doctor's hypothesis, deaths were higher in the doctors' ward because:","options":["the midwives' ward was cleaner and better ventilated","the doctors' ward admitted sicker women","the chlorine solution itself was harmful","doctors arrived from autopsies carrying something on their hands"],"answer":3,"explanation":"The passage says he guessed that doctors coming from autopsies were carrying something on their hands, and that hand-washing cut deaths. Ventilation, sicker patients and harmful chlorine are not mentioned; the chlorine reduced deaths.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-verbal-placement-567","question":"Critical reasoning. A city says that its new bike lanes have made cycling safer, because the number of cyclists injured fell by 30% in the year after the lanes opened.\nWhich of the following, if true, most seriously weakens the city's claim?","options":["The bike lanes cost less than the city had budgeted.","Most of the injuries that did occur happened at night.","In the same year a metro fare cut halved the number of people cycling, so injuries per cyclist actually rose.","Other cities have also built bike lanes."],"answer":2,"explanation":"If cycling halved while injuries fell only 30%, each cyclist became more likely to be hurt, so the raw fall does not show greater safety. Cost, the timing of injuries and other cities do not bear on whether the lanes made cycling safer.","difficulty":"very-hard","source":"CAT VARC · Accenture"},
  {"id":"apt-verbal-placement-568","question":"Critical reasoning. In a study of 500 firms, those offering flexible working hours had lower staff turnover than those that did not. But when firms of the same industry and size were compared with each other, the difference disappeared.\nWhich conclusion is best supported?","options":["Flexible hours cause staff turnover to rise.","The apparent link between flexible hours and low turnover may reflect industry and firm size rather than the policy itself.","Firm size has no effect on staff turnover.","Flexible hours are offered only by large firms."],"answer":1,"explanation":"A difference that vanishes once industry and size are held constant suggests that those factors, not flexible hours, drove the original gap. Nothing shows flexible hours raise turnover, and the data imply that size or industry does matter.","difficulty":"very-hard","source":"CAT VARC · Product company OA"},
  {"id":"apt-verbal-placement-569","question":"\"All certified auditors have passed the qualifying exam. Ravi has passed the qualifying exam. So Ravi is a certified auditor.\"\nWhich argument has the same flaw?","options":["All roses are flowers. This plant is a flower. So this plant is a rose.","All roses are flowers. This plant is a rose. So this plant is a flower.","No rose is a weed. This plant is a rose. So this plant is not a weed.","If it rains, the match is off. It is raining. So the match is off."],"answer":0,"explanation":"The original reasons from 'all A are B' and 'x is B' to 'x is A', which does not follow, since other things can be B too. The rose argument makes the identical move. The other three arguments are valid.","difficulty":"hard","source":"TCS NQT · CAT"},
  {"id":"apt-verbal-placement-570","question":"Read the passage and choose the option that best summarises it.\n\nPassage: In countries where tipping is customary, a waiter's earnings depend heavily on customers' moods, the weather and even the waiter's appearance, none of which has much to do with service. Studies of restaurant bills find that tip sizes change only slightly with the quality of service customers report. A system meant to reward good service ends up mostly rewarding things the waiter cannot control.","options":["Waiters should be paid only through tips.","Tipping, meant to reward good service, mostly reflects factors unrelated to service.","Customers tip more when the weather is bad.","Good service is impossible to measure."],"answer":1,"explanation":"The passage lists unrelated factors that drive tips, notes their weak link to service quality, and concludes the system rewards the wrong things. It does not recommend tips-only pay, state the direction of the weather effect, or claim service cannot be measured.","difficulty":"hard","source":"CAT VARC · Infosys"},
  {"id":"apt-verbal-placement-571","question":"You want a senior colleague to review your draft report before it goes to the client. Which message is most appropriate?","options":["Review this today, it's urgent.","Could you possibly glance at my draft sometime, if you are free, no pressure at all?","Would you be able to review the attached draft by Thursday? Your view on the cost section in particular would be very helpful.","I have attached the report. Let me know."],"answer":2,"explanation":"The third message is polite, gives a clear deadline and says what feedback is wanted. The first is curt and demanding; the second is so tentative that it sets no deadline; the last does not actually ask for a review.","difficulty":"moderate","source":"Accenture · Capgemini"},
];

export default questions;
